window.QUIZ_LOCAL = (window.QUIZ_LOCAL||[]).concat([{"q":"○○○ 법당의 주존불로써 양측에 관음과 세지를 협시로 한 삼존불의 형태로 봉안되어 있다. 양측의 불상은 양식적인 특징이 본존불과 달라 다른 작가에 의해 조성되었음을 알 수 있다. 군의자락의 도드라진 면이나 뒷면 대의 끝단 등에 도금이 탈락되어 있으며, 이를 제외하면 상태는 비교적 양호하다. 복장공은 상의 저부바닥으로부터 비스듬이 파내고, 무릎정도의 높이에서 입구가 二段으로 이루어진 좁고 깊은 방형의 복장공이 마련되어 있으며, 복장공이 열려 있은 이유 때문에 목좌대를 최근에 와서 덧붙인 것으로 추정된다.","a":"밀양 부은사 석조아미타불좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643094.jpg"},{"q":"18세기 불화의 전통을 계승하고 있는 탱화로 19세기 중후반 전라도와 경상도에서 활발한 활동과 함께 많은 작품을 남기고 있는 작품세계를 살펴볼 수 있다. 1981년 화재로 대웅전이 전소되면서 삼존불과 후불탱, 괘불탱 등 많은 성보가 소실된 후 각 전당이나 요사 내에 남아 있는 성보자료 등을 지금의 임시 수장고에 보관하고 있다. 보관된 성보 중 주존지장탱과 10위의 시왕탱 중 7위 만 양호한 상태로 보존되어 있다.","a":"남해 화방사 지장시왕탱","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020041114233500.jpg"},{"q":"괴정은 영조 42년(1766)에 괴정 남준형이 지은 정자로, ‘경목재(景牧齋)’라 하며 지내던 곳이다. 남준형 선생은 벼슬에 뜻을 두지 않고, 경전과 역사 연구에 전념하면서 후학을 키우는데 여생을 보냈으며, 마을 사람들을 위해 힘써 칭송을 받았다. 남준형의 『괴정유사(槐亭遺事)』와 남용만의 『괴정기(槐亭記)』, 남효채의 『괴정중건기실(槐亭重建記實)』에 기록이 남아 전하고 있다.","a":"괴시리괴정","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663286.jpg"},{"q":"전라남도 강진군 강진읍 만덕산에 있는 ○○○ 대웅전 안에 모셔진 삼존불(三尊佛) 가운데 본존불이다. 이 불상은 강진군 대구면 용운리에 있는 정수사에서 1951년에 옮겨 온 것이라고 전해진다. 사각형의 얼굴은 고개를 앞으로 숙이고 있으며, 두툼한 옷을 걸친 어깨는 각을 이루고 있어 다소 경직된 느낌을 주고 있다. 무릎 위에 올린 두 손은, 오른손은 손끝을 땅을 향하게 하고 왼손은 배꼽 부근에서 손바닥을 위로 향하게 하고 있다. 왼손은 별도로 만들어 끼운 것이며, 손목 끝부분에 ‘석가(釋迦)’라고 써서 이 불상이 석가여래를 표현한 것임을 알 수 있다.","a":"강진옥련사목조여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640122.jpg"},{"q":"○○○○○ 책판은 조선중기 문신인 大庵 朴惺(1549-1606) 선생의 문집인『大庵集』의 목판으로, ○○○○ 사후 선생이 지은 글을 모아 숙종 5년(1679) 李元禎이 序를 지었으며 대암의 증손 世熙에 의하여 편집, 간행되었다. 문집은 6권 4책이며 권1(目錄·詩), 권2(祭文·雜著), 권3(書·墓誌銘), 권4(疏), 권5(行狀·輓詞·祭文), 권6(祭文·墓碑銘)으로 구성되어 있다.","a":"대암선생문집책판","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636939.jpg"},{"q":"이 불화는 1870년에 경선 응석(慶船 應釋)과 봉감(奉鑑),자한(自閒), 체훈(軆訓)이 그린 개운사 ○○○○○를 초본으로 하여 혜산축연에 의해 제작된 것이다. 혜산축연(惠山 竺演)은 19세기 후반 ~ 20세기 전반 강원도와 경기도지역을 중심으로 활동하던 화승으로 금강산의 신계사, 유점사를 비롯한 강원도 일대의 사찰들과 흥천사, 봉림사 등 경기지역 사찰의 불화를 많이 조성한 화승이다. 그는 서울지역에서도 활발하게 불화를 제작하여 현재 서울에서 조성한 작품은 20여 점이 남아있는데, 그중 1887년 ○○○ 불화 제작시에는 수화사(首畵師)로 활동하면서 불사를 주도하였다.","a":"경국사 지장시왕도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"성북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2594743.jpg"},{"q":"○○○은 조선시대 구산포에서 울릉도로 가던 수토사들이 순풍을 기다리며 머물렀던 건물이다. 이 건물의 정확한 건립연대는 확인할 수 없으나 구산동사 중수기에 의하면 1851년(철종 2년) 중수하고 ○○○이란 현판을 걸었다는 기록이 남아있다. 이 건물은 정면(남쪽) 4칸, 우측면(서쪽) 4칸, 좌측면(동쪽) 3칸의 일자형 팔작집으로 동해안 해변의 작은 포구 구산리 마을 중심부에 남향으로 자리 잡고 있으며, 현재 마을 주민들의 집회장으로 이용되고 있다.","a":"울진 대풍헌","c":"시도기념물","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654713.jpg"},{"q":"조선후기 청화백자 항아리이다. 구연은 곧고 높으며 어깨가 팽창되다가 저부로 가면서 좁아들다가 굽 부분에서 약간 벌어진 형태이다. 유색은 담회청색을 띠며 전체적으로 용융이 잘되어 광택이 좋다. 구연부 바깥쪽과 구연부와 어깨의 경계부위에는 각각 1줄의 청화선을 둘렀다. 어깨에는 여의두문을 돌렸으며 그 밖의 장식문양은 없다. 동체 전면에는 앞뒤로 한 쪽에는 파초가, 다른 한쪽에는 대나무가 심겨진 장탁자 위에 놓인 화분을 그렸으며, ○○○ 사이에는 매화문을 그렸다. 청화는 농담을 이용하여 변화 있게 채색하였다.","a":"백자청화화분문호","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636469.jpg"},{"q":"남평 문씨의 종가로 약 300년 전에 지은 건물이며 안동지방의 전형적인 평면구성을 취하고 있다. 지금 있는 건물은 임동면 ○○○에 있던 것을 임하댐 건설로 1988년 옮긴 것이다. 앞면 3칸·옆면 2칸으로 중앙 앞쪽에 흙바닥을 그대로 둔 봉당이 있고 그 뒤에 마루가 놓여있다. 마루 왼쪽에 안방, 오른쪽에 상방이 있다. 봉당의 왼쪽에는 부엌, 오른쪽에는 외양간과 그 위에 다락이 설치되어 있다. 벽은 온돌방만 흙으로 하고, 나머지는 널판으로 되었다. 지붕은 기와로 덮었으며 집안의 연기가 빠져나갈 수 있는 ○○○○이라 부르는 구멍을 내었다.","a":"안동마령동기와까치구멍집","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658748.jpg"},{"q":"고려 후기의 문신 연담 ○○의 ○○이다. ○○○○○는 본래 충청북도 ○○시 청원구 북이면 대율리에 있던 것을 1975년 국토개발지구로 지정됨에 따라 지금 위치로 옮겼다. ○○는 본관은 ○○이고 자는 선갑先甲, 호는 연담으로 1255년(고종 42) 문과에 장원급제하여 첨사부녹사詹事府錄事·국자감대사성國子監大司成·감찰대부監察大夫 등의 관직을 지냈다. 고려 원종 때 왜구 침범을 꾸짖고 납치해간 고려인의 송환을 요구하기 위하여 일본에 사신으로 다녀오기도 했다. 충렬왕 때 원나라 황제의 생일 축하사절단으로 원나라에 갔다 돌아오는 길에 별세하였다.","a":"청주 곽예 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649388.jpg"},{"q":"○○은 승려의 사리를 봉안한 탑으로, 부도 또는 사리탑이라고도 불린다. ○○○○○은 누구의 사리를 모신 것인지는 확인되지 않았으나, 일반적인 ○○과는 구별되는 독특한 구조를 지니고 있다. 기단부는 전체적으로 높이가 다소 높은 편이며, 바닥의 지대석 위에 팔각형 하대석을 두 층으로 올려 구성되었다. 아래쪽 하대석은 문양 없이 단순한 형태이고, 위쪽 하대석에는 각 면을 선으로 나누고 꽃무늬가 정교하게 새겨져 있다.","a":"합천 청강사 승탑","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2761446.jpg"},{"q":"○○○○ 내에 자리하고 있는 비로, 서원을 세우게 된 배경과 위패를 모신 사계 김장생(1548∼1631) 선생의 행적 및 사원의 구조 등에 관해 적고 있다. ○○○○은 김장생의 학문과 덕행을 기리고자 지방의 유림들이 뜻을 모아 건립하였으며, 대원군의 서원철폐령이 내려졌을 때도 폐지되지 않았던 47개 서원 중의 하나이다. 김집·송준길·송시열 선생의 위패를 함께 모셔두어 매년 2월·8월에 제사를 지내고 있다. 비는 높직한 사각받침돌 위로 비몸을 세우고 지붕돌을 올린 모습으로, 조선 현종 10년(1699)에 세운 것이다.","a":"돈암서원 원정비","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661533.jpg"},{"q":"○○○는 학생들의 공부를 위해 사용되던 집이다. 처음에는 조선 정조 2년(1778)에 대사성인 서정공 박문현이 살림집으로 세운 건물이나, 정조 24년(1800) 경에 도곡 박종우의 공부방으로 사용되면서 그의 호를 따서 ○○○라는 이름을 붙였다. 앞면 4칸·옆면 1칸 규모이며, 후대에 퇴칸을 달고 대청을 넓혀 누(樓)처럼 꾸몄다. ○○○는 태백산지역 살림집의 일반적인 구조를 가지고 있는 소박한 건물이다.","a":"도곡재","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636899.jpg"},{"q":"경상북도 김천시 대항면 ○○○의 박물관에 보관되어 있는 ○○○○으로 화강암으로 만들었다. 높이 45㎝, 무릎 폭 28㎝의 아담한 크기로, 본래 서운선사의 원불(願佛)로 전해진다. 호랑이를 어르는 모습에서 당당한 기품과 사실적인 표현기법이 돋보인다. 전체적인 모습으로 보아 고려시대 문화의 절정기인 인종(재위 1123∼1146), 의종(재위 1147∼1170) 때에 만들어진 것으로 추정된다.","a":"직지사석조나한좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640958.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 언제 지었는지 정확히 알지 못하나, 양성산 아래에 있던 것을 광해군 1년(1609)에 다른 곳으로 옮겼다가 숙종 9년(1683)에 지금의 위치로 옮겼다고 한다. 고종25년(1888) 문의현이 ○○로 폐합되면서 없어졌다가 1893년 문의현이 복구된 후 이듬해 다시 세웠다. 1906년 ○○향교에 합쳤다가 1925년 크게 중수하여 복구하였다. 현재의 건물들은 1980년에 다시 짓고 1988년에 보수한 것이다.","a":"청주 문의향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638533.jpg"},{"q":"높이 35센티미터의 화강암 탑신석 위에 9층의 점판암제 옥개석이 올려져 있다. 평면 정사각형이며 초층 및 2층 옥개석 하면에는 연판문이 장식되어 있으며 그 이상은 각형 층급받침을 새기고 있다. ○○ 지역에서는 다른 예가 없으며 전국적으로도 몇 기 안되는 청석탑으로 규모는 작으나 공예품과 같은 아름다움을 지니고 있다.","a":"충주 창룡사 다층청석탑","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660822.jpg"},{"q":"계초심학입문(誡初心學入文), 묘법연화경 권제1(妙法蓮華經 卷第一) 등 10책 모두 370년이 넘은 고전적(古典籍)이며, 불교사의 희귀 자료이다. 2004년 성주사 안심료(安心寮)에 임시 봉안된 불상을 지장전 건립과 함께 이전하여 개금(改金) 및 개채(改彩)하면서 지장보살불의 복장유물을 확인한 결과 지장보살과 시왕을 비롯한 권속일체가 1681년 신조된 사실과 조성한 화원 및 시주자 명단이 열거되어 있으며, 당시 성주사의 명칭이 웅신사(熊神寺, 곰절) 임을 알 수 있다.","a":"달마산사적 미성책","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018102913454700.JPG"},{"q":"고려말 조선초의 부윤(府尹:종 2품의 관직)인 전득우 장군의 묘소이다. 세종 9년(1427) 당시 의금부제조에 재직 중이던 아들이 나라에 큰 공을 세워 원종공신이 되었으며, 그 부친에게도 가선대부 한서부윤의 벼슬이 내려졌고 왕이 직접 묘비를 하사하였다. 사각으로 다듬은 화강암으로 봉분의 아래쪽을 둘렀으며, 봉분 주위에는 2단의 낮은 돌담을 쌓았다. 앞쪽에 서 있는 묘비에는 원래는 부인의 묘인데 전득우가 늦게 죽었으므로 후에 합장하였다는 내용을 적고 있다.","a":"전득우묘","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651975.jpg"},{"q":"○○○○○는 담장을 사이에 두고 있는 최감찰댁(1892)과 비슷한 시기에 건축된 것으로 추정되며, 안채, 광채, 사랑채, 문간채로 이루어져 있다. 안채는 정면 6칸, 측면 2칸의 초가집으로 초가로서는 규모가 매우 크다. 사랑채는 지정 당시에는 없었으나 2009년 자료를 고증해 복원하였으며 정면 3칸, 측면 2칸, 홑처마, 우진각지붕 건물이다. 광채는 정면 8칸, 측면 1칸 홑처마 건물이다","a":"보은 최재한 고가","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660792.jpg"},{"q":"이 건물은 선산 김씨(善山 金氏) 문충공파(文忠公派)의 종택으로 안채는 1800년경에 건립, 1878년에 중수하였고, 사랑채는 1812년에 건립된 것으로 추정된다. 문충공(文忠公) 점필재 김종직 (金宗直, 1431～1492)은 고려 말 정몽주․길재의 학통을 이은 아버지 김숙자(金叔滋)로부터 학문을 익히면서 조선시대 도학의 정맥을 계승하였다. 조선 성종(成宗)때에는 도승지(都承旨), 예조참판(禮曹參判) 등을 역임하면서 왕의 총애를 받았다.","a":"점필재종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"고령군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658707.jpg"},{"q":"조선 중기의 문신이며 충절인 지소(芝所) 황일호(1588∼1641) 선생의 묘소이다. 조수륜의 가르침을 받았고, 인조 13년(1635) 문과에 급제한 후 여러 관직을 두루 역임하였다. 인조 14년(1636) 병자호란이 일어나자 인조를 남한산성으로 안전하게 모신 공으로 진주 목사에 올랐다. 인조 16년(1638) 의주 부윤으로 있을 때 청나라를 배척하고 명나라를 돕자는 모의를 하다가 청나라 병사에게 피살되었다.","a":"황일호의묘","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661072.jpg"},{"q":"○○○는 신라 선덕여왕 15년(646) 자장율사에 의해 창건되었다. 영축산은 부처님 당시 마가다국 왕사성의 동쪽에 위치한 산 이름이다. 이 산의 모양이 불법을 직접 설하신 인도 영축산과 통한다 하여 ○○○라 한다. 또한 승려가 되려는 사람은 모두 부처님의 진신사리를 모신 금강계단에서 계를 받아야 한다는 의미에서 ○○○라 한다. 대웅전은 본래 석가모니를 모시는 법당을 가리키지만, ○○○의 대웅전에는 불상을 따로 모시지 않고 건물 뒷면에 금강계단을 설치하여 부처님의 진신사리를 모시고 있다.","a":"양산 통도사","c":"시도기념물","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019050316274700.JPG"},{"q":"금오산 자락 아래 해발 약 230m 지점의 능선에 위치하고 있는 국사골 ○○○○는 남산 동쪽 남산 순환도로 입구에서 오른쪽으로 나 있는 등산로를 360m 정도 올라가다 북쪽으로 난 계곡을 건너 다시 소로를 따라 북쪽 산등성이를 향해 약 300m쯤 올라가면 나타나는 대숲을 지난 지점에 위치한다. 이곳은 고깔바위 아랫부분에 해당하며, 서남쪽으로는 南山 浮石이 건너다보인다. 절터에는 모두 7개의 축대가 불완전하게 남아 있으며, 5개소의 건물지가 확인되었다. ○○○○은 이 절터의 가장 높은 지점에 서 있다.","a":"경주남산 국사곡 제4사지 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641256.jpg"},{"q":"○○○○은 북으로 천안, 청주는 물론 아산만을 한눈에 내려달 볼 수 있는 중요한 군사적 거점지역에 축조하였다. 축조시기는 백제시대로 660년 백제가 멸망하고 풍왕과 복신, 도침장군을 선두로 일어났던 백제부흥운동군의 최후의 구국 항쟁지로 알려져 있다. 「신증동국여지승람」전의현 고적조에 간단한 설명이 나와 있는데 이 기록에 의하면 조선초기에는 이미 폐성되어 있었다는 기록이 남아 있다. ○○○○은 내성과 외곽성이 함께 갖추어져 있으며 성내에서 백제시대 기와편이 출토되고 있다.","a":"운주산성","c":"시도기념물","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1797151.jpg"},{"q":"‘○○○○○’는 조선 시대의 학자인 김안국(金安國, 1478년-1543년)의 학문과 덕행을 기억하기 위해 세워진 서원이 있던 곳이다. 서원은 1580년에 세워졌으며, ‘기천’이라는 이름은 1625년 임금으로부터 사액(賜額; 조선 시대에 임금이 사당이나 서원 등에 이름을 지어 새긴 편액(扁額)을 내리던 일) 받은 것이다. 서원은 임진왜란(壬辰倭亂; 1592년-1598년까지 2차에 걸친 조선과 일본과의 전쟁) 때 불타 없어졌다가 복원되면서, 김안국을 포함하여 총 8명[이언적, 홍인우, 정엽, 이원익, 홍명구, 이식, 홍명하]을 모셨다.","a":"기천서원지","c":"문화유산자료","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660094.jpg"},{"q":"○○○의 뒤뜰에 따로 마련된 곳에 있는 2기의 ○○으로 동쪽과 서쪽 방향에 세웠다. 원래의 자리는 알 수 없으나 비교적 온전한 형태를 갖춘 모습이다. ○○○는 신라 48대왕 경문왕때 자정선사(慈淨禪師)가 수도하던 암자에 경문왕이 선사의 인물됨을 알고 국사(國師)의 존호(尊號)와 주석(住錫)하는 절에 ○○○의 이름을 지어 ‘○○○’라 쓴 현판을 내렸다고 전한다. 조선 정종 원년에 함허당(涵虛堂) 득통화상(得通和尙)이 폐사된 절을 중창하고 주석하였으며, 이후 인조때 중창하였다. 1965년 극락전과 요사를 중건하였고, 1981년부터 13년간 탄성스님이 중건하였다.","a":"괴산 공림사 승탑","c":"문화유산자료","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019041916513000.jpg"},{"q":"명나라『태조실록』과『대명회전』에 잘못 기록된 조선왕가의 계보를 영조 20년(1744)에 와서 바로 잡게된 것을 축하한 시를 모아 ○○에 새긴 것이다. 크기는 가로 58cm, 세로 30cm이며, 수량은 22매이다. 이는 조선 태조 이성계가 고려 문신 이인임의 아들로 중국 사서에 잘못 기록되어 조선 전기부터 선조 17년(1584)까지 이를 고치기 위해 여러 차례 사신을 파견해왔으나 명나라에서는 계속해서 이를 거절하고 있었다.","a":"광국지경록 목판","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020082411205900.jpg"},{"q":"○○군 대병면 대지리 산 2번지 일원은 발굴조사 결과 건물지 16동, 축대 배수로, 괘불지주 등의 유구가 확인되었으며 출토된 기와, 자기류등을 통해 볼 때 12세기에 건립되어 18세기까지 사용되었을 가능성이 높으며 17세기 초반에서 후반경에는 실체 사찰의 기능을 수행하였음을 확인하였다. 발굴결과 수차례에 걸친 수.개축이 있었음을 확인할 수 있었으며 고려시대 전기에서 조선시대 후기에 걸쳐 운영된 사찰로 판단되고 있다.","a":"합천 무학대사 유허지","c":"시도기념물","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657509.jpg"},{"q":"총 높이 120cm, 구경 75cm의 크기로 조선후기 ○○ 중에서는 비교적 대형에 속한다. 명문(銘文)에 의하면 1782년(정조 6)에 만들어졌다. 전체적으로 종의 몸체는 위가 좁고 아래로 갈수록 넓어지는데 중앙 부분부터 거의 직선으로 내려오는 형태이다. 종의 정상부에는 하나의 몸체로 이어진 쌍용의 용뉴(龍鈕)가 있다. 종의 몸체에는 상 ·하대가 생략된 대신에 몸체 중앙에 둘러진 굵은 줄을 기준으로 상하로 구분한 뒤 상부엔 범자문(梵字圓文)과 연곽(蓮廓), 보살입상(菩薩立像)을 두었다. 보살입상은 둥근 두광(頭光)에 합장한 자세로 연꽃위에 서 있는 모습이다.","a":"안성 칠장사 범종","c":"시도유형문화유산","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637808.jpg"},{"q":"이 문건(文件)은 오늘날 서울에 편입되었으나 조선시대에는 도성 밖에 있던 ○○○에 둔진(屯鎭)을 처음으로 설치하고 둔진(屯鎭)의 주민에게 포역(曝役)․훈업(燻業)을 맡게 한 사실을 밝힌 비변사의 문안(文案)과 훈련도감의 문적(文蹟)을 1805년(純祖 5년) 6월 재작성하여 발급한 완문(完文)과 그 세부사항이 기록된 절목(節目)이다.","a":"성북동포백훈조계완문절목","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590510.jpg"},{"q":"○○○은 조선 인조 때 이조판서와 대제학을 지낸 우복 정경세(1563∼1633)가 편찬한 아동용 수신 교과서이다. 이 책은 우복 정경세 자신이 나이 여덟살 되던 해에 아버지의 가르침을 받아가며 소학서로 윗사람에게 겸손하고 온순하는 방법을 배우고 이를 행하려 했으나 그리하지 못한 것을 후회하면서 자기 아들만은 자기의 전철을 밟지 않도록 하기 위하여 뛰어난 유학자의 『향교예집』가운데 「동자예편」을 약간 손질하여 어린이들이 쉽게 깨닫도록 만든 것이다. 선조 37년(1604)에 정경세 자신이 직접 손으로 써서 만든 것이다.","a":"양정편","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636313.jpg"},{"q":"○○○는 조선 중종 17년(1522)에 신월스님이 지은 절이다. 원래는 고려 광종(재위 949∼975) 때 법인대사가 삼각산 부허동에 보덕암을 짓고 이어져 내려오던 것인데, 신월이 지금의 자리로 옮겨 크게 짓고 ○○○라 이름지었다. 그 후 광해군 10년(1618)의 큰 화재와 오랜 세월로 인해 건물이 퇴락하자, 고종 3년(1866) 흥선대원군의 시주로 다시 지었다. 1933년 조선어학회 주관으로 한글 맞춤법 통일안을 위해 이희승·최현배 등의 국문학자 9명이 기거하며 집필한 곳이기도 하다.","a":"화계사 대웅전","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636215.jpg"},{"q":"지금까지 전국에서 발견된 ○○은 일시적인 것만 남아 있는데 ○○○○○은 임란 직후부터 일제시대나 해방 이후까지 수백 년○○네 걸쳐 많은 양의 ○○이 잘 보존되어 있다. 이러한 점은 우리나라에서도 사례가 많지 않은 경우에 속한다. 이에 ○○○○○을 통해서 조선시대 중기이후 ○○지역의 자율적인 향약시행의 전통이 어느 곳보다 강했다고 할 수 있는 소중한 자료이므로 문화유산으로 지정하여 보존할 가치가 있다.","a":"의령 화양리 동안","c":"시도유형문화유산","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642458.jpg"},{"q":"○○○○는 태조 원년(1392) 관의 교육진흥책에 따라 설립되었다고 보여지나, 임진왜란 때 소실되었다가 1605년(선조 38)에 동래부사 홍준이 재건할 때 향교의 가장 중심건물로 건립되었다. 그 후 유생들의 건의에 따라 학소대 아래, 동래고등학교 부근, 인생문 부근 등 수차 이건 중건되었으며, 순조13년(1813)에 동래부사 홍수만이 현 위치인 성 서쪽 복호대(伏虎臺) 아래 양좌(良坐)로 이건하였다. 1987년 9월 도리이상을 해체·보수하였고, 2010년 9월 주초이상 해체·보수를 거쳐 2011년 8월 단청 및 수지처리를 완료하였다.","a":"동래향교 대성전","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"동래구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636615.jpg"},{"q":"평산 신씨가 거주하는 오래된 집으로 만괴헌이란 이름은 현 소유주의 6대조 신재수의 호를 따서 붙인 이름이다. 원래 이 건물은 야성 정씨 저택이었으나, 순조 15년(1815) 이수민이 사들였고 그 뒤 헌종 9년(1843) 신재수가 다시 사들인 것이다. 지금 있는 건물은 현 소유자의 고조할아버지인 신의영이 확장하면서 고쳐 지은 것이다.","a":"영덕만괴헌","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662836.jpg"},{"q":"○○○ 극락전 오른쪽에 자리하고 있는 탑으로, 전체의 무게를 지탱하는 기단(基壇)을 2층으로 두고, 그 위로 3층의 탑신(塔身)을 올려놓은 모습이다. 기단은 각 층의 4면마다 기둥 모양을 본떠 새겼는데, 아래층은 면의 모서리와 가운데에, 위층은 모서리에만 두었다. 특히 아래층에는 기둥조각으로 나뉜 8곳에 안상(眼象)을 세밀하게 새겨 장식하였다. 탑신은 각 층의 몸돌과 지붕돌이 각각 하나의 돌로 이루어져 있고, 몸돌의 모서리마다 기둥 모양을 새겨 놓았다.","a":"무위사삼층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662010.jpg"},{"q":"태봉산 남쪽의 언덕에 위치한 무덤들이다. 원래는 100여기 이상의 무덤이 있었던 것으로 보이나, 개간과 도굴로 대부분 파헤쳐져 지금은 능선을 따라 2∼3기만 확인할 수 있다. 봉분의 규모는 외형상 대형이 지름 25∼30m·높이 6∼8m이며, 중형은 지름 15∼20m·높이 4∼5m, 소형은 지름 10m 내외, 높이 3m 정도이다. 내부는 돌로 돌방(석실)을 만들고 천장을 좁혀 뚜껑돌을 덮고, 입구와 통로가 있는 앞트기식돌방무덤(횡구식석실분)이라 생각된다.","a":"산청 생초고분군","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654743.jpg"},{"q":"강익(姜瀷)에서 강관수(姜寬秀)에 이르기까지 7대 185년간(1723∼1908)에 걸치는 호구단자·준호구·신호적 등 30매, 의인 남원양씨 정려각 중수 상량고유문 1매, 1646∼1649 사이의 강승(姜昇)의 교지 3매, 강수제(姜壽齊)의 별가교첩(別加敎牒) 2매, 간찰 1매 등 모두 37매이다. 강익에서 강관수에 이르기까지 7대 185년간(1723∼1908)에 걸치는 호구단자(20)·준호구(8) 및 신호적(2) 등의 자료들에는 다른 문중의 자료에서 볼 수 없는 특이한 내용들이 담겨 있다.","a":"진주강씨 고문서","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664799.jpg"},{"q":"○○○ 내의 우물 옆에 놓여 있는 것으로, 원효대사를 기리는 비의 받침돌이다. 낮은 직육면체의 모습을 하고 있는데, 네 모서리가 떨어져 나가 많이 훼손되었다. 윗면에는 비를 꽂아두기 위한 홈이 파 놓았고, 옆면에는 옅은 안상(眼象)을 새겼다. 고려 명종대(1170∼1197) 한문준이 건립한 ○○○○○의 대석이 남아있는데, 원효대사를 위한 비석이나 시호(諡號 : 죽은 이의 덕을 기리어 붙여주는 호)가 없음을 애석하게 여긴 왕이 ‘대성○○○○’라는 시호를 내리고 비석을 세우도록 하였다.","a":"분황사화쟁국사비부","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640425.jpg"},{"q":"호남창의동맹소 의병대장 이석용의 생가이며, 임실군 성수면 삼봉마을에 위치하고 있다. 1870년대에 지은 생가는 정면 3칸, 측면 2칸의 전형적인 민가로 왼쪽부터 부엌, 마루와 방, 오른쪽 방으로 이루어져 있다.이석용(李錫庸, 1878~1914)이 태어나 25세 즈음 태평리로 이사하기 전인 1903년까지 살았다. 이석용(李錫庸, 1878~1914)은 임실군 성수면 삼봉리(三峰里) 출신으로 본관은 전주, 자는 경항(敬恒), 호는 정재(靜齋)이다. 1907년 8월 26일 집을 떠나 9월 12일 마이산 아래 용암에서 창의하여 호남창의동맹 의병대장으로 추대되었다.","a":"이석용생가","c":"시도기념물","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653649.jpg"},{"q":"1915년 안세화 주교가 로버트 신부의 도움을 받아 지은 ○○○이다. 1912년 안세화 주교는 로버트 신부를 도우면서 프랑스 ○○○로 수녀회에 고아와 노인을 돌보고 의료사업을 담당할 수녀의 파견을 요청하였다. 1914년 수녀의 파견이 결정되자 ○○○ 건축에 착수하여 다음해인 1915년 ○○○○의 준공과 함께 대구 ○○○○○로 ○○○이 건립되었다. 건물터는 대구 국채보상운동의 주역이었던 천주교 신자 서상돈이 기증하였고, 건물 설계는 로버트 신부가 하였으며, 건축공사는 중국인들이 담당하였다.","a":"샬트르성바오르수녀원코미넷관","c":"문화유산자료","nc":"","r":"대구광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659482.jpg"},{"q":"○○지역 영양 남씨 시조인 남계조의 묘를 지키기 위해 세운 재실이다. 이곳은 명당으로 건물과 비석, 천연기념물로 지정된 향나무가 질서 있게 자리잡고 있다. 1670년경 세운 것으로 알려져 있으나 확실하지 않으며 17세기 양식을 엿볼 수 있는 부분도 남아 있지 않지만 독특한 지붕 양식을 지니고 있다. 이 지역의 대표적인 재실 건축물로 민속적 가치를 지닌다.","a":"청송 화지재","c":"시도민속문화유산","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658963.jpg"},{"q":"○○○ 폐사지에 있는 석탑으로서 원형을 잃고 있다. 탑의 기단부는 매몰되었고, 옥개석 3매와 탑신 1매만으로 세웠는데, 3층탑으로 추정되며, 탑의 양식으로 보아 고려시대 것이다. 잔존한 탑신에는 문비가 4면에 새겨져있다.","a":"김해 안곡리 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641372.jpg"},{"q":"○○○○○은 사적 제137호로 지정된 ○○○○○ 지석묘 주변, 해발 50m 내외의 낮은 구릉과 평지에 모두 16기의 고인돌이 분포하고 있다. 평지에는 사적 제137호인 ○○○○○ 지석묘와 탁자식 고인돌의 고임돌로 추정되는 석재 하나가 세워져 있다. 여기서 북동쪽으로 약 300m 떨어진 솔밭에 덮개돌 밑에 고임돌이 없는 고인돌인 개석식 고인돌 3기가 축조되어 있으며, 사적 제137호의 동쪽 낮은 구릉에는 탁자식 4기와 개석식 고인돌 4기가 분포하고 있다.","a":"강화 부근리 고인돌군","c":"시도기념물","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645659.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 국립교육기관이다. ○○○○는 언제 처음 지었는지 자세한 기록이 남아 있지 않지만, 조선 태조 7년(1398)에 세운 것으로 전한다. ○○○은 17세기 초에 세운 것으로 1907년에 크게 보수하였다. 현재는 제사 공간인 ○○○과 동무, 교육 공간인 명륜당이 남아 있다. ○○○은 앞면 3칸·옆면 3칸의 규모이며, 공자를 비롯한 그의 제자들과 우리나라 성현들의 위패를 모시고 있다.","a":"칠곡향교대성전","c":"문화유산자료","nc":"","r":"대구광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659456.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 광해군 13년(1621)에 처음 지었고, 숙종 원년(1675)에 다시 지었다. 제사 공간인 ○○○은 앞면 3칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다. 안쪽에는 공자를 중심으로 그의 제자와 중국과 우리나라 성현의 위패를 모시고 있다. 조선시대에는 나라에서 토지와 노비·책 등을 지원받아 학생을 가르쳤으나, 지금은 교육 기능은 없어지고 제사 기능만 남아 있다.","a":"흥덕향교대성전","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661726.jpg"},{"q":"○○○은 영남지역에서 재지사족으로 자리 잡고 있는 기호학파의 노론계열인 ○○ 법전의 진주강씨 강재항을 기리는 정자이다. ○○ 법전의 진주강씨는 입향 이래 영남지방의 재지사족과 유대를 강화하면서 중앙정계를 출입하였다. 특히 강재항은 관직에서 은퇴한 이후 향리에서 강학 활동을 하며 삼계서원의 향음주례에 참여하는 등 영남학파의 선비들과 활발하게 교유하고 있어 주목된다. ○○○은 구릉지의 암반 위에 건축된 특이한 정자이며, 소장되어 있는 책판과 현판도 매우 주목되는 문화유산이다.","a":"봉화 뇌풍정","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663782.jpg"},{"q":"사헌부 장령을 지낸 김영수(1446∼1502)가 88세의 늙은 어머니를 즐겁게 해드리고자, 조선 연산군 2년(1496)에 지은 정자이다. 그 뒤 여러 차례 보수하고 1947년에 다시 지음으로써 오늘에 이른다. 삼귀정이라는 이름은 십장생 중의 하나인 거북이와 같이 생긴 세 개의 바위가 정자 마당에 있어서 붙여진 것인데, 어머니의 장수를 기리기 위한 것으로 보인다. 앞면 3칸·옆면 2칸으로 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕으로 되어있다. 4면이 모두 개방된 형태로 주변 경치와 어울려 경관을 더해준다.","a":"삼구정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640711.jpg"},{"q":"신라 애장왕 때 창건된 경남 ○○○○○에 있는 불상이다. 비로자나불(毘盧遮那佛)은 “널리 밝은 빛을 두루 비춘다”[光明遍照]는 ‘빛의 부처’이자, 진리의 부처이다. 비로자나불이 봉안된 법당을 ○○○○ 또는 대광명전(大明光殿)이라 하며, 또 부처의 이름을 따서 비로전(毘盧殿)이라고도 한다. ○○○○○은 원래 성주 법수사(法水寺)에 봉안되어 있던 불상으로, 임진왜란으로 폐사(廢寺)되면서 가야산 용기사(龍起寺)로 옮겨졌고, 다시 절이 폐사되면서 고종 1년(1897)에 서울 화계사(華溪寺) 범운 스님이 ○○○○○으로 옮겨 봉안되었다.","a":"합천 해인사 대적광전 목조비로자나삼존불","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641414.jpg"},{"q":"조선 인조 때의 문신인 ○○○의 행적을 기록한 비이다. 본관은 안정(安定)이고 호는 구포(鷗浦)이다. 인목 대비의 서궁 유폐 사건(西宮幽閉事件)이 일어나자 낙향했다. 1636년(인조 14) 병자호란이 일어나자 단신으로 남한산성에 들어갔으며 관향사(管餉使)가 되어 군량 공급에 큰 공을 세웠다. ○○○는 사각형 받침돌 위에 비신(碑身 ; 글씨를 새기는 부분)을 세우고 지붕돌을 올린 방부개석(方趺蓋石) 양식을 갖추고 있다. 비문은 김상헌(金尙憲)이 글을 짓고 송준길(宋浚吉)이 글씨를 썼으며 전액(篆額 ; 전서체로 비석의 이름을 새긴 부분)은 김수항(金壽恒)이 썼다.","a":"나만갑선생신도비","c":"시도유형문화유산","nc":"","r":"경기도","s":"구리시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637583.jpg"},{"q":"경상북도 영주시 문수면 아산리에 있는 불상으로, 독립된 바위의 동쪽면에 세밀한 부분이 보이지 않을 정도로 얕게 조각되어 있다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 눈·코·입은 윤곽이 희미하고 짧은 목에는 3줄의 삼도(三道)가 뚜렷하다. 옷은 왼쪽 어깨에만 걸치고 있는데, 왼쪽 어깨에서 오른쪽 배부분으로 부드러운 반원형의 옷주름을 표현하였다. 왼손은 자연스럽게 펴서 배 아래부분에 대고 있으며, 오른손은 손바닥이 밖을 향하도록 들어서 오른쪽 가슴 윗부분에 대고 있다. 전체적인 모습으로 보아 신라말 혹은 고려초에 만들어진 것으로 추정된다.","a":"영풍월호리마애석불좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662941.jpg"},{"q":"○○○에 보존되어 있는 그림으로, 석가불의 부탁을 받고 석가불이 입멸(入滅)한 후부터 미륵불이 출현할 때까지 육도(六道)의 중생을 교화한다는 지장보살과 심판관인 시왕(十王)을 함께 그린 탱화이다. 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 비단 바탕에 채색으로 그려진 이 시왕탱은 중앙의 지장보살좌상을 중심으로 그 좌우측에 도명존자와 무독귀왕을 비롯해 시왕·판관·명부사자·동자·동녀·옥졸 등을 배치하고 있다. 세부표현이 매우 치밀하고 정교하다.","a":"양산 통도사 광무3년명 지장시왕탱","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664764.jpg"},{"q":"○○○ 근처 마을 입구의 하천변에 놓여 있는 ○○○○이다. 봉산(封山)이란 나라에서 나무 베는 것을 금지하는 산이란 의미로, 이렇듯 표석을 세움으로써 그 구역의 산림을 보호하고자 하였다. 표석의 형태는 각 면을 잘 다듬은 직사각형의 모습으로, 앞면에 봉산(封山)이라는 글씨가 큼지막하게 적혀 있다. ○○○은 예로부터 황장목(공공건물에 사용하는 양질의 소나무)이 나기로 유명하여 조선 숙종 6년(1680) 봉산으로 지정되었다. 표석을 세운 시기는 ○○○이 봉산으로 지정된 조선 숙종 때일 것으로 추측된다.","a":"황장산봉산표석","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662865.jpg"},{"q":"영천 이씨들이 모여 사는 마을에 있는 집으로 1900년경에 세웠다고 전한다. 건물은 안채, 사랑채, 헛간채, 문간채로 구성되어 있다. 안채와 사랑채는 ㄷ자형을 이루고 있고 그 맞은편에 헛간채가 있어 튼 ㅁ자형 구조를 보인다. 평면 구성이나 기법에서 독특한 점은 보이지 않지만 여러 세대가 함께 살던 모습을 살필 수 있어 좋은 예가 되는 집이다.","a":"의성 점우당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658962.jpg"},{"q":"○○○은 전동면 송성리에 위치하고 둘레 714m, 높이 3∼10m, 폭 2m이다. “철성(鐵城)”이라 불리며, 금성(金城)으로 표기한 바 삼국사기에 금현성이 바로 이 성이다. 금사리쪽에서 정북으로 30리를 뻗은 산맥의 최고봉인 금성산(金城山)에 구축되어 북으로 전의·천안방면, 남으로 금강 일대를 굽어보고 있다. 전형적인 백제산성으로 험준한 지형을 이용하여 견고하게 구축되어 철옹성이다.","a":"금이성","c":"시도기념물","nc":"","r":"세종특별자치시","s":null,"i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1797205.jpg"},{"q":"○○○은 1392년에 고려말 괴산군수, 김해부사 등을 지낸 사복재 권정(1353∼1411)이 고려의 멸망 소식을 듣고 고향에 내려와 지은 정자이다. ○○○이란 고려를 회복한다는 뜻으로 처음에는 안동 임하면 도목촌 북쪽 지어실(현 예안면 기사리)에 세웠으나, 후손들이 1720년에 지금 있는 자리로 옮겼다. 정자는 앞면 3칸·옆면 2칸 규모이며, 마루 4칸·온돌방 2칸으로 구성되어 있다. 평소에는 마루를 개방하지 않고 있지만, 들어 열 수 있는 문을 두어 개방시에 전체가 하나의 공간이 되도록 마무리하였다.","a":"영주동반구정","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663159.jpg"},{"q":"‘○○○’는 소나 말을 이용하여 곡식을 찧는 도정 기구로 ‘연자방아’ ‘연자매’, ‘돌매방아’라고도 부른다. 방아 틀에 연결된 돌을 소나 말이 끌어 돌림으로써 곡물껍데기를 제거하거나 밀을 빻는 농기구로 농촌에서 널리 사용되었다. 둥글고 판판한 돌판 위에 그보다 작고 둥근 돌을 옆으로 세워 얹어 아래위가 잘 맞닿도록 하여 돌리는 방식이다. 즉 요철형태의 두 개의 돌에 집어넣은 곡식이 돌아가는 압력에 눌려 으깨지는 원리다. <○○○○○>는 화강암으로 만들어진 원형의 숫돌과 받침돌인 암돌로 구성되어 있다.","a":"하남시상사창동연자마","c":"문화유산자료","nc":"","r":"경기도","s":"하남시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660115.jpg"},{"q":"조선시대 조대감이 지었다고 전하는 가옥으로 ‘○○○○○’이라는 이름은 현 소유자의 이름을 따서 붙인 것이다. 건물 형태는 안채, 사랑채, 행랑채가 하나로 연결된 ㄷ자형이다. 안채는 앞면 6칸으로 왼쪽에서부터 부엌·안방·대청·건넌방 순으로 되어 있고 건넌방 앞에는 누마루를 설치하였다. 중앙의 사랑채는 방과 부엌을 두었고, 행랑채는 안채보다 길어 서로 어긋나게 자리잡고 있다.","a":"방기옥가옥","c":"문화유산자료","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661329.jpg"},{"q":"○○○은 쌍백을 관통하는 통과도로에 연접하여 서향으로 입지하고 있으며, 일각문과 보호각을 토석혼축담장으로 두른 일반적인 형식의 효자각이다. 정면 1칸, 측면 1칸의 규모이며 배면에만 벽체를 두었을 뿐 나머지 3면에는 모두 살창으로 처리하여 외부에서 들여다 보이도록 하였다. 화강석을 원형으로 다듬은 주초를 놓고 기둥을 세윘는데 기둥은 원형의 굵은 재료를 사용하여 튼실해 보인다. 가구는 대들보 위에 파련대공을 세워 종도리를 받게 한 3량가구 형식으로 부재들은 일반 규격보다 큰 튼실한 재료를 사용하였다.","a":"합천 효정각","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666602.jpg"},{"q":"본 작품은 화면 가운데 지장보살좌상을 중심으로 좌우에 원형두광을 갖춘 도명존자와 무독귀왕을 비롯하여 시왕, 판관, 사자, 동자 등의 권속들이 좌우대칭으로 정연하게 배치되어 있다. 높은 단 위의 백색 연화좌에 결가좌한 지장은 먹선으로 묘사한 투명한 두건을 쓰고, 가슴 위로 올린 오른손에는 보주를 들고 왼손은 무릎 위에 얹고 있다. 대좌 앞쪽에 놓인 석장은 지장의 왼쪽 어깨에 비스듬히 기댄 상태이다. 지장의 협시인 도명과 무독귀왕은 합장한 채로 서있고, 명부시왕은 각각 관을 쓰고 홀을 들거나 혹은 합장, 두루마리를 들고 지장을 향해 서 있다.","a":"남해운대암지장시왕탱","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666282.jpg"},{"q":"전북특별자치도 고창 선운사에 있는 조선 후기의 범종으로 높이 103㎝, 입 지름 93㎝이고, 종을 매다는 고리인 용뉴를 포함한 전체 높이는 129㎝이다. 용뉴는 2마리 용으로 만들었다. 한국 범종의 특징인 소리의 울림을 도와 준다는 용통이 없는 대신, 종 윗면에 1개의 구멍을 뚫었고, 어깨부분에는 2줄의 선을 돌렸다. 선 안쪽으로 글씨를 새겼는데, 조선 순조 18년(1818)에 다시 만든 것임을 알려준다. 몸체 중앙에는 3개의 돌출된 선을 둘러 위와 아래로 구분해 놓았다.","a":"선운사범종","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639406.jpg"},{"q":"○○○ 안에 있는 ○○이다. ○○은 보통 금당이나 탑 앞에 두는데, 이 ○○도 원래는 용화전(龍華殿) 앞에 있던 것을 일제시대에 절내의 종루와 그 자리를 바꿔놓은 것이다. ○○은 3단의 받침 위에 불을 밝혀두는 화사석(火舍石)과 지붕돌을 올린 일반적인 형태로, 각 부재가 8각을 이루고 있다. 받침부분은 가운데기둥을 사이에 두어 아래받침돌에는 엎어놓은 연꽃무늬를, 윗받침돌에는 솟아오르는 연꽃무늬를 새겨 대칭적으로 표현하였다. 화사석은 4면에 네모난 창을 두었는데 창의 가장자리마다 창문을 달았던 10개의 구멍흔적이 남아있다.","a":"범어사 석등","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636646.jpg"},{"q":"이 비석은 우선 그 형태가 특이하다. 비수와 비신을 한 덩어리의 돌로 만들고 양쪽의 측면에 지주석을 대어서 바람과 빗물로부터 어느 정도 비석을 보호할 수 있게 하고 한편으로는 우아함과 함께 권위를 느낄 수 있도록 하였다. 비수를 두 마리의 용이 여의주를 보호하는 형태로 만들되, 여의주가 비수 크기에 비해 상대적으로 커 보이며 두 마리 용의 입으로부터 여의주에 이르기까지가 파여 있어서 여의주가 상대적으로 매우 돋보이게 표현되어 있다.","a":"합천 조언형 묘갈","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642422.jpg"},{"q":"○○○는 통도사에 딸린 절로, 사명대사의 충훈을 추모하기 위하여 세운 ○○○당이 있는 절이다. ○○○은 유명계의 심판관인 시왕(十王)을 모시고 있다고 하여 시왕전(十王殿) 또는 지장보살을 중심으로 모시고 있다 하여 지장전이라고도 한다. 시왕은 죽은 자들의 죄를 심판하는 10명의 지옥왕으로, 일반인에게 널리 알려져 있는 염라대왕은 이 가운데 다섯 번째 왕이다. 지장보살은 불교 구원의 이상을 상징하는 보살로서, 모든인간이 구원을 받기까지 자신은 부처가 되는 것을 미루면서 천상에서 지옥에 이르는 육도(六道)의 중생을 낱낱이 교화시키는 역할을 맡았다고 한다.","a":"밀양 표충사 명부전","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664170.jpg"},{"q":"유허비란 한 인물의 자취를 기리기 위해 세워두는 비로, 이 비는 우탁 선생의 옛 집터를 기념하고 있다. 우탁은 고려 후기의 대학자이면서 성리학의 선구자로, 동방(東方)에서 가져온 『주역』을 1개월만에 터득하였다 하여 ‘역동선생’이라 일컬어지기도 한다. 성균제주에까지 그 벼슬이 이르렀으며, 문예에도 조예가 깊어 늙어감을 한탄하며 지은 『탄로가』는 가장 오래된 시조작품이면서 뛰어난 작품으로 평가받고 있다. 비는 거북받침돌 위로 비몸을 세우고, 맨 위에 머릿돌을 얹어놓은 모습이다.","a":"역동유허비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640281.jpg"},{"q":"○○○ 대웅전 내에 봉안된 ○○○○○는 1970년대 대웅전이 건립된 후 안성 청룡사에서 옮겨왔다. ○○○○○는 가로 241.5㎝×세로 162㎝의 두루마리 형태로 직사각형을 이루고 있으며 제작연대는 화기를 통해 1911년에 그려졌음을 알 수 있다. ○○○○○는 바깥쪽부터 안쪽으로 11개의 동심원이 둘러져 있어 연화장세계를 받치는 11개의 풍륜을 그린 것이다. 그 안쪽에는 물결치는 향수해(香水海)와 대련화가 둘러싸고 있으며, 비로자나불의 정토인 연화장세계를 받치고 있다.","a":"안성법계사화장찰해도","c":"문화유산자료","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660261.jpg"},{"q":"읍성이란 군이나 현의 주민을 보호하고 군사적·행정적인 기능을 수행하기 위해 소재지를 둘러싸은 것을 말한다. ○○○○에 대해서는 『신증동국여지승람』에 돌로 쌓은 성이며, 성의 둘레가 4,070척(1,233m), 높이가 11척(3m)이고, 성 안에 도랑 1개와 우물 4곳이 있었다고 기록되어 있다. 현재 남아있는 성의 둘레는 1,820m이며, 평면형은 서벽이 동벽보다 긴 사다리꼴 형태이다. 서쪽과 북쪽의 성벽은 돌로 쌓았고, 남벽은 흙으로 쌓았으며, 동벽은 흙과 돌을 섞어 쌓았다.","a":"한산읍성","c":"문화유산자료","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661115.jpg"},{"q":"제주도의 고인돌은 한반도와는 달리 청동기시대가 아닌 탐라시대에 만들어진 거석문화유산으로 북방식․남방식․개석식(무지석식)으로 구분된다. 이곳 ○○○의 고인돌은 남방식․개석식 고인돌형식이며 축조시기는 대략 기원전 1세에서 기원 후 1세기경으로 추정된다. ○○○고인돌 1～3호는 ○○○ 1514번지 내 속칭 ?난이머들?에 있으며 3기가 10m 정도의 간격을 두고 삼각 형태로 놓여져 있다. 특히 고인돌 1호는 남방식고인돌의 형식이며, 고인돌 2․3호는 개석식 고인돌 형식이다.","a":"상예동지석묘3호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657717.jpg"},{"q":"남명 조식(1501∼1572)의 학문과 사상을 이해하고 추모하기 위하여 그를 향사하고 있던 ○○○○의 묘정에 세웠던 비석이다. ○○○○은 1576년 가회면의 회현(晦峴) 아래 세워졌다가 임진왜란 때 불탄 회산서원(晦山書院)의 후신으로, 1601년 봉산면에 세워졌던 향천서원(香川書院)이 1609년 사액되면서 얻은 명칭이다. 이 ○○○는 조선 순조 12년(1812)에 세워진 것으로 가로 80㎝, 세로 180㎝, 폭 25㎝이다. 비의 형식은 거북 모양의 비석 받침돌 위에 태극무늬의 직사각형 비몸을 세우고 머릿돌을 얹은 모습이다.","a":"합천 용암서원 묘정비","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664752.jpg"},{"q":"소유자인 김승진의 선조들이 수대에 걸쳐서 살아온 집이다. 정확한 건축연대는 알 수 없으나, 사당채의 기와에 조각된 기록으로 보아 조선 중종 11년(1516)에 지은 것으로 여겨진다. 몸채와 행랑채·사당의 3동으로 이루어졌다. 몸채는 옛 방식에서 많이 나타나는 H자형 평면구조를 이루었다. 사랑방 뒤쪽에 있는 도장방의 배치나 행랑채의 구성 등으로 보아 이 동네 주택 중에서 가장 오래된 집임을 알 수 있다.","a":"묵재고택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658779.jpg"},{"q":"○○면 대교들에는 본래 6기의 고분이 있었다고 전해지나 1960년대 경지정리 사업으로 소멸되고 현재는 3기만 남아 있다. 1호분은 장축 16m, 단축 14.5m, 높이 4.5m이고 2호분은 장축 6.8m, 높이 1.9m이며 3호분은 장축 22m, 단축 19m, 높이 4.9m이다. 오래 전부터 큰 무덤이라는 뜻의 몰뫼, 몰무덤, 말무덤으로도 불러 왔다. 발굴조사 결과 1호분과 3호분은 5세기 후반~6세기 전반에 축조되었는데 이 지역에서 그동안 보이지 않던 새로운 무덤이다.","a":"해남 옥천 '만의총' 고분군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052021565600.jpg"},{"q":"조선후기에 가면 각 마을마다 자제들을 교육하기 위한 서당, 강학당을 건립해 나가는 것이 일반적인 추세였다. ○○○도 이 범주에 속하는 문중자제들을 위한 강학당이다. 역사적인측면에서 ○○○는 옥산에 약 450여년간 세거해온 여강이씨의 대표적인 강학당(講學堂)이라는 점에서 역사성을 부여할 수 있다.","a":"경주 귀후재","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051422400601.JPG"},{"q":"○○○의 옛 터에 남아 있는 3기의 석조물로, 자연석을 깍아 만든 것으로 보인다. 석조는 스님들이 사용하는 물을 담아두는 것으로, 안이 파인 직사각형 모양이다. 석구는 돌의 속을 파내어 그 구멍에 곡식을 넣고 찧던 절구이다. 마애는 곡식을 가는데 쓰이는 맷돌로, 그 크기가 거대하여 옛 ○○○의 규모를 가늠하게 한다. 백제시대의 유물로, 정확한 제작연대는 알 수 없으나 사찰의 창건과 함께 제작된 것으로 추측된다.","a":"용봉사지석조(마애,석구,석조)","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661158.jpg"},{"q":"5현사(五賢詞)라 불리우는 방사량·방귀온·안전·방응현·안창국을 기리기 위한 서원이다. 방사량은 고려말∼조선초의 의원으로 조선 정종 1년(1399)에 간행한 『향약제생집성방 』과 『신찬집성마의방 ·우의방 』의 편집에 참여하였다. ○○○○은 순조 30년(1830)에 세웠으나 흥선대원군의 서원철폐령으로 폐쇄되었다. 그 뒤 서원을 복원하지 못하고 1909년에 후손들이 그 자리에 유허비를 세웠다. 현재 서원이 있던 곳에는 건물은 찾아볼 수 없고 담장만 남아 있다.","a":"유천서원","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661666.jpg"},{"q":"○○○○는 1903년 4월 권혁중이 설립한 교회로, 현 교회당 건물은 그 해 10월에 건립되었다고 하는데 당시의 관련자료나 기록은 남아있지 않다. 이 건물은 우진각 지붕의 단층 목조 한옥 교회당으로 평면은 장방형으로 정면 2칸이고, 측면 4칸이다. 내부 천장은 지붕틀이 그대로 노출된 연등천장이며, 지붕틀은 절충식의 트러스구조이나 구조수법이 다소 조잡하다. 횡칸에는 각각 2개씩의 지붕틀을 설치하여 2개의 기둥이 평보를 받치고 있는데 부재의 치목이 거칠고 결구수법이 격식에 맞지 않아 보이나 전체적으로 자연스러운 구조미를 느끼게 한다.","a":"영천자천교회","c":"문화유산자료","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663491.jpg"},{"q":"이 ○○○의 背面은 배접지로 마감한 후 朱砂로 다라니를 적어두고 있는데 그 동안 관리 소홀로 인해 배접지가 좀의 의한 일부분의 결락과 함께 내부가 완전히 드러나 있기도 하다. 따라서 조사 중 그 속에 복장되었던 腹藏物을 확인할 수 있었다. 복장물 중 紺色 물을 들인 한지 願文 또한 발견되었는데 이 원문에는 緣化秩과 함께 丙申八月日에 조성 봉안하였음을 적어두고 있다. 원문에 표기된 丙申年은 이 ○○○ 양식상 19세기 불화 양식을 보여주고 있으므로 1836년과 1896년에 해당된다.","a":"밀양운주암칠성탱","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666428.jpg"},{"q":"○○○에 딸린 암자인 ○○○ 안마당에 서 있는 탑으로, 원래의 자리를 굳건히 지키고 있다. ○○○이란 벼루를 만들던 점판암을 이용해 만든 탑인데, 이 탑은 화강암으로 이루어진 바닥돌 이외에는 모두 이 재질의 돌이 쓰였다. 탑은 3단의 바닥돌 위에 쌓아 놓았는데, 세울 당시에는 기단(基壇)과 탑신부(塔身部)의 몸돌들이 있었을 것이나 지금은 10개의 지붕돌만이 포개진 상태이다. 지붕돌은 파손이 심하여 곳곳에 작은 돌을 괴어 놓았는데 그 모습이 안쓰럽다. 지붕돌은 밑면에 2단씩의 받침을 두었으며, 윗면에 느린 경사가 흐른다.","a":"동화사염불암청석탑","c":"시도유형문화유산","nc":"","r":"대구광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636877.jpg"},{"q":"○○○은 조선 순조 1년(1801)에 용암 임석형(1751∼1816) 선생이 바위 위에 지은 정자이다. 임석형이 지은 『○○○ 창건기』와 이휘준의 『중수기』에 기록된 내용을 보면 고종 1년(1864)에 보수 공사한 것으로 되어 있다. 정자 규모는 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 중앙에 방 1칸을 만들어 마루 아래에서 불을 땔 수 있게 하였고, 둘레에 난간을 설치하였다.","a":"거창 용암정","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664485.jpg"},{"q":"수열평 마을에 자리하고 있는 비로, 조선시대 중기의 오씨 부인이라는 여인의 절개를 기리고 있다. 선조 30년(1597) 정유재란이 일어났을 때 장수지방에 침입하였던 왜적들이 집집마다 약탈을 하며 불을 지르기도 하면서 부녀자들을 겁탈하는 일이 잦았다. 화평 마을에 살고 있는 양사무의 부인 오씨부인은 아침에 들이닥친 왜적들에게 가슴을 잡히는 등 모욕을 당하게 되자, 자신의 가슴을 칼로 베어 그들의 얼굴에 뿌리면서 “짐승만도 못한 오랑캐들아! 젖이 욕심나거든 이것을 들고 네 나라로 돌아가라”며 크게 외쳤다.","a":"수열비","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"장수군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661659.jpg"},{"q":"임진왜란 후에 간행된 경전 7책으로, 십지경론(하) 난승지 제5권 7 ~ 법운지 제10권 12, 간집록, 대방광불화엄경소초 권34, 경덕전등록 권22~24, 대방광원각수다라요의경 권6, 묘법연화경 권1,2 이다. 각수를 적어놓은 형태나 어미 모양 등 지방 사찰에서 간행된 목판본의 형태와 판본류를 확인해 볼 수 있으며 조선후기 각 지방의 경전 간행의 경향을 알 수 있다.","a":"김해 보현사 불교전적류","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643167.jpg"},{"q":"덕계 오건 선생을 추모하기 위해 세운 서원이다. 오건(1521∼1574) 선생은 효성이 지극하여 명종 4년(1549)에 예조로부터 포상을 받았다. 그는 조식·김인후·이황의 제자이며, 명종 13년(1558)년에 식년문과에 급제하여 여러 관직을 지냈다. 선조 5년(1572)에는 관직을 버리고 경상도 산음 덕계리로 낙향하여 여생을 지냈다. ○○○○은 조선 선조 39년(1606)에 지었으며, 숙종 3년(1677)에 ‘서계’라는 현판을 나라에서 하사 받아 사액서원이 되었다. 흥선대원군의 서원철폐령으로 고종 5년(1868)에 철거되었다가 1920년대 복원되었다.","a":"산청 서계서원","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663905.jpg"},{"q":"표제에는 시도기(時到記)로 되어 있고 책등에는 ○○○○○이라 적혀 있으며, 필사본이다. 여중묵(余重默)의 친필로 보이는 「비단일록서(碑壇日錄序)」 2면이 권두에 실려 있으며, 1면에 17자 8행씩 적혀 있다. 그 뒤 정서(淨書)되어 있는 본문은 1면당 총 10행(평균적으로 1행 20자씩 기록)으로 총 461면이다. 책의 내용은 비단일록 및 시도기의 두 부분으로 구분할 수 있다. 전체 461면 가운데, 비단일록은 4-19면까지 기록되어 있으며, 나머지는 시도기에 해당하는 내용이 기재되어 있다.","a":"의령여씨 향제시도록 및 시조제단비","c":"문화유산자료","nc":"","r":"경상남도","s":"의령군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020022810265100.jpg"},{"q":"삼국통일의 주역이였던 김유신(595∼673) 장군의 영정을 모시고 있는 사당이다. 김유신은 15세 때 화랑이 되었고, 무열왕 7년(660) 상대등이 되었다. 그 뒤 중국 당나라와 연합하여 백제를 멸망시키고 나당연합군의 대총관이 되어 고구려를 정벌하고 삼국통일(676)의 위업을 달성하였다. 신라와 고려 때에는 장군이 태어난 태령산 아래 장군의 사당에서 봄과 가을로 제사를 지냈다. 그러나 조선에 들어와서 관리가 소홀하다가 임진왜란, 병자호란을 겪으면서 폐허가 된 것을 철종 2년(1851) 백곡면에 ‘죽계사’를 세워 장군의 영정을 모셨다.","a":"진천 길상사","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649115.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고, 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 고려 우왕 6년(1380)에 세웠고 조선 광해군 7년(1615)에 지금 있는 자리로 옮긴 후 여러 차례 보수를 거쳐 오늘에 이르고 있다. 향교 건물로는 대성전, 명륜당, 동재·서재, 내삼문, 외삼문 등이 있다. 대성전은 앞면 3칸·옆면 2칸 규모의 건물로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 꾸몄다. 안쪽에는 공자를 비롯한 중국의 성현 9인과 우리나라 성현 18현(賢)의 위패를 모시고 있다.","a":"은진향교","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652926.jpg"},{"q":"○○○는 소요당 윤언례가 학문과 후진 양성을 위해 선조 6년(1573)에 지은 것이다. 현재의 건물은 순조 10년(1810)에 고쳐 다시 지었다. 윤언례는 조선 선조 때의 유학자로 곽재우 장군을 도와 의병활동에 적극 참여하였다. 건물은 정면 5칸·측면 3칸으로 지붕 옆면이 사람인(人)자 모양인 맞배지붕이다. 건물은 ㄷ자형의 본체와 ㅡ자형의 행랑채로 구성되어 있으며, 입구에는 장방형의 연못이 있어 자연과 조화를 이룬다.","a":"합천 구음재","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642003.jpg"},{"q":"○○○○○의 안채는 마을 내에서 가장 오래 된 건물로서 상량문에 건축년도는 오래되어 확인이 되지않고 있으나, 마을내에서 가장 오래되었다는 주민들의 의견에 이견이 없다 예전에는 안채 앞마당 좌우로 광 1채, 억새로 만든 3칸집이 더 있었으며 대문밖에 하인들이 거처 하는 집들이 여러채 있었으나 전부 허물어져 없으며 현재는 대문간채, 사랑채, 안채 및 사당으로 어울려져 있다.","a":"함양 노참판댁 고가","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665186.jpg"},{"q":"영주 ○○○○○ 가옥은 현 소유자인 ○○○의 고조부가 매입한 것으로 1800년대 초기에 건립된 까치구멍집이다. 까치구멍집인 안채와 사랑채, 방앗간채로 구성되어 있는데, 원래는 까치구멍집인 안채만 있었다가 후에 사랑채와 방앗간채를 증설한 것으로 보인다. 전면 도로에 면한 헛간과 나무 사이로 난 입구를 들어서면 비교적 넓은 마당을 두고 ‘一’자형의 사랑채가 동남향하여 자리잡고 있으며, 사랑채 사이로 난 중문(中門)을 들어서면 안마당을 사이에 두고 우측에는 방앗간채가, 정면에는 까치구멍집인 안채가 각각 자리잡고 있다.","a":"영주금광리장석우가옥","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641088.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. 폐교된 문대초등학교 남쪽에 있는 2개의 골짜기에 있으며, 주로 둔원천 부근의 운곡마을 주변에 집중적으로 분포하고 있다. 고려 전기 청자와 조선 전기 분청사기를 만들던 가마터 30여기가 분포하고 있는데 청자 가마터에는 청자와 흑자, 녹청자 등의 자기류와 갑발(도자기를 구울 때 재티등이 묻지 않도록 도자기를 담는 큰 그릇)과 갑발받침, 도지미 등 가마 도구가 출토되었다. 청자로는 대접과 접시, 사발, 종지 등 작은 그릇이 출토되었다.","a":"고흥운대리도요지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654213.jpg"},{"q":"이 불상은 석가모니불상과 아미타불상, 약사불상으로 이루어진 ○○○상으로 현재 모악산 ○○○의 대웅전에 주불로 봉안되어 있다. 중앙의 석가모니불을 중심으로 왼쪽(향우)에는 약사불, 오른쪽(향좌)에는 아미타불이 봉안되어 있는데, 坐高는 116~130cm에 이른다. 세 불상 모두 비교적 보존상태는 양호한 편이다. ○○○이란 원래 과거, 현재, 미래를 상징하는 세 불상을 함께 일컫는 개념으로 인도에서는 거의 찾아볼 수 없고 중국에서는 불상 유입 초기부터 유행하여 이미 북위시대의 운강석굴 등에서 보이기 시작하지만 초기에는 ○○○에 명확한 부처의 이름이 정해져 있지는 않았다.","a":"대원사목조삼세불좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639802.jpg"},{"q":"○○○는 합천 해인사, 승주 송광사와 더블어 우리나라 3대사찰 중의 하나로 경내는 크게 상로전, 중로전, 하로전의 3영역으로 나눌 수 있다. 하로전에 위치한 ○○○은 극락보전과 마주 서 있다. 고려 공민왕 18년(1369)에 성곡선사가 세웠다고 하며 그 뒤에 언제 보수했는지 알 수는 없지만 18세기 후반에 다시 지은 것으로 추정한다. 앞면 3칸·옆면 1칸으로 지붕 옆모습이 사람 인(人)자 모양인 맞배지붕으로 되어있다. 지붕을 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식의 건물이다.","a":"양산 통도사 약사전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641819.jpg"},{"q":"○○○○은 미암면의 남쪽에 있는 월출산 산줄기의 북쪽에 위치하고 있다. 산줄기는 해발 50m 내외까지는 급경사를 이루며 내려오다가 그 이하로는 완만하게 구릉을 이루며 내려오고 있다. 고분은 남쪽에서 북쪽으로 내려오는 구릉 말단의 능선상에 위치하고 있으며 구릉의 동사면에 마을이 들어서 있다. 고분은 최종율씨 집 뒤쪽에 있는데 가옥이 들어선 동쪽과 남쪽은 분구 끝자락이 심하게 깎여나갔다. 분구에는 간이 건물을 비롯한 창고와 물탱크가 들어서 상당히 심하게 훼손되었으며 곳곳에 감나무를 비롯한 유실수가 심어져 있다.","a":"영암남산리마봉고분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662259.jpg"},{"q":"이 탱화는 화면이 약간 어둡게 변질되었지만 상겸파 특유의 화풍인 사실적이면서도 단아한 인물묘사와 세장한 신체표현의 특징이 잘 나타나 있어 18세기 후반의 불화 가운데서도 작품성이 뛰어나고, 화면은 아미타불 중심으로 8대보살, 사천왕, 10대제자가 좌우로 자리하도록 구성하였다. 탱화 조성(造成)에 참여한 화승은 尙謙, 창은, 性玧, 快全, 法成 有弘등이며 尙謙을 주축으로 하는 상겸파의 초기의 작품으로 경기도 화파가 경북지역에 미친 영향을 연구해 볼수 있는 귀중한 자료이다. 상겸파는 이후 이 탱화를 조성한 인연으로 남장사의 괘불과 십육나한탱을 제작하였다.","a":"상주 황령사 아미타후불탱","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641081.jpg"},{"q":"이 유적은 옛 사람들의 집단거주지였던 곳으로 중산리 이화마을과 갓안마을이 형성되어 있는 지역에 위치한다. 태화강 북쪽 지역을 대표하는 삼한 후기〜삼국시대 후기까지 형성된 ○○○○이다. 2002년 울산발전연구원에서 실시한 시굴조사에서 주거지, 작업장, 방어시설 등이 확인되어 당시 취락의 구성, 범위, 배치 및 주변 지역과의 교류, 변천과정 등을 구체적으로 알 수 있었다. 사로국[斯盧國]에서 신라로 성장해 가는 과정을 보여주며 신라 초기 연구에 중요한 유적이다.","a":"중산동취락유적","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645919.jpg"},{"q":"귀부는 비받침부분을 일컫는 말로, 대개 거북 모양을 띠고 있다. 이 귀부는 조선 제 16대 임금인 인조의 아들 숭선군의 신도비(왕이나 고관 등의 평생업적을 기록하여 그의 무덤 가까이에 세우는 비)를 세우기 위해 만든 것이나 비를 세우지 못하고 중단되어 귀부만 남은 것이다. 숭선군은 이름은 징(徵)이고, 인조의 다섯째 아들이며 어머니는 귀인 조씨(趙氏)이다. 효종 2년(1651) 누이인 효명옹주의 시할아버지 김자점의 역모에 관계되었다 하여 강화도에 유배되었다가, 효종 7년(1656)에 석방되어 벼슬과 지위를 되돌려 받았다.","a":"공주오룡리귀부","c":"시도유형문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2024110414132700.jpg"},{"q":"조선시대 진잠현의 관리들이 업무를 처리하던 건물이다. ○○○ 이외에도 궐패(闕牌)와 전패(殿牌)를 모셔 놓고 초하루와 보름에 궁궐을 향해 절을 올리던 객사와 관리의 살림집인 내아, 지방관이 행정업무를 처리하던 동헌, 무기를 보관하던 무기고 등 많은 건물이 있었다고 한다．처음에는 교촌동에 있었으나 1934년경 지금 있는 자리로 옮겨서 다시 지었다고 한다. 앞면 4칸·옆면 2칸 규모로 이루어져 있으며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 간결하게 짜 놓았다.","a":"기성관","c":"문화유산자료","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659733.jpg"},{"q":"이 건물은 우리나라의 제5대∼제9대 ○○○을 역임한 ○○○○○이 태어난 가옥이다 1917년 11월 14일 아버지 박성빈(朴成彬) 공과 어머니 백남의(白南義) 여사의 5남 2녀 중 막내로 태어나서 구미초등학교와 1937년 대구사범학교를 졸업할 때까지 살았던 곳이다. ○○○이 태어난 아래채는 좌측에는 앞뒤로 1칸씩의 온돌방, 우측에는 방앗간과 외양간 1칸씩이 배치되었으며, 앞쪽 온돌방이 박○○○이 공부하던 방이다.","a":"박정희대통령생가","c":"시도기념물","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654541.jpg"},{"q":"전북특별자치도 남원시 산내면의 ○○○은 실상사와 같은 시대인 9세기 초에 창건된 사찰이다. 임진왜란으로 실상사가 폐허화되었을 때는 약 200년 동안 실상사의 승려들이 이 절에서 머물렀다고 한다. 이 ○○○○은 원래 실상사 ○○○ 안에 보관되어 있었으나 1997년 5월에 도난 되었다가 같은 해 9월에 회수되어 현재는 실상사에 보관되어 있다. 머리는 높게 틀어 올려 상투모양으로 묶은 후 보관(寶冠)을 썼다. 이마 부분에는 머리카락이 굴곡지게 표현되어 양쪽 귀를 돌아 어깨 아래까지 길게 늘어져 있는데, 이는 고려말 조선초의 보살상에서 공통적으로 나타나는 특징이다.","a":"백장암보살좌상","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639645.jpg"},{"q":"뒷산 8부 능선에 위치한 자연암반에 선형으로 음각한 ○○○○이다. 주변에 기와편이 산재하는 것으로 미루어 보아 사찰이나 암자가 있었던 것으로 추정된다. ○○○○의 높이는 6m 정도이고, 폭은 2.5m 정도이며 방형 기단위에 앙련좌와 통견의 가사가 희미하지만 남아 있다. 목의 삼도, 뚜렷하지 못한 선각, 어색한 구도 등 특징으로 고려시대에 조성된 것으로 추정된다.","a":"함양대대리마애여래입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642270.jpg"},{"q":"○○○는 신라시대에 의상대사(625∼702)가 처음 세웠다고 전하며 조선시대까지도 큰 사찰이었다고 한다. 조선 후기까지 여러 차례 수리가 있었던 것으로 보인다. ○○○○○은 석가모니를 모시는 건물로 옛 건축양식을 지니고 있다. 그러나 기단부의 뚜껑돌이 모두 없어졌고, 다만 소맷돌이 있는 돌층계가 남아 있다. 지붕 옆모습이 사람 인(人)자 모양인 맞배지붕으로 되어있고 지붕의 무게를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식이다.","a":"거동사대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640536.jpg"},{"q":"○○○는 치악산 남쪽 남대봉 중턱의 해발 1,100m의 높은 곳에 위치한 사찰이다. 신라 문무왕 때 의상대사가 지었다는 설과 경순왕의 왕사였던 무착대사가 지었다는 설이 있다. ○○○은 고려말 나옹스님에 의해 새롭게 지어졌으나 한국전쟁 당시 소실된 것을 1968년에 다시 지은 후에 1988년 현재의 위치로 이전하여 중창하였다. 높은 곳에 조성된 사찰답게 자연지형에 맞게 배치되었으며 비교적 낮은 기단 위에 조성되었고 정면 3칸, 측면 3칸의 규모로 다포계 양식의 겹처마, 팔작지붕형태의 건물이다.","a":"상원사대웅전","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660341.jpg"},{"q":"조선 효종의 사위인 ○○○과 숙경공주(淑敬公主)의 묘역이다. ○○○은 1659년(효종 10)에 효종의 여섯 번째 공주인 숙경공주와 혼인하여 흥평위(興平尉)가 되었고, 후에 흥평군(興平君)에 봉해졌다. 묘역은 숙경공주와 합장한 하나의 봉분 형태이다. 묘역 주변에는 곡장(曲墻; 봉분이 있는 구역을 보호하기 위해 주위에 두르는 담)이 둘러져 있으며, 봉분 하단에는 둘레석을 조성하여 공주의 묘격을 반영하였다. 묘표(墓表; 무덤 주인공의 이름 등을 새긴 비석)는 비교적 큰 규모인데, 원수방부형(圓首方趺形; 둥근 머릿돌과 사각 받침돌의 비석 형태)이다.","a":"죽서원몽린묘역","c":"문화유산자료","nc":"","r":"경기도","s":"여주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660259.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배계층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식, 바둑판식이지만 받침돌이 없는 개석식으로 구분된다. 북제주군 애월읍 광령리에 있는 이 고인돌은 개석식으로, 판석을 받침돌 겸 석관의 벽으로 삼아 매장부를 지상에 마련한 형태이다.","a":"광령지석묘 2호","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657670.jpg"},{"q":"손기양(1559∼1619)의 학문과 덕행을 기리기 위한 서원이다. 손기양은 조선 선조(재위 1567∼1608) 때 학자로 임진왜란시 의병을 일으켜 나라에 충성을 다했으며 만년에는 학문에 전념하였다. 영조 19년(1743)에 진암서당으로 세웠는데, 헌종 10년(1844) 선생의 위패를 모시는 청절사를 세워 ○○○○으로 부르게 되었다. 그 후 흥선대원군의 서원철폐령으로 폐쇄되었다가 1914년에 복원하였다. 경내에는 청절사, 강당, 동재와 서재, 문루, 내삼문, 주사 등이 있다. 청절사에는 손기양의 위패를 모시고 있으며 해마다 3월과 9월에 제사를 지낸다.","a":"밀양 칠탄서원","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663974.jpg"},{"q":"이 지도는 19세기 ○○성을 중심으로 동으로 청사포, 서로 낙동강, 남으로 몰운대, 북으로 두구·반송동을 경계로 한 옛 ○○군을 한지에 수묵담채로 그린 조감도형식의 채색 회화식 지도이다. 부산을 중심으로 한 지도로는 조선전기 신숙주의 『해동제국기』에 보이는「부산포도(富山浦圖)」가 있을 뿐이고, 조선중기까지는 별다른 지도가 없으며, 조선후기에서 말기로 접어들수록 정밀한 지도의 제작이 많아졌다. 현재 부산 중심의 지도로는 대략 150여점 확인되고 있다.","a":"동래 고지도","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"서구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636719.jpg"},{"q":"조선시대 문신인 이온의 위패를 모시고 있는 사당이다. 건물은 선조 13년(1580)에 세운 앞면 3칸·옆면 2칸 규모의 건물로 해마다 음력 3월 10일 제사를 지내고 있다.","a":"합천 용연사","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664318.jpg"},{"q":"○○○ 천왕문 앞에 자리한 ○○○ 일선선사(1533∼1609)의 사리탑이다. 일선선사는 조선 중기의 승려로 서산대사의 제자이며 전북지역내의 불교 보급에 큰 영향을 미쳤다. 탑은 연꽃을 두른 원형의 받침돌 위로 길쭉한 종모양의 탑신을 올린 간략한 형태이다. 탑신 표면에는 아무런 장식도 없고 다만 맨 끝부분을 마치 팽이처럼 뾰족하게 조각하여 마무리하였다. 탑신의 아래에 ‘○○○ 일선탑(靜觀堂 一禪塔)’이라는 탑이름이 있고, 바닥돌 윗면에 ‘만력 37년건(萬曆三十七年建)’이라 적혀 있어, 조선 광해군 원년(1609)에 세운 것임을 알게 되었다.","a":"백련사 정관당 부도","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"무주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639523.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 광무 1년(1897) 대성전과 동재·서재만 갖춘 규모로 지었다. 1934년에는 명륜당 등의 교육 공간을 새로 지었다. 향교 안에는 학생들의 교육 장소인 명륜당과 기숙사인 동재·서재가 있으며, 내삼문을 지나면 제사 공간인 대성전이 모습을 드러낸다. 명륜당 지붕은 옆면에서 볼 때 여덞 팔(八)자 모양인 팔작지붕이다. 대성전은 중국과 우리나라 성현의 위패를 모신 건물로, 옆면 지붕선이 사람 인(人)자 모양인 맞배지붕이다.","a":"여수향교","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662064.jpg"},{"q":"전체의 무게를 지탱하는 기단(基壇)을 2층으로 두고, 3층의 탑신(塔身)을 올린 모습의 탑이다. 원래는 기단(基壇)의 일부가 없어지고, 탑신의 3층 몸돌과 지붕돌이 각각 따로 떨어져 흩어져 있었는데, 1989년 탑을 해체하면서 모두 수습하여 복원해 놓았다. 아래층 기단은 네 개의 돌을 바둑판처럼 짜서 이루게 하였으며, 4면의 모서리와 가운데에 기둥 모양을 본 떠 새겼다. 위층 기단은 4장의 돌을 사방에 세워 면을 이루게 하고, 각 모서리마다 별도의 돌로 다듬은 기둥을 세워 두었는데, 원래의 것이 없어져 새로이 만들어 끼워 넣었다.","a":"보성계산리삼층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662083.jpg"},{"q":"운제산에 있는 ○○○는 신라 진평왕(재위 579∼632) 때 세운 절로 ‘항사사’라 불렀다. 후에 신라 고승 원효와 혜공에 얽힌 설화로 ‘○○○’로 부르게 되었다. 현재 절 경내에는 ○○○을 비롯하여 나한전, 설선당, 칠성각, 산령각 등의 건물이 남아 있다. ○○○은 조선 영조 17년(1741)에 고쳐 지은 것이다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포 양식이다.","a":"포항 오어사 대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641262.jpg"},{"q":"이 영정은 ○○○○○선사의 좌안7분면 바닥가부좌상으로, 왼손엔 목리문이 그려진 주장자를 오른손엔 금색의 ‘범’자가 보이는 염주를 쥐고 측면을 향해 앉아 있다. 인물 뒤편으로 문양 없는 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 도식화된 등받이 장식과 바닥에는 방석을 배치하였다. 화면 향우측에는 주지백서의 ○○○○○대선사지진(枕溪堂寬樞大禪師之眞) 화제가 있다. 화면크기는 가로 81.3cm, 세로 124.0cm이다.","a":"침계당 관추 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643018.JPG"},{"q":"이 영정은 좌안7분면의 바닥가부좌상으로, 녹색 법피가 드리워진 등받이 의자를 배경으로 청색장삼에 붉은 가사를 수하고 왼손에는 주장자를 들고 오른손은 무릎에 살짝 올리고 있는 모습이다. 이 작품은 화면향좌측에 ‘선교양종대각등계팔도도총섭○○○○○지진(禪敎兩宗大覺登階八道都摠攝淸潭堂遵一之眞)’의 화제가 있고 배면에는 묵서화기가 있어 1859년 양공 의운당 자우(良工 意雲堂 慈友)가 조성하였음이 확인된다. 화면크기는 가로78.8cm, 세로120.4cm이다.","a":"청담당 준일 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643003.JPG"},{"q":"마을 입구에 서 있는 돌장승이다. 장승은 민간신앙의 한 형태로, 보통 몸체에 그 역할을 나타내는 글을 새겨 그것에 따라 부르는 경우가 많은데, 이 장승에는 이러한 기록이 없으며, 마을사람들에 의해 ‘장승비’라 불리우고 있다. 장승은 네모난 돌기둥을 다듬어 한 면에 얼굴을 새겨 두었다. 기둥 정상에는 모자 모양을 새기고, 얼굴에는 눈썹·눈 ·코·입을 새겨 놓았는데, 입은 약간 웃는 듯한 모습이며, 코는 약간 떨어져 나갔다. 손에는 여의주봉을 들고 있어 일반적인 장승과는 다른 모습이다.","a":"신당동석장승","c":"시도민속문화유산","nc":"","r":"대구광역시","s":"달서구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658101.jpg"},{"q":"○○○란 불교 의식에서 사용하는 불교 도구이다. 저(杵)는 인도의 고대 무기 가운데 하나로 제석천이 아수라와 싸울 때, 코끼리를 타고 ○○○를 무기로 삼아 아수라의 무기를 쳐부순다고 한 신화에서 유래되었다. 손에 쥘 수 있는 모양으로, 쥐고 있으면 묵중하고 엄숙한 기분이 감돌아 온갖 잡념과 방해물을 굴복시켜, 부처의 세계로 인도한다는 의미를 가지고 있다. ○○○○○는 양끝이 3개의 가지가 있는 화살촉모양으로, 손잡이에는 손바닥이 닿는 부분이 볼록하게 나왔다. 손잡이 양끝은 4잎의 연꽃무늬를 양각함으로서 섬세하고 아름다운 모습을 보여주고 있다.","a":"송광사금강저","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639847.jpg"},{"q":"○○○는 신라 진덕여왕때 원효대사가 안거하며 수도 정진해 붙여진 이름이다. 조선 인조 4년(1626년)에 한글로 필사된 ○○○○○은 2책 1권으로 만들어 졌는데. 글씨가 모범적이고 바르며 보존상태도 양호한 상태로 17세기초 유교적 규범이 엄격한 궁중상궁에 의해 작성한 공덕경이란점에서 귀중한 자료일 뿐 아니라 한글 표음법 연구에도 중요한 자료로 평가받고 있다","a":"의정부원효사묘법연화경","c":"시도유형문화유산","nc":"","r":"경기도","s":"의정부시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637760.jpg"},{"q":"충암 김정(1486∼1520)의 학문과 덕행을 추모하기 위해 세운 서원이다. 김정은 조선 전기 문신이며 학자로 이조참판, 대사헌 등을 거쳐 형조판서를 역임하였다. 그림과 시문에도 능하였고 조광조와 함께 사림파의 대표적인 인물로 알려져 있다. 이 서원은 명종 10년(1555)에 ‘삼년성서원’으로 세웠고 광해군 2년(1610)에 국가 공인의 사액서원으로서 ‘상현’이라는 이름을 받았다. 헌종 13년(1672)에 지금 있는 자리로 옮겨 세우면서 성운·성제원·조헌·송시열 등을 추가로 모시게 되었다.","a":"보은 상현서원","c":"시도기념물","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649755.jpg"},{"q":"○○○ 나한전에는 석가삼존상을 중심으로 16나한상, 천부상, 사자상이 양측으로 1구씩 봉안되어 있다. 석가삼존상은 불신 전체에 호분이 칠해져 있으며, 16나한상과 권속들은 흰색, 군청, 녹색, 자주 등 다양한 섹으로 법의를 채색했다. 특히 좌측 5,6번째 나한상은 다른 상들과 달리 목조로 제작되었는데 얼굴이나 법의 표현 등이 석조 나한상과 닮아 보이나 양식적으로 차이를 보여 후대에 제작된 것으로 보인다.","a":"통영 안정사 석조석가삼존좌상 및 십육나한상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"통영시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643141.jpg"},{"q":"영산 동쪽 밀양으로 가는 도로 옆에 있는 10여 기의 무덤들이 분포하는 곳이다. 구조는 네모꼴이며 네 벽면은 자연석으로 쌓았다. 판돌로 덮인 천장은 다른 지방과 같으나 돌방 안쪽이 폭이 좁고 길이가 길며 비교적 높은 것이 특징이다.","a":"창녕 영산고분군","c":"시도기념물","nc":"","r":"경상남도","s":"창녕군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656050.jpg"},{"q":"○○○○○은 2책으로서, 하협(1583∼1625, 호 단지)과 하선에게 내려진 공신녹권이다. 각 책의 첫 페이지 서두에 수급자의 이름이 제시되어 있고 다음 페이지부터는 내용이 같다. 1614년(광해군 6)에 만들어졌고 금속활자본이다. 규격은 22.5×33.5cm이고, 상하내향삼엽화문, 사주쌍변, 계선이 있는 10행 17자의 형태를 취하고 있다.","a":"진주 단지종택 정운원종공신녹권","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642975.jpg"},{"q":"봉수는 과거 통신수단이 발달하지 못하였던 시대의 군사통신제도이다. 조망이 양호한 산정에서 밤에는 횃불로, 낮에는 연기로 국경과 해안의 안위를 중앙에 알리기 위한 목적으로 설치되었다. 봉수제가 성립된 것은 1149년(고려 의종 3)으로, 1급에서 4급의 봉수 거화수(炬火數)를 규정하고, 봉수군의 생활대책을 마련해 주었다. 조선 세종대에 이르러 그 체제가 정비되었다. 5거 거화수 등 관계 규식 마련, 각 도 연변의 연대(烟臺) 축조, 봉수선로 획정 등을 통해 그 면모를 새롭게 하였다.","a":"주전봉수대","c":"시도기념물","nc":"","r":"울산광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645856.jpg"},{"q":"○○○○○은 충청북도 ○○시 상당구 ○○에 위치한 근대건축물로 ○○ 최초의 서양식건물이다. 구한말 개화기에 충청북도 기독교 문화의 요람이었던 ○○○○○은 1906년부터 1932년 사이에 건립된 여섯 동의 서구식 건물로서, 미국 북장로교회 소속 선교사들에 의해 ○○지방에서는 맨 처음으로 건립된 양옥 건물이다. 미국 북장로교회 소속 선교사였던 민노아(閔老雅, F.S. Miller) 목사가 1900년경 ○○시 ○○ 일대에 선교부지를 마련하여 부인과 함께 정착함으로써 건립의 기틀이 마련되었고 1906년 ○○○○○ 4호관을 건립하게 되었다.","a":"청주 탑동 양관","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638599.jpg"},{"q":"고창읍 노동저수지에서 호도마을쪽으로 100m쯤 가면 수백년된 노송과 거목 버드나무가 어우러진 숲에 고고한 자태를 뽑내는 정자가 바로 ○○○이다. 취석이란 말은 옛날 중국의 도연명이 한가로이 세상을 살 때 술이 취하면 집앞 돌팍위에 잠들기도 했다는 도가에서 비롯 되었으며, 사람이 욕심없이 한가롭게 생활한다는 뜻으로 취석이라 일컬었다 한다.","a":"취석정","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"고창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639620.jpg"},{"q":"전라남도 장흥의 야산 계곡에 있는 불상으로 어느 개인이 지은 조그마한 암자에 모셔져 있다. 1매의 화강암 석재를 가공하여 불상과 광배(光背)를 하나의 돌에 만든 석불좌상이다. 머리 위에는 상투 모양의 머리묶음이 뚜렷하며, 갸름한 얼굴과 정제된 이목구비의 표현 등에서 세련된 느낌과 함께 부처의 위엄을 느낄 수 있다. 신체는 인체의 모습을 자연스럽게 묘사하여 통일신라 후기의 불상양식을 충실히 따르고 있다. 옷은 양 어깨를 감싸고 있으며, 옷주름이 도식적으로 표현되었다.","a":"용화사약사여래좌상","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639882.jpg"},{"q":"○○○○○에 보존되어 있는 그림으로, 산수를 배경으로 나한상이 다양한 모습으로 배치되어 있는 16나한도이다. 이 16나한도는 비단 바탕에 채색하여 그려진 것으로, 원래 총 4폭이었으나 1폭이 결실되어 3폭만으로 구성되어 있다. 나한상의 육신은 붉은색에 백색안료를 많이 섞은 분홍색으로 피부를 표현하였고, 육신선은 가는 먹선 위에 엷은 붉은색 선을 겹쳐서 나타내었으며, 육신선에 따라 붉은색으로 바림하여 입체감을 살리고 있다. 머리 부분은 노승(老僧)의 경우 흰 선으로 머리털을 표현하고, 약승(若僧)의 경우 녹청을 발라 묘사하였다.","a":"마하사 응진전 십육나한도","c":"문화유산자료","nc":"","r":"부산광역시","s":"연제구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659362.jpg"},{"q":"○○○은 원래 묵일헌 신치중이 1678년에 삼가현 양촌 마을 동쪽에 축대를 쌓고 나무를 심어 바람 쐬기 좋은 곳을 만들어 이를 ○○○이라 명명했던 것이다. 그러다가 1923년에 그 후손 신종학에 의해 건물 ○○○이 지어져서 오늘에 이른 것이다. ○○○은 정자용도의 누각으로 정면 4칸 측면 2칸의 5량 소로수장 겹처마 팔작집이다. 자연석 기단과 자연석 주초위에 외진주는 원주, 내진주는 방주를 올렸다. 정면 방문은 모두 두 짝 띠살문이며 상부에는 광창을 넣었고 하부는 머름으로 수장했다. 대청에는 종도리와 중도리 사이를 연결하여 우물반자 천장을 넣었다.","a":"거창양지리인풍정","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666232.jpg"},{"q":"조선시대 임금을 상징하는 궐패를 모시고 초하루와 보름에 제사를 지내며 중앙에서 파견된 사신이 머무르던 ○○목의 객사이다. 고려시대에 지어진 건물로 조선 중종 21년(1526)에 화재를 입어 고쳐지었다. 그러나 임진왜란 때 또다시 불타 선조 39년(1606)에 다시 세웠다. 원래의 위치는 지금의 동성동 ○○경찰서 자리였으나 1940년에 옮겨져 ○○여자중학교의 교실로 사용되었다. 그 후 다시 만산동으로 옮겨졌다. 가운데에 본관을 두고 양쪽에 동익헌·서익헌이 붙어 있다. 본관은 앞면 3칸·옆면 3칸이고, 지붕은 옆면이 사람 인(人)자 모양인 맞배지붕이다.","a":"상주 상산관","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640587.jpg"},{"q":"1930년대에 지은 것으로 보이는 개량한옥으로, 일제시대의 대표적인 건축가 박길용(1898∼1943)이 설계했다고 전한다. 원래는 경운동에 있던 것을 1994년 지금의 장소로 옮겨 지었다. 원래 건축주가 두 아들에게 한 채씩 주기 위하여 지은 집이라고 하며, 민익두 가옥이 앞채이고 이 집이 뒤채에 해당한다. 네모반듯한 집터의 동쪽에 대문이 있고, 안마당으로 들어가면 H자형의 건물이 있다. 중심축에 부엌·대청·건넌방·사랑방이 있으며, 부엌 앞쪽으로 안방이 있고 뒤쪽으로 뒷방이 있다. 반칸 너비의 툇마루를 두어 동선을 연결하였다.","a":"월계동각심재","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"노원구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658053.jpg"},{"q":"○○○○은 선조 9년(1576)에 지방 유림들이 뜻을 모아 정몽주(鄭夢周, 1337~1392)와 조광조(趙光祖, 1482~1520)의 학문과 덕행, 충성스러운 절개를 추모하기 위해 세운 ‘충렬사(忠烈祠)’에서 시작되었다. 충렬사는 정몽주와 조광조의 묘소 중간 지역인 죽전에 창건하였다. 임진왜란 때 화재로 소실된 후 선조 38년(1605) 경기도관찰사 이정구(李廷龜), 용인현감 정종선(鄭從善) 등이 정몽주의 묘가 있는 모현읍에 옮겨 중건을 시작하였다. 1608년에 사당 3칸, 동재와 서재 각 2칸, 문루 3칸 규모로 완성하고 문루 위에는 강당을 지었다.","a":"충렬서원","c":"시도유형문화유산","nc":"","r":"경기도","s":"용인시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637339.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. ○○○○는 태종 7년(1407)에 성동리에 세웠으나 1550년에 옮겼다. 임진왜란 때 불타 없어진 것을 순조 1년(1801)에 현재의 위치에 다시 지었다. 대성전을 중심으로 한 제사공간과 명륜당을 중심으로 하는 배움의 공간이 경사진 곳에 위치하고 있다. 외삼문과 명륜당은 앞쪽에 내삼문과 대성전은 뒤쪽에 일직선으로 놓여 있어 향교의 일반적 배치형식인 전학후묘의 방식을 따르고 있다.","a":"순천향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639993.jpg"},{"q":"2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 석탑이다. 위층 기단과 탑신의 몸돌에는 기둥모양을 조각하였고, 특히 1층 몸돌에는 문(門)모양을 새겨 두었다. 지붕돌은 밑면에 1층은 5단, 2층은 4단, 3층은 3단의 받침을 두었는데, 윗층으로 올라갈수록 받침이 줄어들고 있어 이 탑만의 독특한 특징이 되고 있다. 비교적 크기가 작은 탑이지만 각 부분이 균형있게 잘 조화되어 있다. 통일신라의 일반적인 석탑양식을 따르고 있지만 지붕돌받침에 변화가 있는 점 등으로 보아 고려 전기의 석탑으로 추정된다.","a":"안동죽전동삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640445.jpg"},{"q":"○○○○에 서 있는 탑으로, 지금 자리에서 서쪽으로 40m 지점에 무너져 있던 것을 옮겨 세운 것이다. 이 탑으로 인하여 ‘○○’이라는 마을 이름이 생겨났다. 형태로 보아 2층 기단(基壇) 위에 5층의 탑신(塔身)을 올렸을 듯 하나, 지금은 기단부가 거의 없어지고 탑신부는 1층의 몸돌과 1, 2, 3, 5층의 지붕돌만이 남아 있다. 5층 몸돌과 꼭대기의 머리장식은 탑을 복원할 때에 보충한 것이다. 일부만 남은 기단은 윗면에 탑신의 1층 몸돌을 받치기 위한 두꺼운 괴임조각을 두었다.","a":"청주 탑동 오층석탑","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638434.jpg"},{"q":"세종대왕의 여섯째 아들인 ○○○○의 위패를 모신 ○○이다. 어머니는 소헌왕후이며 이름은 유(瑜)이고, 1433년에 ○○○○으로 봉해졌다. 형인 수양대군이 단종을 폐위시키고 왕이 되자 조카인 단종의 복위를 꾀하다 반역죄로 처형당하였다. ○○은 영조 16년(1740)에 세운 것이고 1974년에 보수하였다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다.","a":"진천 금성대군 사당","c":"문화유산자료","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660728.jpg"},{"q":"완귀 안증 선생이 벼슬을 버리고 고향으로 내려와 학문을 연구하고 제자들을 가르치던 곳이다. 안증 선생은 인종이 세자로 있을 때 학문을 가르쳤던 중종 때 학자이다. 명종 1년(1546)에 지은 집으로 안채·사랑채를 비롯하여 여러 채의 건물로 구성되었다. 사랑채는 안증의 호를 따서 ○○○이라 이름하였는데 숙종 21년(1695) 성재 안후정이 지은 건물이다. 앞면은 1층으로 되었으며 뒷면에는 호계천을 향하여 누(樓)를 두었다. ○○○ 옆에는 좌우에 누를 둔 건물이 있는데, ‘식호와’라고 쓴 현판이 걸려 있으며 꾸밈을 달리하여 계절에 따라 선택해서 사용했던 것으로 여겨진다.","a":"완귀정","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658487.jpg"},{"q":"임진왜란 때 순국한 천곡 ○○○의 ○○와 ○○○이다. 본래 부산광역시 동래東萊에 있던 것을 1610년(광해군 2)에 지금 위치인 충청북도 ○○시 흥덕구 수의동에 있는 충렬사忠烈祠의 뒷산으로 옮긴 것이다. ○○○은 본관이 여산礪山이고 호는 천곡, 시호는 충렬忠烈이며 15세에 승보시陞補試에 장원하고 20세에 진사가 되었다. 1576년(선조 9) 별시문과에 병과로 급제한 후 여러 관직을 역임하다가, 1583년(선조 16) 사헌부지평司憲府持平을 거쳐 예조·호조·공조의 정랑正郎이 되었다. 이듬해부터 두 차례에 걸쳐 명나라 사신으로 다녀오기도 하였다.","a":"청주 송상현 묘소 및 신도비","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649892.jpg"},{"q":"현종 9년(1668)에 함평 이씨 문중회의를 통해 지어진 청양 함평 이씨 재사이다. 건립된 지 330여 년이 지났으나 초기의 원형을 잘 유지하고 있으며, 특색있는 건물이다. 마룻대에 쓰여진 축문과 중수기록이 적힌 현판을 통해 고종 18년(1881)에 다시 수리한 건물임을 알 수 있다. 재실 4칸·협문 1칸·곳간 2칸·행랑채 9칸의 규모로, 곳간과 행랑채 사이에 대문이 있는 ㄱ자집의 형태이다.","a":"청양영모재","c":"시도유형문화유산","nc":"","r":"충청남도","s":"청양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639259.jpg"},{"q":"봉림사가 소장중인 불교전적류 모두 8건으로 각각의 명칭은 묘법연화경권제1, 묘법연화경권제3,4, 묘법연화경권제4~7, 금강반야바라밀경(상), 약사유리광여래본원공덕경, 불정심관세음보살대다라니경, ○○○○○21(상), 불설대보부모은중경이다. 구마라습이 지은 묘법연화경 제1권은 목판본으로 간기는 없으나 지질, 판식 등으로 보아 14세기에 간행된 절첩장으로 보인다. 절첩장(折帖裝)은 권자본에 이어 고려 중후기에 많이 만들어진 것으로 서지학적으로 중요한 자료로 취급되고 있다. 본 불경의 경우 인쇄상태가 선명하므로 불경연구, 서지학연구 및 장정연구 등에 아주 귀중한 자료이다.","a":"월인석보 제이십일(상)","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642622.jpg"},{"q":"옛날 자암과 봉수대가 있었던 ○○○의 암벽에 마애된 석불로서 고려시대의 여래좌상으로 양각과 선각으로 높이 2.45m, 무릎높이 1.7m이며 거대한 암벽이 즐비한 ○○○의 중턱 바위틈에 끼어 옆으로 드러누운 상태로 발견되었다. 불상의 광배는 없고 머리는 소발에다 큼직한 육계를 새겼다. 위엄있는 표정의 얼굴은 볼이 풍만하고 반쯤 감은 눈끝이 위로 치켜졌으며, 약간 파손되었으나 균형있는 콧등과 조그만 입은 물론 어깨까지 늘어진 귀 등이 아주 세련된 조화미를 보이고 있다.","a":"김해 봉화산 마애여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641431.jpg"},{"q":"표암이란 ‘박바위’, ‘밝은바위’를 뜻하는데, 신라 6촌 가운데 알천 양산촌의 시조 이알평이 이 바위에 내려와 세상을 밝게 하였다하여 표암이라고 부르게 되었다고 한다. B·C 69년 6촌장이 여기에 모여 화백회의를 열고 신라 건국을 의결했으며, 그후 B·C 57년 신라가 건국되었다. 이와같이 표암은 경주이씨 혈맥의 근원지인 동시에 신라 건국의 산실이고 화백이라는 민주 정치제도의 발상지인 성스러운 곳이다. 이러한 뜻을 새긴 유허비가 조선 순조 6년(1806)에 세웠고, 1925년에 표암재가 건립된 뒤 매년 3월에 그 뜻을 기리며 제사를 지내고 있다.","a":"경주표암","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654482.jpg"},{"q":"개태사는 고려 태조 왕건이 후백제 세력을 완전히 물리친 후, 태조 23년(940)에 지은 절이다. 당시 절 안에는 태조의 초상화가 있어서 나라에 전쟁의 기미가 있으면 그 앞에 기원문을 올려 나라가 태평하기를 빌었다고 한다. 그 후 이 절은 고려 후기에 이르러 왜구의 빈번한 약탈에 의해 차츰 기울어진 것으로 보인다. 현재의 위치는 세종 10년(1428)에 옮겨진 것으로, 개태사 안에는 ○○○○삼존불상(보물 제219호)이 있고, 이외에도 석탑과 쇠솥이 있다.","a":"개태사지","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652745.jpg"},{"q":"자라올이라 불리는 오촌 마을 동쪽 야산지대와 무동산 남쪽 산등선과 서쪽 산줄기에 밀집된 무덤들이다. 1978년 행해진 발굴조사에 의하면 삼국시대의 것으로 확인된 무덤이 총 211에 이르렀으나 거의 파괴되었다. 봉토는 없으나 지표에서 50∼80㎝ 내외의 땅속으로 들어가면 무덤의 뚜껑돌(개석상면)이 확인된다. 돌방(석실)은 서남쪽으로 향해있으며, 널방(현실)과 널길(연도)는 완전한 모습을 갖추고 있다.","a":"초촌리고분군","c":"시도기념물","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653484.jpg"},{"q":"『○○○○』은 김창협(金昌協, 1651~1708)의 친필 서간을 장첩한 것이다. 『○○○○』은 본래 금(金), 목(木), 수(水), 화(火), 토(土) 5책이었으나 현재는 금, 목, 수, 토 4책만 남아있다. 『○○○○』에 수록된 글은 서간 84편, 기문 1편, 시 1편, 발문 1편 등 87편이다. 서간은 1695년 10월에서 1704년 12월 사이에 작성된 것으로 대부분 11촌 조카이자 제자인 김시좌(金時佐, 1664~1727)에게 보낸 것이다.『○○○○』에 수록된 서간은 김시좌의 4대손인 김성근이 집안에 대대로 전해내려 오던 것을 1838년에 장첩한 것이다.","a":"농암진적","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023032213463300.jpg"},{"q":"현재 경상북도 의성군 비안면 ○○○에 있는 석조불상이다. 둥근 대좌(臺座) 위에 앉아 있는 모습으로, 두 눈은 깊게 파여져 있는 상태이다. 손은 왼손 검지를 오른손으로 감싸고 있는 모습으로 ○○○○불을 형상화한 것임을 알 수 있다. 옷은 왼쪽 어깨를 드러낸 채 오른쪽 어깨에만 걸쳐 있다. 고려시대 때 만들어진 불상으로 추정된다.","a":"의성장춘리비로자나석불좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663107.jpg"},{"q":"호봉 이돈(1568∼1624) 선생이 관직을 떠나 고향에 돌아와 학문연구와 후배양성에 전념하기 위해 지은 정자이다. 언제 세웠는지 정확히는 알 수 없으나, 광해군 2년(1610)경 이라고 전해지며, 건물 내부의 기록을 통해 동야 김양근(1734∼1799)이 황폐화된 것을 고쳐지었음을 알 수 있다. 앞면 3칸·옆면 2칸의 규모로 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 대청을 사이에 두고 온돌방을 만들었으며, 양끝과 앞쪽에 난간을 설치한 툇마루를 두었다.","a":"산수정","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658866.jpg"},{"q":"서울특별시 구로구 고척 2동에 있는 함양 여씨의 묘역이다. 함양 여씨의 시조는 중국 내주 사람인 여어매(呂御梅)이며, 본관은 경상남도 함양이다. 여어매는 원래 당나라 사람으로 한림학사를 역임하였는데, 황소의 난을 피하여 통일신라 헌강왕 3년(877) 신라에 귀화하였다. 경상북도 성주군 벽진면에 정착하여 살았고, 고려시대에는 공조전서를 지내었다. 묘역에는 함양 여씨의 선조인 숭의랑공의 묘가 윗쪽에 있고 그 아래쪽에 그의 부인의 묘가 있다. 숭의랑공은 조선 전기의 인물로 태종 때에 호조좌랑, 호조참판 등을 역임하였다.","a":"여계묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"구로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636256.jpg"},{"q":"조선 정조(재위 1776∼1800))는 아버지인 사도세자의 묘를 양주 배봉산에서 수원의 화산 아래로 옮기면서 기존의 수원읍을 현재의 팔달산 아래로 옮겨 새 도시를 조성하였다. 새로 이주한 주민들의 안정을 위해 성곽을 쌓을 것을 계획하고 수원의 이름을 화성으로 바꾸었다. 정조는 새 도시 경영을 위한 경제적 기반 확보와 백성들의 생활안정을 목적으로 둔전(각 궁과 관아에 딸렸던 밭)을 설치하였다. 또한 농사를 위한 관개 용수와 제방 쌓는 일, 상권에 대한 보호, 나무를 심는 식수사업 등 갖가지 정책적인 배려를 베풀었다.","a":"만년제","c":"시도기념물","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019070418061800.png"},{"q":"조선 중기의 문신인 장만(張晩, 1566~1629)의 본관은 인동(仁同)이고, 호는 낙서(洛西)이다. 1624년(인조 2)에 이괄(李适)의 난을 평정한 공으로 진무공신(振武功臣) 1등에 녹훈되었다. 장만의 초상화는 관복본과 유복본(儒服本) 2점이 전한다. 사모에 단령을 입고 의자에 앉은 장만의 <관복본 초상>은 진무공신에 녹훈될 때 충훈부에서 그려준 공신도상으로 추정된다. 장만의 일대기를 기록한 행장(行狀)에는 이괄(李适)의 난 때 병든 몸을 수레에 싣고 야전에서 지내다 한쪽 눈을 잃었다고 나온다.","a":"장만선생영정및공신록권","c":"시도유형문화유산","nc":"","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637630.jpg"},{"q":"‘○○○’은 사람이 죽어 살아 있을 때의 일을 심판받는 곳인 명부(冥府)를 상징하는 곳으로, 주로 10번의 재판을 주관하는 10명의 왕인 시왕[十王]과 중생을 구제하는 지장보살을 상(像)으로 봉안한다. 다른 이름으로는 시왕전, 지장전 등이 있다. ○○○의 ○○○은 건물의 이름을 적어 걸은 편액에 명왕전(冥王殿)이라 되어 있다. 지금의 ○○○ 건물은 1880년에 의민스님이 주도하여 세운 것이다. 건물의 생김새를 보면 길게 다듬은 화강석을 3단으로 쌓아 기단을 만들고 그 위에 자연석을 거칠게 다듬은 초석을 놓고 둥근 기둥을 써서 몸통을 만들었다.","a":"삼막사명부전","c":"문화유산자료","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019042317134400.JPG"},{"q":"경상북도 의성군 단촌면 관덕리의 3층석탑과 함께 있는 불상으로 높이는 98㎝이다. 목 부분이 잘려나간 것을 올려 놓은 상태이며, 얼굴은 심하게 닳아서 코 부분만이 남아 있다. 눈과 입은 세부 확인이 어려워 얼굴의 인상을 살피기 어렵다. 가슴 앞에 있는 목걸이와 U자형의 장식, 팔찌가 있어 보살상을 표현한 것으로 보인다. 갸름한 얼굴, 신체의 안정감, 부드러운 굴곡 등에서 8세기 신라 양식의 특징을 잘 보여주는 작품이다. 조각 솜씨가 뛰어나 신라시대 불상 연구의 귀중한 자료로 평가된다.","a":"의성관덕동석조보살좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640535.jpg"},{"q":"조선 초기 성종대의 뛰어난 학자이며 우리나라 최초의 농학자 ○○○ 선생의 묘이다. 세종 29년(1447) 24세로 장원급제한 뒤 여러 관직을 거쳐 세조 9년(1463) 중추원 부사로 명나라에 다녀왔으며 세조의 총애를 받아 세자빈객이 되었다. 예종 즉위년(1468)에 진산군(晉山君)에 봉해졌으며, 성종 13년(1482)에 좌찬성에 이르렀다. 문장이 당대 으뜸이고 글과 그림에도 뛰어났으며, 인품이 겸손하고 치밀해 맡은 일을 잘 처리하였다.","a":"강희맹선생묘및신도비","c":"시도기념물","nc":"","r":"경기도","s":"시흥시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646279.jpg"},{"q":"○○○○은 전북특별자치도 부안군 상서면 감교리 개암사의 뒷산에 있는 돌로 쌓은 산성이다. 우금바위와 개암사 저수지까지의 능선 밑으로 산성을 쌓았는데, 남쪽으로 통한 계곡 입구에 남문을 설치하고, 양쪽 능선을 따라 동서로 연장되어 있다. 다듬은 돌과 자연석을 적절히 섞어가며, 우금바위에서 그 길이가 남쪽으로 563m, 서쪽으로 675m, 동쪽과 북쪽을 합하여 총 3960m 길이의 성벽을 쌓았다. 백제 의자왕 20년(660) 백제가 나당연합군에 항복하자 복신 장군 등은 일본에 있던 왕자 풍(豊)을 맞아 왕으로 추대하고, 백성들을 모아 의병을 일으켰다.","a":"우금산성","c":"시도기념물","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653366.jpg"},{"q":"○○○은 임진왜란 때 진주성 싸움에서 전사한 김인갑과 그 아우 김의갑, 병자호란 때 전사한 김인갑의 아들 김시엽의 충의를 기리기 위해 조선 고종 10년(1872)에 세운 건물이다. 김인갑은 선조 12년(1579) 무과에 급제하고 선조 24년(1591)에는 훈련원 판관이 되었는데, 진주성 싸움에서 전사하자 선무원종공신으로 기록되었고 병조판서 벼슬에 올랐다. 김의갑은 선조 23년(1590)에 무과에 급제하여 전사하자 주부의 벼슬에 올랐다.","a":"쌍봉리충신각","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"화순군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661991.jpg"},{"q":"○○ 최씨의 시조인 최승과 선조 8분의 위패를 모신 사당이다. 최승은 신라 문성왕 8년(846)에 흉년이 들어 도적이 많아지자, 중국 당나라 무종(武宗)의 명을 받아 이들을 무력으로 평정하였다. 또한 통일신라 진성여왕 3년(889)에 반란이 일어나자 이를 수습하였다. ○○○는 남쪽을 향해 있으며 앞쪽에 있는 문은 가운데를 높힌 솟을대문이고 최승이 살았을 때의 업적을 기록한 신도비와 석교가 있다.","a":"충주 영모사","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660745.jpg"},{"q":"곰솔은 소나무과로 잎이 소나무 잎보다 억센 까닭에 곰솔이라고 부르며, 바닷가를 따라 자라기 때문에 해송으로도 부른다. 또 줄기 껍질의 색이 소나무보다 검다고 해서 흑송이라고도 한다. 바닷바람과 염분에 강하여 바닷가의 바람을 막아주는 방풍림이나 방조림으로 많이 심는다. 무안 ○○○ 곰솔은 둘레가 큰 줄기는 3.6m, 작은 줄기는 2.3m로 해안가에서 자라고 있다. 밑부분의 가지 일부가 죽은 것 외에는 나무 상태가 매우 좋은 편이며, 나무의 모습도 아름답다. 마을 사람들은 이 나무를 신성한 나무로 여겨 매년 산신에게 드리는 제사를 지내고 있다.","a":"무안용정리곰솔","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654334.jpg"},{"q":"불상이 있는 단계지방은 옛날부터 냇물이 넘쳐서 수해가 자주 일어나므로, 이를 막기 위하여 세운 고려시대의 불상이라고 전해온다. 마멸이 심하여 원 상태를 알기 어려운데, 얼굴 부분은 근처에 있던 것을 옮겨다 붙여 놓았다고 한다. 머리 위에 상투 모양의 머리묶음이 높이 솟아있고 얼굴에는 살이 올라 양감이 풍부한 편이다. 신체는 어깨가 넓고 각이 졌으며 무릎 폭 또한 비교적 넓다. 특히 가슴부분이 발달하여 건장한 체구를 표현하고 있으나, 아쉽게도 오른쪽 부분이 거의 떨어져 나갔다.","a":"산청 단계리 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641391.jpg"},{"q":"용호동구석기유적은, 대전의 역사가 10만년전인 중기구석기 시대로 올라갈 수 있음을 밝힌 유적이며, 또한 여기에서 출토된 슴베찌르개, 마제기법의 유물 등은 금강을 중심으로 펼쳐졌던 중기와 후기 구석기시대 사람들의 문화를 이해하고, 동북아시아 구석기문화의 성격을 연구하는데 매우 중요한 자료임","a":"용호동유적","c":"시도기념물","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645843.jpg"},{"q":"일락사의 범종은 본래 대웅전(大雄殿-현 冥府殿)내에 있던 작은 종으로 신라 문무왕 3년(663)에 의현선사가 창건하고 조선 성종 18년에 대수축했다고 전하기도 하나 1927년에 발간된 서산군지의 기록에 조선 영조 35년(1759)년에 조성된 것으로 기록되어 있다. 그러나 일락사의 범종은 1970년대 후반에 분실되어 현재 행방을 알 수 없다.","a":"일락사범종","c":"문화유산자료","nc":"","r":"충청남도","s":"서산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020031916394400.jpg"},{"q":"조선 세종의 딸 ○○○○의 부군인 ○○○ 안맹담(1415∼1462)의 묘소와 신도비(神道碑:왕이나 고관 등의 평생 업적을 기리기 위해 무덤 근처 길가에 세운 비)이다. 안맹담은 세종 10년(1428)에 부마(駙馬:임금의 사위)가 되어 죽성군이 되었고, 세종 14년(1432)에는 연창군에, 세조 3년(1457)에는 원종공신이 되었다. 묘는 ○○○○와 쌍분으로, 봉분 2개가 나란히 자리하고 있으며 봉분 앞에 석등과 4기의 문인석이 있다. ○○ 아래에 세워져 있는 신도비는 거북받침돌 위로 비몸을 세우고 머릿돌을 얹은 모습이다.","a":"양효공 안맹담과 정의공주 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"도봉구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636187.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 성종 4년(1473)에 관학산 밑에 처음 지었는데, 광해군(재위 1608∼1623) 때 동쪽으로 옮겼다가 헌종 3년(1837)에 지금 있는 자리로 옮겨 지은 것이다. 일제시대 폐교되어 금산향교에 합쳐졌다가 1946년 복원하였고 여러 차례 보수를 거쳐 오늘에 이르고 있다. 정문인 외삼문을 들어서면 앞쪽에 교육 공간인 명륜당이 있고, 그 뒤에 있는 내삼문을 통해 들어서면 제사 공간인 ○○○을 배치하였다.","a":"개령향교대성전","c":"문화유산자료","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662628.jpg"},{"q":"1912년 의암 손병희 선생이 세운 것이다. 일제에 빼앗긴 국권을 찾기 위해 천도교 지도자를 훈련시킨 곳으로 의창수도원이라고도 부른다. ○○○이란 이름은 천도교 교조 최제우가 남긴 시에 자주 나오는 ‘봉황’이라는 낱말을 딴 것이다. 현재 걸려있는 현판은 오세창이 썼다. 손병희 선생은 1910년 우리나라가 일본의 식민지가 되자 천도교의 신앙생활을 심어주는 한편, 지도자들에게 역사의식을 심어주는 수련장으로 이 집을 지었다. 1919년 3·1운동의 구상도 이곳에서 했으며, 이곳을 거쳐간 지도자들이 3·1운동의 주체가 되었다.","a":"봉황각","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"강북구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636047.jpg"},{"q":"현재 명부전 지장삼존상 뒤에 걸려 있는 이 작품은 두건을 쓴 지장보살(地 藏菩薩) 및 도명존자(道明尊者), 무독귀왕(無毒鬼王) 등 지장삼존을 중심에 놓고 좌우에 시왕과 판관, 사자, 옥졸, 선악동자, 사천왕 등을 배치한 그림으로 1924년 6월 고산(古山) 스님에 의해 제작된 작품이다. 7폭을 붙여 한 폭으로 완성한 작품으로 모두가 완전하게 남아 있는데, 이 작품 역시 지장사의 불화와 마찬가지로 횡폭으로 길게 그린 점이 특징이다. 또 좌우 권속들의 얼굴을 음영법으로 처리한 기법은 고산당(古山堂) 축연(竺 演)의 화풍을 잘 보여주고 있다.","a":"안양암 지장시왕도","c":"문화유산자료","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018102313491500.jpg"},{"q":"창선면 ○○○ 정상부에 있다. ○○○로 오르는 길은 옥천에서 오르는 동쪽로, 사포에서 오르는 서쪽로와 상신리에서 오르는 북쪽로가 있다. 금산 ○○○에서 받아 사천의 각산 ○○○로 이어주는 중계지이다. 이 ○○○의 조응관계를 진주목장 창선도 지도에는 ○○ 금산봉수와 진주 각산봉수에 두고 있다. ○○○○○의 높이는 8.6m, 둘레 13.6m이다. 문헌기록으로 보면 1455년에서 1468년 사이에 축조된 것으로 보인다. 1895년 5월 9일 각 처의 ○○○와 봉수군을 군부의 주청에 따라 없애라는 조선왕조실록의 기록에 따르면 ○○○○○ 역시 이 때 없어진 것이 확실하다.","a":"남해 대방산 봉수대","c":"시도기념물","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657162.jpg"},{"q":"○○○터로 알려진 곳에 지금의 절을 새로 지을 때 중 땅속에서 발견된 탑으로, 점판암(벼루를 만들던 돌)으로 이루어진 ○○○이다. 2층의 기단(基壇) 위에 5층의 탑신(塔身)을 올려놓은 구조인데, 기단과 탑신의 모습이 비슷하여 확연히 드러나지는 않는다. 현재는 이 탑을 보호하기 위해 탑의 아래에 화강암의 높고 널찍한 2층의 단을 마련해 놓았다. 아래·위층 기단은 윗면에 연꽃을 새겨놓았고, 탑신부의 각 몸돌에는 불교문자인 범어(梵語)를 새겼다.","a":"원주보문사청석탑","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638115.jpg"},{"q":"국상을 당할 때마다 지방의 유림들이 모여 북쪽을 바라보며 절을 하던 곳에 자리한 비이다. 1919년 고종이 승하하자 이를 슬퍼한 지방 유림의 한 사람인 성주 이씨 ○○○이 1921년에 세워 둔 비로, 동이면 평촌리 마을의 야산 꼭대기 부근에 자리하고 있어 최근에 발견한 것이다.","a":"옥천 이기윤 망북비","c":"문화유산자료","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660734.jpg"},{"q":"○○○는 합천 해인사, 승주 송광사와 더불어 우리나라 3대사찰 중의 하나이며 경내는 크게 상로전, 중로전, 하로전의 3영역으로 나눌 수 있다. 상로전에 있는 ○○○은 대웅전의 동남쪽에 위치한다. 고려 공민왕 18년(1369)에 세워졌다고 전하며, 「○○○중수기」에 의하면 조선 고종 24년(1887)에 불에 탄 것을 고종 25년(1888)에 호성대사가 수리했다고 기록되어 있다. 앞면 5칸·옆면 2칸으로 지붕 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로 되어 있다. 지붕을 받치기 위해 장식하여 만든 공포는 기둥 위와 기둥 사이에도 있는 다포계 양식의 건물이다.","a":"양산 통도사 명부전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641816.jpg"},{"q":"향교란 공자를 비롯한 여러 성현께 제사지내고, 지방 백성들의 교육과 교화를 담당했던 국립교육기관을 가리킨다. ○○○○는 조선 세종 5년(1423)에 진사리 현의 서문 밖에 처음 지었다가, 헌종 15년(1849)에 지금의 위치로 옮겨 지었다. 대부분의 향교 건물들이 남쪽을 향하는 것과는 다르게 이 향교는 동쪽을 향하고 있으며, 대성전·명륜당·동재·서재·삼문 등이 남아있다. 중국과 우리나라 유학자들의 위패를 모시고 제사지내는 대성전과 배움공간이었던 강당인 명륜당은 좌우로 나란히 배치되어 있다.","a":"정의향교","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643268.jpg"},{"q":"조선 중기의 명신이자 우암 송시열尤庵 宋時烈의 종증조인 규암 ○○○의 ○○와 그를 기리기 위해 ○○ 입구에 세운 ○○○이다. ○○○는 본관이 은진恩津, 자는 미수眉叟이고 호는 규암이며 시호는 문충文忠이다. 1521년(중종 16)에 별시문과別試文科에 급제하여 홍문관 정자正字, 수찬修撰 등을 역임하였다. 대간臺諫으로 재직할 당시 김안로金安老의 재집권을 막으려다 제주목사로 좌천되었고, 후에 다시 사수泗水로 유배되었다. 1537년에 김안로 등이 제거되자 예조참의, 승지, 형조참판을 역임한 후, 성균관대사성이 되어 성리학을 강론하였다.","a":"청주 송인수 묘소 및 신도비","c":"시도기념물","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651325.jpg"},{"q":"경상남도 ○○군 ○○면 북촌리에 있는 이 산성은 계곡을 둘러싸며 주위의 산 능선을 따라 일정하지 않은 모양으로 쌓은 산성이다. 성의 둘레가 약 1.7㎞에 달하는 대규모의 산성이고, 남서쪽 성벽은 바깥만 돌로 쌓고 안쪽은 흙과 잡석으로 채우는 방식으로 쌓았다. 만든 연대를 알 수 있는 기록이나 유물을 발견하진 못했지만 만든 방식이 근처의 성산산성, 문안산성과 동일하다. 그리고 성 안에서 발견되는 일부 토기와 기와조각 등으로 미루어 보아 이것은 통일신라시대까지는 거슬러 올라갈 수 있을 것으로 추정한다.","a":"함안 성점산성","c":"시도기념물","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656242.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때면 이곳에 깃발을 달게 되는데, 이 깃발을 거는 길다란 장대를 당간이라 하고, 당간을 양 쪽에서 지탱시켜주는 두 돌기둥을 ○○○○라 한다. 드물게 당간이 남아있는 예가 있으나, 대개는 두 지주만이 남아있다. 이 ○○○○는 ○○○ 절터에 남아 있는 것으로, 지광국사현묘탑비(국보)와 함께 터를 지키고 있다. 기둥에는 별다른 조각이 없으며, 아래에서 위로 갈수록 점점 좁아지고 있다. 기둥사이에는 당간을 꽂아두기 위한 받침돌을 둥글게 다듬어 마련해 놓았다.","a":"법천사지 당간지주","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660351.jpg"},{"q":"○○○○○는 고려 시대 청자와 백자를 만들던 곳이다. 요지는 안양천 지류인 삼성천 상류에서 무너미고개로 올라가다가 초입 우측 사면에 위치한다. 반경 40~50m 범위에서 음각이나 양각한 백자, 청자, 흑유자기 등이 다양하게 출토되어 고려 시대 관악산 일대 도자기 제작양상을 살펴볼 수 있다. 출토된 청자는 대접, 접시와 같이 일상에서 많이 쓰이는 기종이 많고 각접시, 항아리, 뚜껑 등도 조금씩 보인다. 음각이나 양각 혹은 상감문양을 가진 것도 있다.","a":"안양시비산동도요지","c":"시도기념물","nc":"","r":"경기도","s":"안양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646593.jpg"},{"q":"이 유적은 문경공(文敬公) 장암(丈巖) ○○의 ○○이다. ○○는 조선중기의 문신, 학자로 자는 중순(仲淳), 호는 장암(丈巖), 본관은 연일(延日), 좌의정 정철(鄭澈)의 후손이다. 송시열(宋時烈)의 문인으로 숙종 8년(1682) 생원이 되고 1684년 정시문과(庭試文科)에 급제하여 검열(檢閱)·정언(正言)을 지냈으나, 1689년 기사환국으로 인현왕후(仁顯王后)가 폐출되고 송시열이 사사(賜死)당하자, 그는 파직되고 문외출송(門外黜送)당했다가 경성에 유배되었다.[출처: 한국민족문화대백과사전(○○)] 이후 숙종 20년(1694) 갑술옥사(甲戌獄事)로 서인이 기용될 때 재…","a":"괴산 정호 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651469.jpg"},{"q":"이 책판은 조선 인조 때의 학자인 간송당 ○○○의 문집인 『○○○○』과 『금라전언록』을 간행하기 위해 만든 것이다. ○○○는 효심이 극진하여 백효(伯孝)라고 불렀다. 인조반정 직후 공조좌랑을 역임하였으나 곧 벼슬을 버리고 고향으로 내려가 학업에 열중하였다. 『간송집』은 영조 20년(1744)에 간행한 것이고, 『금라전언록』은 함안의 역사와 고려말 충신 이방실 장군을 비롯한 함안 출신자들의 업적을 기록한 것으로 순조 13년(1813)에 간행되었다. 책판의 크기는 가로 44.5㎝, 세로 21.5㎝이며, 총 190매가 합강정에 보관되어 있다.","a":"조임도 간송문집 및 금라전신록목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641788.jpg"},{"q":"○○○는 신라 무열왕때 의상조사가 창건하여 웅정암이라 하였으나 임란때 소실한 후 1603년 지조와 원찬이 중창하고 이름을 ○○○로 바꿨다. 그후 조선 영조 50년(1774) 중수하여 오늘에 이르고 있으며, 유적 유물로는 대웅전과 명부전, ○○○, 요사채 2동 등이 있다. ○○○ 규모는 정면3칸, 측면 2칸이며, 구조는 중층 누각에 익공계 팔작집이다. 상하층은 벽 없이 사방이 트여 있고, 대웅전 앞 중정에서 진입할 수 있게 후면 어칸에 통로를 내어 출입하고 있다. 현재 ○○○ 좌우로는 대웅전 영역으로 접근하는 통로가 있다.","a":"영천 영지사 범종각","c":"문화유산자료","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051421555100.JPG"},{"q":"조선 순조 25년(1825)에 부사 조길원이 세운 관청의 정문으로 고종 7년(1870)년에 고쳐 지었고, 1985년에 ○○문화유산단지 안으로 옮겼다. 앞면 3칸·옆면 2칸의 2층 건물로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 1층은 3개의 문으로 되어있는데, 가운데 문은 부사가 출입했고 양쪽 문은 평민이 출입했다고 한다. 2층에는 난간을 둘렀으며 사방이 탁 트여 멀리있는 적의 동정을 살필 수 있도록 하였다. ‘도호부절제아문(都護府節制衙門)’이라는 현판은 건물을 세울 당시에 부사 조길원이 썼다고 한다.","a":"제천 청풍 금남루","c":"시도유형문화유산","nc":"","r":"충청북도","s":"제천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2021012016144000.jpg"},{"q":"○○○○은 조암산 자락 아래 낙동강 옛 퇴강(물미) 나루터 주변에 자리 잡고 있는 ○○ 지역 최초의 천주교 교당이다. 경북 북부지역 천주교 신앙의 산실이며 한국 천주교의 역사를 대변하는 교당으로 천주교회사에 중요한 위치를 차지한다. 1956년에 건립된 본당은 입면과 평면에서 고딕양식의 특징을 지닌 근대 건축물로서의 가치도 매우 크다. 성주의 가실본당, 김천의 본당과 더불어 경북의 천주교사를 보여주는 중요한 자료이다.","a":"상주 퇴강성당","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663611.jpg"},{"q":"충청북도 ○○시 살미면 향산리에 있는 ○○○○은 계곡을 포함한 산 정상을 둘러 쌓은 형태를 띄고 있다. 삼국시대에 만들어진 것으로 추정되는데, ○○○○이라는 명칭은 『세종실록지리지』에 처음 보이고 있어 조선 초기에도 ○○○이 봉화대로 사용되었음을 알 수 있다. ○○○○은 굴곡이 심한 능선을 이용하여 방어에 용이하게 쌓았는데, 산성이 있는 곳은 특히 경사가 심하여 곳곳에 암벽이 형성된 천연의 요새이다. 경사가 완만하여 접근이 비교적 쉬운 서문과 남문, 동문터의 근처에는 2중, 3중의 방어벽을 별도로 설치하여 산성을 요새화하였다.","a":"충주 대림산성","c":"시도기념물","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650582.jpg"},{"q":"원래 원주시 중앙동의 폐사지에 있던 것을 1962년 5월에 강원감영터로 이전하였다가 2000년 봉산동 시립박물관 야외로 이전 전시하고 있다. 탑의 형태는 1층 기단(基壇)위에 5층의 탑신(塔身)을 올린 모습이다. 전체가 큼직한 돌로 이루어진 기단은 네 모서리와 각 면의 가운데에 기둥모양의 조각을 두었으며, 탑신의 각 몸돌에도 모서리마다 기둥을 본떠 새겼다. 위로 오를수록 서서히 줄어드는 비율이 단아하며, 형태도 정돈되어 있다. 지붕돌은 얇은 편이고 밑면의 받침이 3단씩인데, 안타깝게도 파손된 부분이 많다. 양식으로 보아 고려시대에 세운 탑으로 추측된다.","a":"일산동오층석탑","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637852.jpg"},{"q":"○○○에 보존되어 있는 ○○○○○인데, 탱화란 천이나 종이에 그림을 그려 액자나 족자 형태로 만들어지는 불화를 말한다. 비단 바탕에 주색을 바르고, 그 위에 세선의 백색선묘로 도상을 표현하고 있다. 화면 상단 중앙의 아미타상을 중심으로 팔대보살상과 사천왕상이 좌우에 배치되어 있다. 아미타상을 중심으로 좌우에 보살상 2구씩 각각 배치하고 그 위쪽에 아난과 가섭을 배치하였으며 그 바깥쪽에 여래상 1구씩 배치하고 있다. 화면의 아래쪽 부분 중앙에 있는 기록에 의하면 이 불화는 가경 19년, 즉 조선 순조 14년(1814)에 조성된 것임을 알 수 있다.","a":"양산 통도사 가경19년명 아미타후불탱","c":"문화유산자료","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664816.jpg"},{"q":"○○○는 통일신라 효소왕 1년(692) 의상대사가 지금의 자리보다 서쪽에 신광사라 이름지어 세웠다. 그 뒤 고려 공민왕 10년(1361) 나옹대사가 지금 있는 자리로 옮겼다. 당시에 새로운 절터에서 큰 바위가 나왔다 하여 터닦는 다는 뜻을 가진 ‘선(禪)’자를 넣어 ○○○라 했다. 영조 1년(1725) 서쪽 옛 터로 옮겼다가 순조 4년(1804) 지금 있는 자리로 다시 옮겨 현재에 이르고 있다. 절 경내에는 ○○○을 비롯하여 명부전, 칠성각, 산왕각 등이 남아있다. ○○○은 앞면 3칸·옆면 3칸의 규모로, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"성주 선석사 대웅전","c":"시도유형문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641307.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 조선 명종 15년(1560)에 세워진 ○○○○는 고종 7년(1870)과 24년(1887)에 고쳤고, 후에 여러 번의 수리를 거쳐 오늘에 이르고 있다. 현재 남아있는 건물은 대성전·동재·서재·명륜당 등이 있다. 건물은 내삼문을 경계로 앞쪽에는 학생들이 공부하던 명륜당을 중심으로 배움의 공간을 두고 있다. 뒤쪽에는 공자를 비롯하여 여러 성현들의 제사를 지내는 대성전이 있어, 향교의 일반적 배치형태인 전학후묘를 따르고 있다.","a":"음성향교","c":"시도유형문화유산","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638550.jpg"},{"q":"인천광역시 ○○군 선원면 선행리에 위치한 ○○○는 김상용 선생을 비롯한 병자호란과 신미양요 때 나라를 지키다 순절한 충신 29명의 위패를 봉안한 사당이다. 1641년(인조 19)에 건립하여 현충사(顯忠祠)라 부르다가 1658년(효종 9)에 국왕으로부터 ○○○란 이름을 받아 ○○유수 허휘가 ○○○로 이름을 바꿨다. 김상용은 1636년 병자호란 때 왕실의 신주를 받들고 빈궁·원손을 수행해 ○○도에 피난했다가 이듬 해 성이 함락되자 성의 남문루(南門樓)에 있던 화약고에 불을 지르고 순절하였다.","a":"강화 충렬사","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637043.jpg"},{"q":"충청남도 논산시 연산면 소재지에서 대전 방향으로 약 3㎞쯤에 있는 하송 마을 북쪽 산 능선에 ○○○○○이 위치하고 있다. 높이 4.3m, 너비 3.5m의 수직 화강암벽에 가는 선으로 ○○○입상을 새겼는데, 중앙 본존불의 높이는 3.2m이고, 오른쪽 협시불의 높이는 1.23m이다. 불상을 만든 연대나 유래를 전하는 문헌 및 기록은 없으나 고려시대에 만들어진 불상으로 추정된다.","a":"연산송정리마애삼존불","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661449.jpg"},{"q":"○○○ 경내로 들어오는 일주문을 지나 약 20～30m 올라오면 왼쪽 산사면에 위치해 있다. 석조형 부도로 이끼가 전체적으로 덮혀 있으며, 앞쪽 기단면은 완전히 드러나 도괴의 위험도 있어 보인다. 부도의 특징을 보면, 기단· 탑신· 상륜부 3部로 구분되었으며, 탑신과 상륜은 일석이다. 기단은 치석하여 2段으로 만들고 탑신이 놓이는 기단 상면은 복엽연판으로 돌려 장식했다. 연봉형 상륜 아래로는 크고 대담한 7개의 연판으로 장식된 것처럼 보이는데, 문양을 자세히 보면 연잎을 서로 대칭으로 말아 연판 같은 효과를 내고 있는 것이 특징이라 하겠다","a":"남해 화방사 승탑","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666690.jpg"},{"q":"임진왜란 때 부원수 신각(申恪)을 중심으로 한 조선군이 왜군과의 육상 전투에서 최초로 승리를 거둔 장소이다. ○○○은 양주시 광적면에서 파주시 광탄면으로 넘어 가는 360번 지방도로에 위치한 고개로 “게네미고개”라고도 불린다. 신각은 1592년(선조 25) 임진왜란이 일어나자 도원수 김명원(金命元) 휘하의 부원수로서 한강을 지켰다. 그러나 한강 방어선이 무너지자 유도대장(留都大將) 이양원(李陽元)과 함께 양주로 가서 흩어진 병사들을 다시 모으고 함경도병마절도사 이혼(李渾)에게 지원병을 얻어 북상하는 왜군의 선봉부대를 맞아 ○○○에서 전투를 벌여 큰 승리를 거두었다.","a":"해유령전첩지","c":"시도기념물","nc":"","r":"경기도","s":"양주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646046.jpg"},{"q":"○○○ 선생의 외가가 있던 곳으로 그가 태어난 집터이다. ○○○은 수양대군이 조카 단종을 폐하고 왕위에 오르는 것에 반대한 사육신의 한 사람이다. 세종(재위 1418∼1450) 때 집현전의 학자로 훈민정음 창제에 크게 공헌하였으며, 단종 폐위에 대해서도 굳은 절개를 지켜 죽임을 당했다. 숙종 2년(1676)에 읍사 이량이 선생의 옛 집 근처에 사당을 세우고 사육신을 같이 모실 것을 청하자, 나라에서 녹운서원이라 하였고, 뒤에 노은이라고 이름을 바꾸었다.","a":"성삼문선생유허지","c":"시도기념물","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651753.jpg"},{"q":"○○○은 한국의 토속신인 산신 즉 산신령을 모시는 곳으로, 마을과 절을 수호하는 기능을 갖는다. ○○○○은 마을이름과 같이 왕릉이나 왕실 가족의 무덤 주변에 형성된 마을이다. 덕릉(德陵)은 덕흥대원군묘의 별칭으로 조선 선조임금의 아버지인 덕흥대원군(1530∼1559)의 묘이다. ○○○은 앞면 1칸, 옆면 1.5칸 규모이고, 옆면에서 볼 때 지붕선이 ‘사람인(人)’자 모양과 비슷한 맞배지붕을 얹었으며, 양 옆으로 바람을 막아주는 풍판(風板)을 달아 놓았다.","a":"덕릉마을산신각","c":"시도민속문화유산","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658176.jpg"},{"q":"선현께 제사지내고 학문을 이어받고자 설립한 조선시대 사립교육기관으로 인조 12년(1634)에 세웠다. 김장생(1548∼1631)의 학문과 덕행을 기리기 위해 처음 세웠으나, 훗날 제사를 지내는 ○○○에 김집, 송준길, 송시열의 위패를 추가 배향하였다. 현종 1년(1660) 임금에게 ‘돈암’이라는 이름을 하사받으며 사액서원으로 승격되었고, 흥선대원군의 서원철폐령이 내려졌을 때에도 없어지지 않은 47개 서원 중 하나이다. ○○○○은 조선 중기 이후 많은 인물을 배출한 유서 깊은 곳으로 해마다 2월과 8월에 제사를 지내고 있다.","a":"돈암서원유경사","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639265.jpg"},{"q":"무안면 가례리 ○○○○에 보관되어 있는 ○○○로 재단법인 화쟁교원(이사장:김용대)에서 수집한 33종 52권인데 목록은 다음과 같다. 1. 대장일람(大藏一覽) 10권 2책 = 明홍무 13년(1380년) 2. 사기영선(史記英選) 3권 = 세종 2년(1527년) 3. 팔양신주경(八陽經) 1권 = 건융 56년(1791년) 4. 도서(都序) 1권 = 강희 20년(1681년) 5. 불설아미타경(佛說阿彌陀經) 1권 = 선조 39년(1605년) 6. 송운집(松雲集) 1권 = 만력 3년(1574년) 7. 호법론(護法論) 1권 = 순치 5년(1648년) 8. 범망경(梵網經) 1권 =…","a":"밀양영산정사고불서","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642294.jpg"},{"q":"○○시의 중심부에 있는 초가지붕집으로 조선 후기에 지어진 것이다. 앞면 3칸·옆면 2칸의 규모로, 왼쪽으로 2개의 방이 있으며 오른쪽으로 부엌이 있다. 겹집양식으로 뒤쪽에 안방과 골방을 배치하였고, 앞쪽에는 툇마루가 있다. 네귀퉁이에 있는 기둥은 안으로 기울어지도록 세웠으며, 못을 사용하지 않고 이음·새끼줄 등을 이용하였다. 특히 부엌쪽은 초가지붕이 땅 가까이까지 내려와 있다. 흙벽으로 되어있고 목재의 가공 등이 거친 편이다. 흙과 돌로 된 담이 집 주위를 둘러싸고 있다.","a":"강릉 오금집","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"강릉시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638058.jpg"},{"q":"척화비란 조선 고종 때 병인양요, 신미양요를 승리로 이끈 흥선대원군이 서양세력을 배척하고, 이를 모든 백성에게 일깨워 주고자 전국의 중요한 곳에 세워두도록 한 것으로, 이 비도 그 중 하나이다. 비는 낮은 사각받침돌 위로 길쭉한 비몸돌을 세운 모습이다. 비문에는 ‘서양 오랑캐가 침범하는데 싸우지 아니하고 화친하자고 주장하는 것은 나라를 팔아먹는 것이니, 우리 만년자손에게 경계한다’는 강한 어투의 경고문을 적고 있다.","a":"기장척화비","c":"시도기념물","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645165.jpg"},{"q":"독립운동에 일생을 바친 ○○○ 장군의 업적을 기념하기 위해 세운 비이다. ○○○ 장군은 홍성에서 태어나 15세에 집안의 노비를 풀어주고, 그들에게 농사지어 먹고 살만한 논밭을 골고루 나누어 주었다. 1905년 서울로 올라와 육군무관학교에 들어갔으며, 1907년 고향에 돌아와 호명학교를 세우고 90여칸의 자기집을 학교건물로 쓰게 했다. 광복단에 들어가 항일투쟁을 하다 1918년 만주로 건너가 3.1 독립선언에 전주곡이 되는 무오독립선언서에 39명의 민족지도자의 한사람으로 서명하였다.","a":"김좌진장군비","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661164.jpg"},{"q":"조피골(조피)로 불리는 곳에 자를 덕원(德원). 호를 둔재라고도 하고. 종6품인 충무위부사과 (충무위부사과)를 역임하였고 중직으로는 정2품인 통훈대부 사복시정(通訓大夫 司僕시正)에 제수된 바 있는 취수당 오연 (오연 1598~1669) 선생이 1650년경에 건립한 정면 3칸 측면2칸 규모에 팔작지붕의 중층루각형 정자이다.","a":"영양취수당","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641085.jpg"},{"q":"○○○의 옛 터에 석불 1구와 함께 남아 있는 탑으로, 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올리고 있다. 기단의 네 모서리와 탑신의 몸돌에는 기둥 모양을 새겨 놓았다. 지붕돌은 윗면이 완만한 곡선을 이루며 네 모서리선이 목조지붕의 지붕선처럼 뚜렷하게 표현되었다. 지붕돌 밑면에는 별도의 돌을 끼워 넣어 층급받침을 대신하고 있다. 꼭대기에는 노반(露盤:머리장식받침) 위로 앙화(仰花:활짝 핀 연꽃모양의 장식)가 놓여 머리장식을 하고 있다. 무너져 각 부재들이 흩어져 있던 것을 1996년에 새로 복원한 것이다.","a":"담양연동사지3층석탑","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662225.jpg"},{"q":"안채와 사랑채, 문간채와 곳간채가 어우러져 ㅁ자형 평면을 갖춘 집이다. 안채는 1918년에 지었고 그 외의 가옥은 1940년경에 지은 것으로 앞면 5칸 반·옆면 2칸 규모이며 남향으로 자리잡고 있다. 대청마루 북쪽면은 틔우지 않고 도장방을 만들어 물품을 보관하는 공간으로 만들었다. 사랑채는 앞면 3칸·옆면 2칸 크기의 동향집인데 1칸 마루를 넓게 처리하고 2개의 온돌방 앞에 툇마루를 두었다. 안마당의 곳간채는 가운데 기둥 하나와 흙벽이 지붕을 지지하는 구조로서, 민가의 원형에서 발전한 것으로 주목된다.","a":"산청단계리박씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664100.jpg"},{"q":"화북포 앞바다에 오고가는 배들의 안전을 기원하기 위해 해안에 세운 사당이다. 조선 순조 20년(1820) 당시 제주목사로 있던 한상묵이 세웠으며 그 뒤 헌종 7년(1841) 방어사였던 이원조가 건물을 보수하고 헌종 15년(1849) 장인식이 돌에 ‘해신지위’라는 글자를 새겨 보존하도록 하였다. 지금 있는 건물은 1975년 장소가 좁아 서북편 해안으로 옮겨 다시 세운 것으로 1칸 크기를 가진 한식 기와집이다. 해마다 음력 1월 15일에 바다가 삶의 터전인 주민들이 모여 정성을 다해 해상의 안전을 기원하는 해신제를 지내고 있다.","a":"해신사","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657796.jpg"},{"q":"○○○ 대웅전 안에 본존상으로 봉안된 ○○○○○이다. 좌고(坐高) 138㎝로 좌상으로서는 꽤 큰 편에 속하며 통나무의 속을 파서 조각하여서인지 매우 무거운 편이다. 불상의 등과 밑부분에는 복장공(腹藏孔)이 마련되었는데, 현재 등쪽의 복장공은 완전히 막혀 있으며 밑부분의 복장공은 4개의 판목을 쇠못으로 박아 고정하였다. 후령통(喉鈴筒)을 비롯한 복장은 남아있지 않으나 <수능엄경의해(首楞嚴經義海)>1책(1~3권)과 일부 파손된 경전 일부분이 발견되었다.","a":"고산사목조석가모니불좌상","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637228.jpg"},{"q":"이원경의 후손들이 그를 추모하기 위해 지은 사당이다. 이원경은 고려지현관 직제학 금자광록 대부를 지낸 인물로, 후에 벼슬을 사직하고 ○○군 두상면 상상곡에서 살았다. 사당은 조선 숙종 18년(1692)에 지었고, 원래 앞면이 4칸이었으나 후에 양측에 1칸씩 늘려 지었다. 지붕은 옆에서 볼 때 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다. 충현사는 3현(이치·이홍조·이일로)을 추모하기 위해 고종 32년(1895)에 지은 사당이다. 원래는 농산서원 안에 있었으나 흥선대원군의 서원철폐령으로 서원은 사라지고 충현사만 남아 있다.","a":"합천 청금정 ∙충현사","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664127.jpg"},{"q":"돈대란 적의 움직임을 살피거나 공격에 대비하기 위하여 영토 내 접경지역 또는 해안지역의 감시가 쉬운 곳에 마련해 두는 초소이다. 보통 높은 평지에 쌓아 두는데, 밖은 성곽으로 높게 하고 안은 낮게 하여 포를 설치해 둔다. 특히 ○○도에 있는 돈대들은 조선 인조 14년(1636) 병자호란이 일어나 ○○도가 함락되자, 이에 놀란 조정에서 해안 경비를 튼튼히 하기 곳곳에 쌓아두도록 한 것이다. 창후리 선착장에서 북쪽으로 난 비포장길을 따라 100m 정도 떨어진 곳에 자리하고 있는 이 돈대는 해안을 따라 직사각형으로 길게 쌓았다.","a":"강화 무태돈대","c":"문화유산자료","nc":"","r":"인천광역시","s":"강화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/0000000001659581.jpg"},{"q":"○○○은 ○○○ 세존사리탑(世尊舍利塔) 앞에 조성된 건물로서 조선 인조 2년(1624)에 임진왜란으로 소실된 ○○○ 중건시 벽암대사(碧巖大師)에 의해 중창되었다고 하며, 건물 내에는 석가모니불과 함께 연대 미상의 16나한(羅漢)이 모셔져 있다. 조선후기 호영(呼映)스님에 의해 작성된 것으로 알려진 「○○○전경도」에는 사리각(舍利閣)이라 표기되어 있어 이 전각이 원래 사리탑 적멸보궁의 예배처로 사용되었을 것이라고 한다.","a":"보은 법주사 능인전","c":"시도유형문화유산","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638848.jpg"},{"q":"○○○는 신라 문무왕 4년(664)에 화엄화상(華嚴和尙)이 처음 창건하였고, 조선 선조 7년(1574) 송혜증법사(松惠證法師)가 고쳐 지었다고 전한다. 오랜 세월로 인해 다른 건물들은 없어지고 지금은 ○○○과 요사채, 그리고 근래에 세운 대웅전이 남아 있다. ○○○은 정면 3칸·측면 2칸의 맞배집으로 단순하고 소박한 구조를 지닌다. 서쪽으로 500m 지점에 ‘극락암’이 있었다고 전해지며, 남쪽 800m 지점의 금학산 중턱에 금정암이 남아 있다.","a":"용담사무량전","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662414.jpg"},{"q":"탱화란 천이나 종이에 그림을 그려 족자나 액자 형태로 만들어서 거는 그림을 이른다. 이 탱화는 조선 영조 40년(1764) ○○○○○에 봉안되었던 것으로, 현재는 표충사에 보존되어 있다. 그림 전체의 크기가 가로 65㎝, 세로 70㎝이고, 화폭의 크기는 가로 54㎝, 세로 55㎝ 인 작은 규모의 특이한 탱화로, 석가가 아닌 제석이 그 중심에 자리하고 있다. 제석은 의자에 앉아 있는 모습인데, 손으로는 이제 막 피어오르는 연꽃을 두 손으로 받쳐들고 있다.","a":"사룡산금정암제석탱","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640972.jpg"},{"q":"우리나라 최초의 사액서원인 ○○○○의 현판으로, 사액서원으로 될 당시 조선시대 명종이 이름을 지어 그것을 직접 쓴 것이다. 사액서원이란 임금이 이름을 지어 그 이름을 적은 현판과 그에 따른 서적·토지·노비 등을 나라에서 내려준 서원을 말한다. ○○○○은 조선 중종 38년(1543) 풍기군수 주세붕(1495∼1554)이 건립할 때는 백운동서원이었다.","a":"명종어필‘소수서원’현판","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641067.jpg"},{"q":"조선 광해군(1608∼1623) 때 양주목사를 지낸 김흥국(1557∼1623)이 이곳에 와 살면서 지은 정자로 이름은 김흥국의 호를 따서 지은 것이다. 건물은 앞면 3칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 장식한 익공 양식으로 꾸몄다. 신흠이 쓴 팔경시판(八景詩板)이 걸려 있다. 부여 백마강변의 자온대 위쪽에 서 있으며, 부여 팔경의 하나로 경치가 매우 뛰어나다.","a":"수북정","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661049.jpg"},{"q":"勝山文中의 入鄕祖이자 조선시대 西班 종9품인 展力副尉를 지낸 허문손의 아들인 ○○는 將仕郎 箕子殿 參奉을 지냈으며, 부인인 ○○강씨는 함안군수를 지낸 姜叔卿(1428~1481)의 이녀 강ㅇㅇ이다. 족보 속 문헌에 의하면 ○○ 묘비는 春秋館 修撰官을 지낸 趙舜(1467~1529)이 찬하였고, 嘉靖 元年(1522) 2월에 세웠으며, 진양강씨묘비는 經筵參贊官 春秋館 修撰官을 지낸 鄭士龍(1491~1570)이 찬하였고, 嘉靖 6년(1527) 2월에 세운 것으로 기록되어 있다.","a":"진주 허추 부부 묘 석물","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2018053116105100.jpg"},{"q":"거창 신씨 집성촌인 황산마을에 있는 옛 집이다. 지금 있는 건물은 1927년 옛 건물을 헐고 다시 지은 것으로 ‘원학고가(猿鶴古家)’라고도 부른다. 건물은 안채, 사랑채, 중문채, 곳간채, 솟을대문, 후문 등으로 구성되어 있다. 검소한 양식에 서민 전통한옥의 특징을 잘 갖추고 있는 집이다.","a":"거창황산리신씨고가","c":"시도민속문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1659056.jpg"},{"q":"○○○란 병인양요와 신미양요를 승리로 이끈 흥선대원군이 서양사람들을 배척하고 그들의 침략을 국민에게 경고하기 위해 서울 및 전국 각지에 세우도록 한 비로, 이 비도 그 중의 하나이다. 낮은 사각받침돌 위에 비몸을 세우고, 맨 위에 지붕돌을 올려놓아 다른 ○○○와는 다른 모습이다. 이는 당시 대원군의 명으로 ○○○를 곳곳에 세우자, 이 지역의 관청에서 그것을 본 떠 세우면서 양식을 달리 한 것으로 보인다.","a":"남해 척화비","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664570.jpg"},{"q":"고려 때 이부시랑을 지낸 하광신의 지극한 효성을 기리기 위하여 조정에서 세운 비(碑)와 각(閣)이다. 하광신은 원래 중국 송나라의 대도독으로서, 고려시대부터 우리나라에 정착하면서 살게된 하흠의 아들 하용의 손자이다. 어릴 때부터 효성이 지극하였다고 하는데, 매서운 찬바람이 불어치는 겨울에 복숭아를 구해다준 전설적인 이야기가 전한다. 하광신의 효성이 지극하다는 소식을 들은 충숙왕(1327)은 하광신이 살던 마을에 효자를 표창하기 위해 세우는 붉은문<정문(旌門)>을 세우고 그의 자손들에게 대대로 부역을 면제하도록 하였다.","a":"하효자정려각","c":"문화유산자료","nc":"","r":"대구광역시","s":"수성구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659476.jpg"},{"q":"개국신화의 주인공인 단군 왕검의 초상화이다. 우리나라 개국신화는 그 내용이 약간씩 다르지만『삼국유사』와『제왕운기』에 전해지고 있는 내용을 보면 다음과 같다. “환웅이 아버지인 환인의 허락을 받아 하늘에서 내려와 태백산에 살기 좋은 인간세상을 건설하고자 하였다. 그 후 곰이 변한 웅녀와 혼인하여 인간인 왕검을 낳았다. 그는 평양에 도읍을 정하고 나라이름을 조선이라 하고 1908년의 수를 누린 끝에 아사달산의 산신이 되었다. ” 단군 왕검의 초상화는 전국 각지에 모셔두고 있지만 형태가 모두 다르다.","a":"부여천진전단군화상","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019051414471400.jpg"},{"q":"건륭 59년 5월 (정조 18년, 1794) 선박 관리소 에서 갑인년에 소봉할 각종 진상마을 제주도 삼읍배로 나누어 실어 내보낼 보고서로 사공의 이름과 배의크기 그리고 말의 수가 기록 되었다.","a":"보초등록","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643350.jpg"},{"q":"○○○ 표충사에 모셔져 있는 청허당 서산대사를 비롯한 세 분의 선사 영정이다. 세 분의 선사는 임진왜란 때 의병을 일으켜 나라를 구한 승병장으로서 큰 공을 세웠다. ○○○은 ○○○ 일주문에서 서쪽으로 약 200m 남짓 떨어진 곳에 있는 암자인데, 특히 사명대사가 입적한 곳으로 유명하다. 사명대사가 입적한 이곳에 그의 스승인 서산대사의 영정을 중심으로 왼쪽에 기허당대선사영정이 있고, 오른쪽에 사명당대선사의 영정이 배치되어 있는데 모두 의자에 앉아 있는 모습이다.","a":"합천 해인사 홍제암 삼화상 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642323.jpg"},{"q":"조선 제9대 왕인 성종의 세 번째 아들 ○○○ 이항安陽君 李㤚(1480~1505)과 부인 능성 구씨(1480~1556)의 합장묘이다. 성종의 뒤를 이어 연산군이 왕으로 즉위하였는데, 연산군은 자신의 친어머니가 폐위된 일에 ○○○의 어머니이자 성종의 후궁인 귀인 정씨가 관여된 것을 알게 되어 관련된 인물을 처형하는 갑자사화를 일으켰다. 이로써 ○○○은 유배 간 후 이듬해인 1505년에 죽음을 맞았다. 중종이 왕위에 오른 후에 ○○○의 장례를 치르고 무덤을 정비하였다. 능성 구씨 부인은 묘지명이 남아 있어서 그 생애를 알 수 있다.","a":"전주이씨 안양군묘","c":"시도기념물","nc":"","r":"경기도","s":"군포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2021102813171600.jpg"},{"q":"○○○는 신라 흥덕왕 8년(833)에 무염국사가 세운 절이다. 흥덕왕 초년에 무염국사가 웅동 지방에 침입한 왜구를 물리친 기념으로 왕이 무염에게 재물과 전답을 시주하여 구천동에 터를 골라 이 사찰을 지었다고 한다. 세울 당시에는 500여 명이 머물렀던 대사찰이었으나, 세운지 276년만에 화재를 입어 대장리로 옮겨 지었다. 조선 현종 9년(1668)에 또 다시 화재를 입어 구천동으로 옮겼다가 정조 13년(1789)에 현재의 위치에 세웠다.","a":"창원 성흥사 대웅전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641742.jpg"},{"q":"◦ 남포현의 치소(治所)는 웅천읍 수부리에 있었으나, 조선 세종 때, 지금의 ○○○○으로 옮기면서 세종 28년(1446)에 주민통치와 외적 침입 시 방어를 위해 돌로 성을 쌓았고, 현재 성(城)의 길이는 790m 정도임. ◦ 축성 초기에는 왜구 방어를 위한 군사 기지적 성격이 강했으나, 점차 왜구의 침입이 줄어들면서 행정치소로 기능하였음.","a":"남포읍성","c":"시도기념물","nc":"","r":"충청남도","s":"보령시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1651817.jpg"},{"q":"○○○는 변산반도 남단에 있는 절로 백제 무왕 34년(633)에 혜구두타(惠丘頭陀)가 지었으며, 소래사라 하였다. 소래사가 ○○○로 바뀐 것에 대한 사료적 근거는 없지만, 중국의 소정방이 이 절을 찾아와 시주한 것을 기념하기 위해서 고쳐 불렀다고 전한다. 인조 11년(1633)에 다시 짓고, 고쳐서 오늘에 이르고 있다. ○○○ 경내에 있는 ○○○○ 요사는 서로 연결되어 있는 건물이다. ○○○은 인조 18년(1640)에 청영대사가 지은 것으로 앞면 6칸·옆면 3칸의 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다.","a":"내소사설선당과요사","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639555.jpg"},{"q":"서하면 봉전마을은 정여창 선생의 처가가 있는 마을로서 선생이 처가에 들러 유할때는 군자정이 있는 영귀대에서 유영하였다. 정선전씨 입향조인 화림재 전시서 공의 5대손인 전세걸, 세택이 일두선생을 기념하기 위해 1802년 이곳에 정자를 짓고 군자가 머무르던 곳이라 하여 군자정으로 칭하였으며 이후 몇 차례의 보수가 있었으나 내용을 알 수 없다. 군자정은 거연정으로부터 하류쪽으로 150m 정도의 거리에 위치하고 있으며 정면 3칸, 측면 2칸 규모이나 정면의 주칸을 5자, 측면의 주칸을 4자 정도로 잡아 규모는 작은 편이다.","a":"함양군자정","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665576.jpg"},{"q":"○○○ 마을입구에 봉안된 불상이다. 신체의 하반부는 완전히 사라져서 남아 있지 않다. 남아 있는 상반부의 신체도 마멸이 심해 세부를 알아보기는 어렵다. 머리에는 육계(肉髻; 상투 모양의 머리묶음)가 희미하게 남아 있으며 계란형의 얼굴 또한 표면이 마멸되어 세부를 알아볼 수 없다. 목은 짧지만 삼도(三道; 붓다의 지혜를 상징하는 세 줄의 주름)는 흔적이 남아 있다. 두꺼운 법의(法衣; 승려들의 겉옷)가 양쪽 어깨에 걸쳐져 있으며, 옷자락은 길게 늘어진 ‘U’자 모양을 형성하며 배 앞으로 흘러내리고 있다.","a":"이평리석불입상","c":"문화유산자료","nc":"","r":"경기도","s":"이천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660075.jpg"},{"q":"각화사에 놓여 있는 비받침돌로, 고려 전기 문신인 좌간의대부 김심언이 세웠던 ‘통진대사비(通眞大師碑)’의 일부로 전하고 있다. 바닥돌과 하나의 돌로 이루어져 있으며, 등 중앙에 마련된 비좌(碑座:비몸을 꽂아두는 네모난 홈)는 약간 파손되긴 하였으나 거의 본 모습을 갖추고 있다. 등무늬는 6각형이 전면에 덮혀 있고, 그 안마다 ‘王’자와 ‘佛’자를 도드라지게 새겼다. 대체적으로 고려 전기의 정교하고도 웅대한 조각솜씨를 이어받고 있으나, 몸통에 비해 머리가 작은 감이 든다.","a":"각화사귀부","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640659.jpg"},{"q":"○○○ 극락전 앞에 서 있는 탑으로, 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 바닥돌은 후대에 새로운 돌로 보수한 상태이며, 기단과 탑신의 몸돌 모서리마다 기둥 모양을 새겨 놓았다. 지붕돌은 낙수면이 짧고 처마가 얇은데 비해 밑면에 새긴 4단의 받침이 높직하다. 극락전의 장중한 규모에 비해 석탑의 높이가 2.6m로 너무 작아 서로 잘 조화되지 않는 듯한 느낌을 주고 있다. 전체적으로 통일신라의 석탑양식을 따르고 있으나 기단이 1층으로 줄어들고, 지붕돌의 조각양식이 변화한 것으로 보아 고려시대에 세운 것으로 추정된다.","a":"용연사삼층석탑","c":"문화유산자료","nc":"","r":"대구광역시","s":"달성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659488.jpg"},{"q":"『○○○○』는 본래 중국 송나라의 여정덕이 주자가 여러 문인들과 교류하며 주고받은 문답(問答)을 모아 편집한 책이다. 모두 50책이나 되는 방대한 양으로, 조선시대 우리나라의 유학자들이 성리학을 공부하면서 반드시 읽어야 할 책이었다. 선조 8년(1575)에 우리나라에서는 처음으로 간행되었으나, 임진왜란 때 모두 불타버렸고, 인조 때 다시 영남감영에서 간행했지만 이것마저도 불에 타버렸다.","a":"주자어류 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641758.jpg"},{"q":"○○○○는 사찰 입구에 설치하는 것으로, 절에 행사나 의식이 있을 때는 당이라는 깃발을 걸어두는데, 이 깃발을 다는 길쭉한 장대를 당간이라 하며, 당간을 양쪽에서 지탱시켜주는 두 돌기둥을 ○○○○라 한다. 원주시 ○○○ 내천 옆에 자리한 이 ○○○○는 원래 통일신라시대에 창건된 사찰내에 서 있던 것이라 한다. 기단부(基壇部)가 땅에 묻혀 있어 그 모양을 알 수 없으며, 좌우 두 기둥과 기둥사이의 당간받침돌만이 남아있다.","a":"봉산동당간지주","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637978.jpg"},{"q":"성재 허전 선생의 영정을 모시기 위해 세운 곳이다. 허전 선생(1797∼1886)은 조선 후기의 문신으로 성호학파의 계승자였으며 헌종 1년(1835)에 과거에 급제하였다. 그는 경연에 참여하여 국왕에게 유교경전을 해설하는 학자 관료의 일을 하였다. 그의 사상은 주로 경연에서 경의(經義)와 관련하여 항상 실심(實心)·실정(實政)을 강조하였고, 현실에 투철하여 전체적인 개혁안을 제시하였다. 저서로는 『성재집』과 선비의 생활의식을 집대성한 『사의(士義)』가 있다. 해마다 3월 3일 이곳에서 석채례(釋采禮)를 지내고 있다.","a":"산청 이택당 물산영당","c":"문화유산자료","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663922.jpg"},{"q":"○○○○○는 ○○읍 동원(東院) 앞 하천에 조선시대(1686년 윤 4월)에 설치한 돌다리의 건립을 기념한 비석으로 앞면에는 ○○○○의 건립과정, 뒷면에는 건립 참여자 명단이 기록되어 있다. ○○○○○는 ○○ 개흥사 계수스님이 ○○읍에서 성 밖으로 사람들의 안전한 통행을 위하여 1685년 정월 초 발원, 지역민 시주를 모아 건립을 주도, 오봉산 돌을 깎아 군수 박립의 조력으로 석재를 운반하고 완공하였다.","a":"보성 동원석량비","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"보성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019041914503200.jpg"},{"q":"이곳은 조선 영조 4년(1728)의 무신란 때 순절한 충강공 이술원 장군을 모신 사당으로 영조 13년(1737)에 세웠다. 이술원 장군은 조선 후기 무신이며 ○○ 출신으로 영조 4년(1728)에 ○○ 좌수로 있었다. 안의의 정희량이 난을 일으키자 나아가 대적하였으나 중과부적으로 생포되어 모진 고문에도 굴하지 않다가 죽음을 당하였다. 시호는 충강(忠剛)이다.","a":"거창 포충사","c":"문화유산자료","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663941.jpg"},{"q":"반계사에 모셔진 조선 선조 때의 정경달(1542∼1602)과 관련된 자료들이다. 반계사는 숙종 40년(1714)에 영광 정씨 문중이 중심이 되어 건립한 것으로,영광 정씨의 정인걸, 정경달, 정명설, 정남일 네 사람과 임진왜란과 정유재란 때 큰 공을 세운 이순신, 임영립을 모시고 제사를 지내는 건물이다. 고종 5년(1868) 훼손 되었던 것을 1957년 지금의 자리에 강당을 새로 짓고, 1959년에 탑을 세워 사우로서의 기능을 대신케 하였다. 유물과 유품들을 살펴보면 다음과 같다.","a":"장흥 반계사와 소장유물","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640080.jpg"},{"q":"경상남도 ○○군에 있는 ○○○○은 산이면과 칠원읍 마산시 내서읍에 걸쳐 산 정상을 둘러싸며 만들었다. 성의 둘레는 480m 에 이르는데 동벽 190m, 서벽 180m, 남벽 50m, 북벽 60m 이며 성폭 5m, 외벽 높이 5∼6m 정도로 전체적인 윤곽이 뚜렷하다. 남동벽과 북벽을 흙으로 쌓았다고 착각하기 쉬우나 군데군데 남아 있는 돌로 쌓은 흔적과 흩어져 있는 돌 등으로 미루어 완전하게 흙으로 쌓은 것은 아님을 짐작할 수 있다.","a":"함안 포덕산성","c":"시도기념물","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1656260.jpg"},{"q":"임진왜란 때 전라도도사로 전주를 방어했던 난포 최공철이 지은 집이라고 전한다. 명종 원년(1545)에 지었다고 하는데, 건축양식이나 기법으로 보아서는 대략 17세기를 전후한 시기의 집으로 보인다. ‘가경 14년’(1809)이라고 쓰여진 막새기와가 발견되어, 순조 9년(1809)에 보수한 것을 알 수 있다. 원래는 정침·아랫사랑·중사랑·방아실·행랑채와 마루 그리고 사당 등이 고루 갖추어진 집이었으나, 지금은 정침·행랑채·사당만 남아있다. 정침은 앞면 7칸·옆면 1칸 반의 규모로 ㅡ자형이며 지붕이 특이하다.","a":"난포고택","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640380.jpg"},{"q":"이 탑은 원래 효공왕릉(孝恭王陵) 부근인 경주시 동방동 장골 사자사(獅子寺) 터에 무너져 있던 것이다. 1936년 경주역을 지금의 위치로 옮기는 것을 기념하여 이곳에 다시 세웠다. 큼직한 2단 받침 위에 4개의 돌을 사용하여 기단을 올렸는데 모서리기둥을 조각하였다. 위에 덮개돌을 올리고 바로 모서리기둥을 조각한 1층 몸돌을 놓았는데 몸돌 받침이 원래 없었는지 잃어버린 것인지는 알 수 없다. 1층 지붕돌의 아랫면에는 4단의 층급받침을 나타내었다. 2층과 3층 몸돌은 1층에 비해 폭은 많이 줄지 않고 높이는 아주 낮아졌다.","a":"경주황오동삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662359.jpg"},{"q":"조선 중기 진무성 장군의 위패를 모신 사당으로 봄, 가을에 제사를 지내고 있다. 송계 진무성 장군은 조선 중기 무신으로 선조 25년(1592) 임진왜란이 일어나자 이순신 장군 휘하의 군관으로 공을 세우고 용명을 날렸다. 인조 5년(1627) 정묘호란이 있은 뒤에는 공로가 인정되어 북방요지 구성군수에 임명되기도 하였다. 순조 26년(1826)에 고흥군 대서면 상남리에 용강사를 지어 진무성 장군 및 3분의 위패를 모셨으나, 고종 5년(1868)에 서원철폐령으로 해체되었다가 고종 19년(1882)에 이곳에 복원하여 무열사라 하였다.","a":"고흥무열사","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"고흥군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654151.jpg"},{"q":"고려 충렬왕 7년(1281)에 중국 원나라 세조가 2차례의 일본 정벌에 실패한 뒤, 그해 10월에 환주산(지금의 ○○시 마산합포구 추산공원 일대)에 군사를 배치하고, 진(鎭)을 설치하였다. ○○○은 이곳에 주둔한 군사들에게 마실 물을 공급하기 위해 만든 우물로 추정되고 있다. 우물 앞에 ○○○이라고 쓰인 비석은 1932년 일본인 고적단체에서 세운 것으로, 그 전에는 고려정이라 불렀다고 한다.","a":"창원 몽고정","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664009.jpg"},{"q":"○○○는 조선조 선조 26년(1593) 6월 29일, 임진왜란 제2차 ○○성 전투에서 ○○성이 함락되고, 7만 민관군이 순절하자, 나라의 원수를 갚기 위해 왜장을 끌어안고 순국한 의기 논개를 제향하기 위해 세운 사당이다. 인조 7년(1629) ○○의 선비들은 논개가 순국한 바위에 의암(義巖)이라는 글자를 전각하였고, 경종 2년(1722)에는 그 위쪽에 「의암사적비」를 세웠다. 영조 16년(1740) 병사 남덕하(南德夏：1688∼1742)는 의기정포(義妓旌褒)를 계청하여 왕의 윤허를 받아 ○○○를 창건하였고, 이후 세 차례의 중수와 중건이 있었다.","a":"진주 의기사","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663792.jpg"},{"q":"○○○ 소장 칠성여래목각탱은 10매의 판목을 세로로 나란히 배치한 후, 상하좌우에서 각 1매의 목재로 고정시켜 틀을 만들어 화면을 형성한 것이다. 칠성불화를 목각에 묘사한 이 작품은 조선후기에 제작된 몇몇의 현존 목각탱이 浮彫와 透彫를 병행한 것과 달리, 부조의 단조로운 형식을 취하고 있다. 칠성여래목각탱의 구성은 치성광여래를 중심으로 좌우 일․월광보살이 협시하고 있다. 이 삼존을 중심으로 좌우에는 7위의 七元星君과 太上老君이 있으며, 그 위로 7여래가 있으며, 이 존상들은 수평으로 3단을 이룬다. 권속들은 1/4정도로 안면을 측면을 틀어 본존을 향하고 있다.","a":"단양 방곡사 목조칠성여래설법상","c":"문화유산자료","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2022072115385900.JPG"},{"q":"고려 인종 때 공신으로 ○○ 송씨의 시조인 ○○의 ○○이다. ○○은 고려 인종 4년(1126) 이자겸의 난 때 인종을 호위하다가 척준경의 반란군들에 의해 살해당했다. 난이 끝난 후 평장사(平章事)라는 고려시대 최고의 벼슬자리에까지 이르렀다. ○○은 ‘○○백’이라는 벼슬을 지냈는데, 당시 ‘백’이라 하면 그 고을의 행정, 사법은 물론 경제에 관한 모든 일들을 다스리는 높은 벼슬이었다. ○○은 ○○백으로 있을 때 고을 사람들이 보다 편안하게 살 수 있도록 밤낮으로 노력하였으며 모든 일을 공정히 처리하였다.","a":"진천 송인 묘소","c":"시도기념물","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1650264.jpg"},{"q":"국가의 평안함과 남해안 지역의 풍년을 기원하기 위하여 국가 주관으로 남해신령께 제사지내던 제사터이다. 우리나라는 고려시대부터 동해의 양양, 서해의 풍천, 남해의 나주 등 3곳에 해신당(海神堂)을 두고 국가에서 제사를 거행하였다. 남해당은 그 3곳 중의 하나로서 『신증동국여지승람』에 봄·가을로 향과 축문을 내려 제사한다고 기록되어 있다. 그러나 1910년 일본에 의해 우리나라의 주권을 빼앗긴 후 제사가 중단되었다. 남·북을 일직선으로 하여 중앙에 6m정도의 당터가 있고, 내삼문과 외삼문 그리고 제각지기 집터가 확인되고 있다.","a":"남해당지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654246.jpg"},{"q":"○○○○○의 상단부에는 음각으로「南無阿彌陀佛」이라고 깊이 새겨져있으며, 각 글자의 너비는 약 14cm정도이다. 그리고 우협시보살상의 우측에는 縱으로 약 4cm 정도의 너비의 글자가 음각으로「世尊應化二千九百三十三年四月 日」이라고 새겨져 있다. 또한 삼존의 아래에는 ‘姜膺秀’, 삼존이 새겨진 암석의 향좌측 측면 암석에는 향좌부터 ‘李瑀榮’, ‘安珪行’, ‘郵創玉’, ‘鄭基南’의 발원자명이 음각되어 있다. ○○○ 법당 동쪽면의 암석에 ○○○○○이 조각되어 있다.","a":"양산원효암마애아미타삼존불입상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642605.jpg"},{"q":"이 영정은 정유재란에 공을 세운 명나라 장수 ○○제독(1541～1612) 영정으로 명주바탕에 채색을 한 좌안8분면의 금관조복의 차림으로 호피를 두른 의자에 앉은 채 양손을 모아 공수자세로 홀을 쥐고 있는 전신교의좌상이다. 인물의 안면부는 주색으로 윤곽선을 그리고 살색으로 채색하였으며 양쪽 볼과 이마, 귓불과 귓구멍에는 주색을 부드럽게 펴 발라 음영을 주었다. 콧수염과 턱수염 등의 모근은 세필의 먹선과 백선으로 자연스럽게 표현하였는데 특히 귓수염과 향우측 턱수염자락은 자연스럽게 바람에 날리는 모습으로 그려내었다.","a":"합천 충무후 마귀 초상","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666292.jpg"},{"q":"선조 35년(1602)에서 광해군 7년(1615) 사이에 조정에서 내암 ○○○ 선생의 조상들과 선생의 부인 및 후손에게 내린 ○○교서들로, 총 17점이다. ○○○은 조선 광해군 때의 문신으로, 선조 6년(1573) 황간현감으로 재직하면서 많은 선행을 베풀었으며, 임진왜란이 일어나자 합천에서 의병을 모아 왜군을 물리쳤다. 선조 35년(1602) 대사헌으로 승진하고 그 후 좌참찬, 우의정, 좌의정, 영의정을 지냈다. 그러나 인조반정 때 집권 서인들에게 억울하게 죽임을 당하였다.","a":"정인홍 선대 증직 교지","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642264.jpg"},{"q":"이 백자항아리는 직립한 구연과 팽창되어 있는 어깨, 하단부로 내려오면서 측사면이 안쪽으로 살짝 휘어진 형태를 지닌 조선후기의 전형적인 입호(立壺)이다. 회화자료를 통해 본 입호의 용도는 일상생활보다는 각종 행사에서 자주 활용하던 그릇이었다. 본 항아리는 물레성형 방식으로 만들었으나 내면 벽에 상부와 하부를 따로 만들어 접합한 흔적이 남아있다. 항아리 제작에서 사용된 흙은 백점토이나 미세한 잡물이 섞여 있고 유약으로 인해 옅은 회백색의 색감이 드러난다.","a":"백자청화모란문호","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"유성구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637236.jpg"},{"q":"태안읍의 뒷산 백화산 줄기의 동남편 산중턱에 자리한 고려시대 절인 ○○○의 중문이다. 중종 25년(1527)에 처음 지어지고 그 후 4차례에 걸쳐 다시 지었고, 1944년에 해체·복원하여 지금에 이르고 있다. 앞면 3칸·옆면 3칸 규모이며, 지붕 옆면이 사람 인(人)자 모양인 맞배지붕집이다. 경사진 곳에 자연석으로 축대를 쌓고 지었기 때문에 밖에서 보면 2층이지만 안에서 보면 단층건물로 보인다.","a":"흥주사만세루","c":"시도유형문화유산","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639225.jpg"},{"q":"석곡리 마을회관 내에 자리하고 있는 탑으로, 이곳에서 조금 떨어진 옛 절터에서 옮겨왔으며, 함께 발견된 석곡리미륵불(충청남도문화유산자료)이 옆에 남아 있다. 탑은 1층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습인데, 탑신부의 3층 몸돌은 없어진 상태이다. 기단은 네장의 판돌을 세워 4면을 이루고 있고, 각 면의 모서리와 가운데에 기둥 모양을 새겨두었으며, 탑신부의 각 몸돌에도 모서리마다 기둥 모양을 새겨 놓았다. 지붕돌은 밑면에 3단씩의 받침을 두고 있고, 처마는 수평을 이루다 네 귀퉁이에서 살며시 들려 있다.","a":"석곡리석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661201.jpg"},{"q":"해남 ○○○○○는 우리나라에서 초기 청자 가마가 집단적으로 분포하고 있는 유일한 곳으로 우리나라 초기 청자의 발생을 살필 수 있는 곳이다. 따라서 우리나라 자기 발생의 단서와 초기 청자의 기형 변화를 파악하는데 매우 중요한 가마터로 주목받고 있다. 이곳에서 출토된 유물은 청자, 흑유, 도기, 요도구 등으로 청자의 기종은 대접과 완, 접시, 화형접시, 병, 유병, 편병, 항아리 등이다. 이 곳 ○○○○○는 신덕리 일대에서 54곳, 금평리 일대에 2곳 등 개별 가마터 80~90기가 분포하는 것으로 추정하고 있다.","a":"해남화원면청자요지","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019052021284700.jpg"},{"q":"앞쪽에 누마루를 둔 ㄱ자형의 평면 형태와 견실한 구조, 치목수법, 치밀한 석재가공과 시공 등이 뛰어난 건물임. 특히 독특한 살 짜임의 청방간 분합 들문, 마루 배면의 판문, 온돌방 전면의 창호 및 머름구성이 매우 짜임새가 있고 품격이 높은 형식을 보여줌. 기둥 상부의 소로수장, 아름다운 창호구성, 마루 상부의 우물반자 구성에서 근대기 한옥의 건축적 특징과 장식적 경향을 잘 보여줌.","a":"밀양 혜남정","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666365.jpg"},{"q":"나지막한 언덕에 자리하고 있는 옛집으로, 조선 숙종(재위 1674∼1720) 때 이조판서를 지낸 이자가 고향으로 돌아와 지은 것이라 한다. 지은 연대는 정확히 알지 못하며, 90여 년 전에 안채를 크게 수리하였다고 한다. 안채와 사랑채가 ㅁ자형으로 배치되었고, 동남향을 하고 있다. 1m 정도의 비교적 높은 기단 위에 지었으며, 여덟 팔(八)자 모양의 화려한 팔작지붕집이다. 안채는 영동지방에서 흔히 볼 수 있는 겹집형에, 영서·중부지방에서 일반적인 대청과 건넌방이 ㄱ자형으로 접하여 있다.","a":"정선 수고당 고택","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"정선군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2016051721241200.JPG"},{"q":"이 석불좌상은 신라통일 직후인 7세기 후반부터 유행하기 시작하여 신라 일대와 그 후 고려 초기에 이르기까지 계속된 여래좌상의 기본양식을 갖추고 있는데 역함을든 수인으로 보아 전형적인 약사여래좌상이다 그 가운데 독특한 점은 약함의 모양인데 구형의 소옹기에 뚜껑이 있는 보기드문 양식을 보이고 있다.","a":"밀양 영산정사 석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642380.jpg"},{"q":"승려 처영에게 하사한 구리로 만든 도장이다. 처영은 조선 선조 25년(1592) 임진왜란이 일어나자 ○○○○의 승병장이 되어 성을 크게 수축하고 전란에 대비하였다. 이에 조정에서 산성별장(山城別將)임을 증명하는 의미로 이 도장을 새겨 하사하였다. 도장은 산성내의 선국사 주지에게 대대로 전해내려 오다, 동학혁명군 김개남이 ○○○○을 본거지로 활동할 때 잃어버렸던 것을 1960년 당시의 주지였던 보월 스님이 발견하여 지금에 이르고 있다. 가로 6.3㎝, 세로 7.8㎝, 두께 1.5㎝의 크기로, ‘○○○○○인(蛟龍山城僧將印)’이라는 7글자를 세로로 2줄 새겨 놓았다.","a":"교룡산성승장동인","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658318.jpg"},{"q":"2권 1첩(첩장본)이고 규격은 26.3×10cm이다. 판식은 상하은니단변(上下銀泥單邊), 상하(上下) 간(間) 17.1cm, 장 크기 26.3×89.4cm에 54행 16자가 배열되었고 9절(折)하여 첩장하였다(8장연결). 권수제는 감지은니범망경노사나불설보살심지계품제10권하(紺紙銀泥梵網經盧舍那佛說菩薩心地戒品第十卷下)이고 권미제(卷尾題)는 수보살계법(受菩薩戒法)이다.","a":"감지은니범망경보살계 및 보살계의","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636444.jpg"},{"q":"○○의 본관은 옥천(沃川)이고 호는 ○○, 자는 정원(淨遠), 시호(諡號)는 충간공(忠簡公)이며 충북 옥천의 목담서원, ○○ 옥동서원에 배향되어 있다. 홍문관 교리․대사성․대사헌 이조참판․응교․부제학․의정부 좌찬성․좌의정 지중추부사 겸 경연춘추관사를 역임하였다. ○○의 상산삼로(商山三老)로 칭송되는 당대 영남학파의 대표적인 문인으로 문장은 으뜸으로 꼽히며, 청렴결백한 성품을 지닌 것으로 널리 알려져 있다. ○○○는 1700년(숙종26)에 세운 것으로, 이수(螭首)의 용문(龍紋)이 사실적이며, 귀부(龜趺)도 매우 힘차게 조각되어 있는 점이 특징적이다.","a":"상주 사서 전식 신도비","c":"시도유형문화유산","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2019050917314000.png"},{"q":"김국광(1415∼1480) 선생의 사당이다. 김국광은 세종 23년(1441) 문과에 급제하여 벼슬길에 올랐고 세조의 즉위를 도와 두터운 신임을 얻게 되었다. 『경국대전』편찬에 적극적으로 참여하였으며 벼슬이 병조판서를 거쳐 우의정과 좌의정에 이르렀다. 인조 원년(1623)에 지은 ○○○는 앞면 4칸·옆면 3칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"모원재","c":"문화유산자료","nc":"","r":"충청남도","s":"계룡시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661397.jpg"},{"q":"현 소유자의 10대조가 세운 집으로 안채와 사랑채로 구분되는 ㅁ자형 평면을 가진 집이다. 집을 지을 당시에 현재 사랑채로 사용되는 건물을 먼저 짓고 그 뒤에 안채를 지은 것으로 보인다. 안채는 앞면 5칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 넓은 마루를 중심으로 양 옆에 방과 부엌을 배치하였다. 사랑채는 가운데 방 3칸을 배치하고 앞면에 툇마루를 놓았다. 툇마루 양 옆으로는 부엌과 창고를 마련하였다. 창고는 공간을 넓게 확보하기 위하여 앞으로 내밀고 앞면은 누마루 형태로 건물을 높였으며 방 앞쪽으로 툇마루를 놓았다.","a":"양양조규승가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660483.jpg"},{"q":"‘○○○○’은 석가모니를 상(像)으로 만들어 모신 불전의 이름으로, 불전 중에서도 가장 중심이 되는 건축물이다. 남양주 수락산에 있는 ○○○는 선조(宣祖)의 부친인 덕흥대원군(德興大院君)의 명복을 빌기 위해 왕실에서 후원한 곳으로, 지금 모습은 여러 번의 화재 이후 1821년에 다시 세우고, 1888년에 고쳐 지은 것이다. 이 건물은 기다란 화강석으로 기단을 쌓고, 원형으로 다듬은 주춧돌과 둥근 기둥으로 몸통을 구성하였다. 지붕은 옆에서 보면 ‘八(여덟 팔)’자 모양인 화려한 팔작지붕이다.","a":"흥국사대웅보전","c":"문화유산자료","nc":"","r":"경기도","s":"남양주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660023.jpg"},{"q":"이곳은 983년경 설치되었던 기성현(행정구역)의 관아 건물이 있었던 곳으로 알려져 있었다. 새로운 발굴 조사에 따르면 고려시대 막새기와를 비롯하여, 명문을 새긴 기와, 신라와 고려의 토기조각, 고려청자 조각, 분청사기 조각 등이 출토되었고, 형태를 알 수 없는 건물의 주춧돌을 발견하였다. 이로써 이 지역은 신라시대에서 고려, 조선 전기에 걸쳐 세운 건물이 있던 곳으로 예상하며, 주춧돌의 규모나 많은 기와조각으로 보아 당시의 관아와 같은 거대한 목조 건물을 배치하였던 것으로 추정한다.","a":"거제 고군현 치소지","c":"시도기념물","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655960.jpg"},{"q":"○○○○은 성월 윤탁(1554∼1593)의 공적과 학덕을 기리고 충효정신을 선양하기 위하여 광무 8년(1904)에 건립되었다. 윤탁은 훈련원 부정을 지내고 임진왜란이 일어나자 의령 곽재우 장군과 함께 의병을 일으켜, 의령·창녕 일대에서 활동하였다. 제1차 진주성 전투 때 진주목사 김시민을 도와 참전하였고, 제2차 진주성 전투에도 참전하여 성이 함락될 때 김천일, 최경회 등과 함께 전사하였다. 서당은 서당 1동과 대문채 1동으로 구성되어 있으며, 서당과 대문채를 일직선상에 배치하였다.","a":"합천 구산서당","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664894.jpg"},{"q":"○○○는 고려 공민왕 17년(1368)에 지공선사와 나웅선사에 의해 창건 되었으나 임진왜란시 화재로 소실되어 조선 선조 38년(1602)에 탄우대사가 중창하였고 숙종 13년(1687)에 중건하였다. ○○○○○은 건립 당시부터 ○○○으로 건립되었는지는 확실치 않으나 창호구성수법 치목방법 등 건축 수법에서 17~8세기의 형식들을 유지하고 있다","a":"의성대곡사명부전","c":"문화유산자료","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663464.jpg"},{"q":"충북 단양군에 있는 구인사에서 소장, 관리하는 백지묵서(白紙墨書) 《○○○○○》은 조선시대에 5명의 여성 불자가 각자 권을 나누어 한글로 베껴 쓴 불교 경전이다. 일명 '먹글씨 ○○○○○' 또는 '법화경'이라고도 한다. 7권 7책으로 이루어졌으며, 책의 크기는 가로 32.5cm, 세로 22.7cm이다. 《○○○○○》 필사(筆寫) 작업은 1909년 9월에 시작해 약 3개월 만인 같은 해 11월 25일 마지막 7권의 필사를 마쳤다.","a":"묘법연화경(언해)","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638884.jpg"},{"q":"조선 영조 때 ○○○○○를 지낸 ○○○ 선생의 유물로, 선생이 이인좌의 난 때 공을 세워 공신에 오르면서 왕으로 부터 하사받은 것이다. 총 8점인데, ○○○ 생원문과 및 부모추증교지 4건, 어사화, 공신녹권, 어필, 태평연도 등이다. 어필은 왕이 손수 쓴 글씨로, 크기는 가로 36.5㎝, 세로 102㎝이다. 태평연도는 창덕궁의 인정전에서 무신난을 평정한 후 잔치를 연 모습을 그린 그림으로, 크기는 가로 63.2㎝, 세로 117㎝이다.","a":"의금부도사김도언유물","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639601.jpg"},{"q":"사월(沙月) 조임(趙任)의 넷째아들인 사고(沙皐) 조정옥(趙廷玉)이 건립한 살림집으로 사두들 마을 안에 남서향하여 자리잡고 있다. 전면에 세운 5칸 규모의 솟을대문을 들어서면 사랑마당을 사이에 두고 정면 7칸 측면 4칸 규모의 口자형 정침이 자리잡고 있으며 정침의 우후측에는 사당이 별도의 공간을 이루며 배치되어 있다. 정침의 좌후측에는 손자인 주강(柱江) 조시광(趙是光)이 건립한 ○○○이 방형의 토석담장을 두른 별도의 공간안에 자리잡고 있으며, ○○○의 전면에는 주사(廚舍)와 별묘(別廟)가 각각 배치되어 있다.","a":"주강정및사고종택","c":"문화유산자료","nc":"","r":"경상북도","s":"영양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663562.jpg"},{"q":"○○○ 미륵전에 봉안된 목조여래좌상의 대좌는 석조로 조성된 8각의 ○○○과 고복형(鼓腹形)의 중대석 및 목조연화좌인 상대석 등 상․중․하 3단으로 이루어져 있다. 그 중 폭이 147㎝에 이르는 규모가 큰 8각의 ○○○은 현재 모서리와 면석 일부분이 결실되었고 표면 곳곳에 불에 탄 흔적이 있으나, 전체적인 원형은 잘 남아 있는 편이다 ○○○의 하부는 우주(隅柱, 모서리 기둥)는 표현되지 않고 아래 위에 각각 단을 이루고 있으며, 가운데 면석에는 안상(眼象)이 1구씩 얕게 새겨져 있다.","a":"범어사 석조연화대좌 하대석","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636740.jpg"},{"q":"○○○○○은 충청남도 논산시 부적면 고정산 정상 남쪽 바위면에 얕게 선각(線刻)한 높이 3.5m의 불상이다. 전체적으로 큰 얼굴, 가늘고 긴 눈, 넓적한 코, 작은 입 등 고려시대 지방 불상양식의 특징을 잘 보여준다. 머리는 육계(肉髻, 상투 모양의 머리)와 나발(螺髮, 부처의 머리카락. 소라 껍데기처럼 틀어 말린 모양)은 비교적 크게 표현되었고, 어깨는 넓고 평행하게 표현되어 당당한 분위기를 주지만, 도식화된 형식미가 강하게 나타난다.","a":"논산신풍리마애불","c":"시도유형문화유산","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639095.jpg"},{"q":"○○○○○는 조선후기 지리학자인 고산자 김정호가 순조 34년(1834)에 자신이 만든 <청구도>를 27년 후에 증보 수정한 대축척 지도로 분첩절첩식지도첩이다. 형태를 보면, 남북을 120리 간격으로 22층으로 구분하고, 동서를 80리 간격으로 끊어 19판으로 구분했음. 동서방향은 구획된 판을 접어서 연결시켜 1첩으로 만들어 쉽게 볼 수 있도록 했음. 남북으로 동서의 방향을 연결시킨 각 첩을 펼쳐서 순서대로 이어대면 연속된 남북을 볼 수 있게 했음.","a":"대동여지도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거창군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642128.jpg"},{"q":"○○시 불모산 서쪽에 자리하고 있는 ○○○는 통일신라 흥덕왕 10년(835) 왜적의 침입을 막기 위해 무염국사가 창건한 사찰이다. 사찰내에 있는 많은 국가유산 가운데 하나인 이 탑은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 모습이다. 현재 아래층 기단은 일부만 남아 있고, 위층 기단에는 네 모서리와 면의 가운데에 기둥모양의 조각을 두었다. 탑신은 1층 몸돌에 간단한 문짝모양이 새겨져 있다. 지붕돌은 밑면의 받침이 4단이고 처마선은 완만한 곡선을 이루고 있으며, 네 귀퉁이는 치켜올림이 심한 편이다.","a":"창원 성주사 삼층석탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641374.jpg"},{"q":"○○○는 신라 헌강왕 11년(885)에 조구선사(祖丘禪師)가 창건하였다. 창건 당시 절 앞에서 캐낸 금으로 불상을 만들었기 때문에 절 이름을 ○○○라고 하였다 한다. 임진왜란 때 소실된 것을 고종(재위 1863∼1907) 때 명성황후가 다시 세웠다. ○○○○○은 정면 3칸 · 측면 2칸의 규모의 다포식 맞배지붕 건물로 고풍스런 모습을 잘 간직하고 있다. 전내에는 주존인 석가모니불을 중심으로 좌우에 문수보살과 보현보살이 봉안되어 있다.","a":"보석사 대웅전","c":"시도유형문화유산","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639239.jpg"},{"q":"자연 암벽 위에 ‘증주벽립(曾朱壁立)’이라는 글씨를 새긴 것으로, ○○○○○의 친필이다. 이곳은 ○○이 살던 옛 터로, ‘○○구기(尤菴舊基)’라고 새겨진 비석이 함께 남아 있다. ○○은 평생을 주자학 연구에 힘쓴 조선시대의 유학자로, 율곡 이이의 학문을 계승하였다. 효종이 세자로 있을 때 그의 스승이 되었으며, 이후 효종이 청을 정벌하려는 계획을 세우자 적극 참여하기도 하였다. 바위에 새겨진 이 글에는 증자(曾子)와 주자(朱子)의 사상을 계승하고 실천하려한 ○○의 확고한 신념을 그대로 담아내고 있다.","a":"우암 송시열 집터","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636206.jpg"},{"q":"조선시대 ○○부 소속 7개 진영중의 하나였던 장목포진의 관아건물이다. 세워진 시기를 정확히 알 수 없으나, 장목리 동구에 있던 것을 정조 9년(1785)에 이곳으로 다시 옮겨 지었다고 한다. 한려해상의 입구에 자리잡고 있어 진해만 일대를 방어하고 대한해협을 바라보기 위한 전략의 요충지였던 이곳은 항상 장수들이 모여 이곳에서 전략을 의논하는 장소로 사용되었다. 임진왜란 때에는 이순신과 이영남 장군이 전략을 모의했다고 한다. 앞면 4칸·옆면 2칸 규모로 지붕이 여덟 팔자 모양인 팔작지붕집이다. 순조 2년(1802)에 다시 지어 조선 후기 건물의 형식을 띠고 있다.","a":"거제 장목진 객사","c":"시도유형문화유산","nc":"","r":"경상남도","s":"거제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641808.jpg"},{"q":"김용현의 시신을 장지까지 운반하기 위해 제작된 기구로, 당시 2000석 지기였던 그의 아들이 서울에서 목재를 사오고, 중국에서 공단과 실을 수입하여 만든 것이라 전한다. 가문에서 3대째 대물림하여 사용하던 것을 그의 증손자인 김현장이 1971년 광주시립박물관에 기증함으로써 이곳에 보존되고 있다. 크기는 길이 312㎝, 너비 132㎝, 높이 220㎝ 로, 2층 목조기와집 형태이다. 36명이 멜 수 있도록 조성된 멜대 위에 2층 기와집 형태의 몸체를 올리고, 맨 위에 햇빛을 가리기 위한 넓은 천을 드리운 후 그 밑에 청사초롱을 달았다.","a":"강진김해김씨가상여","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658119.jpg"},{"q":"조선 세종의 아들인 임영대군의 후손인 ○○○○○는 광해군 6년(1614)에 명문가에서 태어나 행실이 바르고 효성이 지극했던 ○○는 어릴 때 부친이 병들어 눕자 곁을 떠나지 않고 백방으로 약을 구하여 극진히 봉양하였다. 부친이 위독해지자 ○○는 서로 손가락을 깨물어 피를 입에 흘려 넣는 등 정성을 다하였으며 세상을 떠나자 장례를 치르고 묘막을 짓고 3년간 시묘살이를 했다. 또한, 이후 모친이 위독해지자 이들 ○○는 부친때와 같이 지극한 정성으로 봉양하였으나 세상을 떠나자 장례를 치른 후 묘막을 짓고 3년간 시묘살이를 하였다.","a":"이찰·이율 형제 정려","c":"시도기념물","nc":"","r":"인천광역시","s":"계양구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2017021714130300.jpg"},{"q":"조선 때 문신인 남창년(1463∼?)의 무덤 근처에 제사를 지내기 위해 세운 건물이다. 기와에 남아 있는 명문으로 보아 조선 순조 26년(1826)에 지었다고 한다. 그는 조선 영조 때 문과에 급제하였으나 스승인 정여창 선생이 무오사화(1498) 때 화를 당하자 ○○으로 낙향하였다. 그 뒤 문학으로 추천 받아 부령교수가 되었고 저서로 『성경도설』이 있다고 하나 지금은 전하지 않는다. 소나무가 무성하여 솔마골이라 부리는 곳에 있으며 담장이 없는 ㅁ자형 남향 건물이다.","a":"안동 영양남씨 재사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658926.jpg"},{"q":"속리산 비로봉 아래에 위치한 ○○○은 통일신라사대인 720년(성덕왕 19)창건되어 ○○○를 짓기 위한 목재를 저장하여 두던 창고로 이용되다 뒤에 암자를 바뀌었다고 전해지나 증거는 확실하지 않다. 그리고 조선 말기인 1876년(고종 13)에 인명대사(仁明大師)가 중창하였고 1897년 보봉(普峰) 스님이 중수하였다. 광복 후 1963년 법혜 스님이 법당을 중건하고 이후 극락전과 영산전, 산신각을 건립하여 오늘에 이르고 있다.","a":"보은 법주사 상고암 마애불상군","c":"문화유산자료","nc":"","r":"충청북도","s":"보은군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660862.jpg"},{"q":"절 이름이나 유래가 전해지지 않고 있으나 백제 절터로 추정된다. 남쪽으로 약간 경사진 곳에 절터를 배치했으며 주변에 금당터와 목탑터가 확인되었다. 많은 양의 백제 연꽃무늬 와당이 흩어져 있고, 장대석, 백제 기와와 토기 조각들이 출토되었다. 백제의 연꽃무늬 와당들로 보아 6세기 이전에 절이 지어진 듯 하며 가람배치는 1탑식으로 추정한다.","a":"용정리사지","c":"시도기념물","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652759.jpg"},{"q":"‘○○○○○’은 원삼국 시대 늦은 시기의 집단 무덤으로 임진강 유역에서 처음 발굴 조사된 ○○○○○이라는 점에서 의미가 있다. 이 무덤은 고구려 적석총과 다르게 분구 위의 돌층이 두텁지 않기 때문에 즙석묘, 즙석총, 즙석식적석묘 등 다양한 명칭이 사용되었지만, 최근 학계에서는 적석분구묘로 부르기도 한다. 무덤은 임진강이 남쪽으로 흐르다가 다시 북쪽으로 곡류하는 지점의 북쪽 모래 언덕 위에 위치한다. 모래 언덕은 동서 방향으로 길게 형성되어 있는데, 전체 ○○○ 모습은 타원형에 가깝다.","a":"연천삼곶리돌무지무덤","c":"시도기념물","nc":"","r":"경기도","s":"연천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646777.jpg"},{"q":"○○○ 大願庵 竈王幀은 화기에서 밝히고 있듯이 대한제국시대인 光武 7년(1903)에 ○○○ 내원암에서 조성하여 현재의 ○○○에 옮겨 봉안한 조성 및 봉안내력을 간직한 채 현 위치를 잘 지키고 있는 탱화이자 조왕을 단독으로 묘사한 조왕탱임","a":"밀양 표충사 대원암 조왕도","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666347.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다 조선 세종 22년(1440)에 처음 지어진 후 전쟁으로 여러 차례 불탄 것을 영조 31년(1755)에 원래의 위치인 이곳에 다시 짓고 그 후 여러 차례 보수했다. 건물의 배치는 앞쪽에 공부하는 곳인 명륜당과 동·서재가 있고 뒤쪽에 사당 출입문인 내삼문과 사당인 대성전이 위치하는 전학후묘의 형태이다. 그러나 특이한 것은 내삼문의 계단이 직선이 아닌 ㄴ자로 되어있고, 명륜당 뒤의 대성전도 약간 비틀어져 위치하고 있다.","a":"산청향교","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641968.jpg"},{"q":"이 관음보살좌상은 ○○○○○에 본존으로 봉안되어 있으며, 1999년에 개금(改金)을 하여 현재 보존 상태는 매우 양호한 편이다. 팔각대좌 위의 연화대좌 윗면에 있는 묵서(墨書)에 의하면 이 관음보살좌상은 1722년(康熙 61)에 조성되었고, 조각승으로는 ○○○ 비로자나삼존불의 중수와 도금을 담당한 진열(進悅)을 비롯하여 청우(淸雨), 청휘(淸徽), 관성(貫性), 옥홀(玉㧾) 등이 참여하였음을 알 수 있다. 관음보살좌상은 팔각대좌 위의 연화좌에 결가부좌한 자세로 앉아 있다.","a":"범어사 관음전 목조관음보살좌상","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636737.jpg"},{"q":"비의 성격을 정확히 알 수 없으나 비문의 일부 내용으로 보아 불교와 관계된 것으로 짐작되는 비이다. 자연석을 약간 다듬은 기둥 모양으로 앞면에만 글자를 새겼는데 많이 닳아 있어 전체적인 내용 파악은 어렵다. 비문에 의하면 비의 건립연대는 통일신라 원성왕 2년(786)이다. 전남지역에서 발견된 글을 새긴 비중에서 가장 오래된 비로, 마을에서 골목길을 정리하다 발견되어 지금은 최정호씨 집에 옮겨 놓았다.","a":"영암 정원명 석비","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"영암군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662182.jpg"},{"q":"○○○는 청동기시대의 대표적인 무덤으로 고인돌이라고도 부르며, 주로 경제력이 있거나 정치권력을 가진 지배층의 무덤으로 알려져 있다. 우리나라의 고인돌은 4개의 받침돌을 세워 돌방을 만들고 그 위에 거대하고 평평한 덮개돌을 올려 놓은 탁자식과, 땅 속에 돌방을 만들고 작은 받침돌을 세운 뒤 그 위에 덮개돌을 올린 바둑판식으로 구분된다. 전라남도 지방은 전국에서 가장 많은 고인돌이 분포하고 있는 곳으로 지금까지 2만기 이상이 알려져 있다. 30여 기에 달하는 나주 ○○○ 고인돌 무리는 영산강 남쪽 연안의 평평한 구릉지대에 솟은 봉의산 동쪽 기슭에 자리잡고 있다.","a":"나주신포리지석묘군","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654297.jpg"},{"q":"조선 헌종 5년(1839)경에 박익 선생의 제사에 사용하기 위하여 제작된 그릇들이다. 제작 당시에는 모두 32점이 제작되었으나 현재는 술잔 6개, 술통 2개, 사각형 밥그릇 4개, 원형 밥그릇 2개, 촛대 2개, 향을 담는 그릇인 향합 1개 등 18점이 남아있다. 이 그릇들은 ○○로서는 드물게 청동으로 만들었다. 매년 3월 ○○○○에서 박익 선생의 제사에 사용하고 있다.","a":"산청 신계서원 제기","c":"문화유산자료","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664149.jpg"},{"q":"회원서원이 있었다고 해서 서원곡이라 부르는 무학산 계곡 일대에 ○○○이 자리잡고 있다. 회원서원은 조선 중기 학자 한강 정구(1543∼1620)를 추모하는 뜻으로 그의 제자들이 세웠던 곳이다. 조선 고종(재위 1863∼1907) 때 흥선대원군의 서원철폐령으로 없어지고 지금은 ○○○만 남아 있다. 건물 규모는 앞면 4칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞에는 440년 묵은 은행나무가 있는데, 정구 선생이 손수 심은 것으로 전한다. ○○○에서는 해마다 음력 3월과 9월에 정구 선생과 그의 제자인 허목 선생께 제사지내고 있다.","a":"창원 관해정","c":"문화유산자료","nc":"","r":"경상남도","s":"창원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663787.jpg"},{"q":"봉한리 마을에서 난 충신, 효자, 열녀를 기리기 위해 정조 19년(1795)에 세운 것이다. 삼강은 유교적 실천윤리인 충(忠)·효(孝)·열(烈)을 말하는 것이며, 정려는 이러한 것을 잘 지킨 이들의 정신을 받들기 위해 마을 입구에 세우는 징표이다. 이곳의 충신·효자·열녀는 각각 야은 길재·배숙기·약가인데 길재(1353∼1419)는 고려말과 조선초의 학자로 1374년 벼슬길에 올랐으나 고려가 망하고 조선이 건국되자 고향으로 돌아와 학문 연구와 제자를 키우는데 전념하였다. 이색·정몽주와 함께 고려의 삼은(三隱)으로 불린다.","a":"선산 삼강정려","c":"문화유산자료","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663157.jpg"},{"q":"도와 박선(1596∼1669) 선생이 1620년경에 세운 옛 집이다. 건축 당시 박선이 99칸 규모로 세웠으나 2차례의 화재로 본래의 건물은 모두 없어지고 지금있는 건물은 훗날 다시 지은 것이라고 한다. 안채를 비롯하여 가묘, 경염정, 일성제 등의 건물이 있다. 경염정과 일성제는 1925년 주택에서 100m 떨어진 곳으로 이건하여 지금에 이르고 있다. ○○○의 토벽에는 조선시대의 명필가인 숨은 박춘수 선생의 필적이 남아있는데 달밤에 벽에다 썼다하여 월야벽서라 불린다.","a":"영덕도곡동충효당","c":"시도민속문화유산","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658778.jpg"},{"q":"○○시 장유면 ○○○ 대청천의 북쪽 평지에 위치하고있다. ○○○와 고목이 있는 부분은 별도의 석축을 쌓아 ○○○와 고목을 보호하고 있으며 아울러 부락민들의 휴게소로도 이용되고 있다. 부락에서는 이 ○○○를 광석이라 불렀다. (현황) 남방식 ○○○로 생각되나 상석하부가 메꾸어져 있어 정확한 구조는 확인할 수 없었다. 지상에는 거대한 상석만 눌려 있는데북쪽끝 부분만 약간 들려 있고 나머지 부분은 흙과 돌로서 메꾸어져 있다. 상석의 규모는 길이 6.1m, 폭 2.9m, 두께 1.1∼1.3m이며 장축은 남북향이다.","a":"김해 무계리지석묘","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655893.jpg"},{"q":"크게 두 채로 이루어진 집으로 남쪽에 위치한 집은 살림채이고 북쪽에 있는 집은 사당채이다. 살림채는 一자형 집으로 앞면 4칸·옆면 2칸이며 중앙의 대청을 중심으로 서쪽에는 안방을 동쪽에는 건넌방을 배치하였다. 안방 앞에는 부뚜막이 있고, 대청 앞은 전면이 개방된 토방이 있다. 건넌방 앞에는 골방이 있었던 듯하나 지금은 부엌으로 쓰고 있다. 사당은 살림채에 비스듬히 배치되어 있으며 앞면 4칸·옆면 1칸의 건물이다. 뒷쪽에 신주단을 두고 그 곳에 위패를 모시고 있는데 단 위에는 간소한 집 모형의 닫집이 마련되어 있다.","a":"숭보사","c":"시도민속문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658062.jpg"},{"q":"안성시 일죽면과 이천시 그리고 충청북도 음성군의 경계지점에 있는 해발 472m 높이의 망이산에 있다. 이곳은 경기도 남동부와 충청도 북부지역을 연결하는 교통로상의 요충지다. 백제 성곽은 산 정상부를 둘러싸고 있는 토성이며, 둘레는 250m 정도다. 성벽은 영정주를 사용하여 판축공법으로 구축된 것으로 확인되었다. 성내에서는 다량의 토기류와 철제무기류가 출토되었다. 한성백제 시기인 4세기부터 5세기 대에 운영된 것으로 보인다. 통일신라 성벽은 백제토성을 감싸며 능선을 따라 구축된 포곡식 산성이다. 전체 둘레는 2,080m로 대규모에 속하는 산성이며, 장방형이다.","a":"망이산성","c":"시도기념물","nc":"","r":"경기도","s":"안성시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646725.jpg"},{"q":"부여 ○○○○○은 극락전 전면의 동편에 있는 건물로서 지장보살을 모시고 명부의 시왕상(十王像)을 모셨으며 일명 지장전(地藏殿)이라고도 부른다. 건물기단은 자연석을 이용한 낮은 기단에 기둥은 원주를 사용하였으며 좌우 측면 중앙기둥과 후면 평주는 방형 단면이다. 정면 3칸·측면 2칸 규모로, 지붕은 맞배지붕이며 전면 3칸에는 2짝씩의 세 창살문을 달았고 후면은 판장벽으로 처리하고 양측면에 방풍판을 달았다. 1872년 원열화상에 의해 건립되었다고 전하며 건물의 보존 상태는 양호하다.","a":"부여무량사명부전","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661568.jpg"},{"q":"○○○ 마을 안에 자리하고 있는 탑으로, 널찍하게 마련한 돌단 위에 놓여 있다. 몇년 전까지 주변에서 기와조각이 발견되었고, 인근 민가 앞에서 작은 석불(石佛)이 발견되어 이곳이 절터였음을 말해주고 있다. 대체로 파손이 심하지 않은 이 탑은 기단(基壇)을 1층으로 쌓고, 그 위로 5층의 탑신(塔身)을 올린 모습이다. 기단은 윗돌을 괴어두는 부분에 2단의 높직한 괴임을 두었다. 탑신의 각 지붕돌은 밑면에 4단씩의 받침을 새겼으며, 직선을 그리던 처마는 양쪽 끝에서 느리게 위로 들려있다. 꼭대기에는 네모난 받침돌 위로 높직한 머리장식을 얹어 마무리하였다.","a":"남문리오층석탑","c":"문화유산자료","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661246.jpg"},{"q":"이 불상은 땅 위에 있는 화강암의 바위에 받침대를 조각하고 그 위에 불상을 세운 형태이다. 받침대는 2단으로 되어 있는데, 아랫단은 네모난 형태이며 각면에 안상을 새겨 놓았고, 윗단은 둥근 형태로 연꽃무늬를 조각해 놓았다. 이 석불입상의 규모는 전체높이 233㎝, 어깨폭 75㎝, 머리높이 53㎝이다. 서 있는 모습의 이 불상은 머리부분이 몸에 비해 다소 크게 조각되어 있다. 머리에는 굵고 둥근 육계가 솟아있고, 머리모양은 별 장식이 없는 민머리 형태이나 얼굴과의 경계는 뚜렷하게 구분지었다.","a":"불굴사석조입불상","c":"문화유산자료","nc":"","r":"경상북도","s":"경산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663291.jpg"},{"q":"조선 중기 문신이자 임진왜란 때 의병장으로 활약했던 조헌(1544∼1592) 선생의 위패를 모시고 있는 사당이다. 조헌은 선조 25년(1592) 임진왜란이 일어나자 ○○에서 김경백 등과 의병 1,600여명을 모집하고 승병인 영규대사와 함께 청주성을 수복하는데 공을 세웠다. 그러나 충청도 순찰사인 윤극형의 방해로 의병이 강제 해산되어 700여명으로 금산전투에 참전했으나 모두 전사하였다. 건물 규모는 앞면 3칸·옆면 1칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양과 비슷한 팔작지붕이다.","a":"옥천 후율당","c":"시도기념물","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649240.jpg"},{"q":"○○○는 칠성을 불교의 불법을 수호하는 신으로 수용하고 이를 의인화하여 묘사한 불화이다. 원래 불교에서는 칠성신을 신중(神衆)의 하나로 보고 신중탱화 속에서만 묘사하였으나, 칠성에 대한 신앙적 기능이 강화되면서 별도의 칠성탱화가 등장하면서 독립적인 신앙 형태를 지니게 되었다. 칠성탱화가 널리 봉안된 것은 칠성의 주불(主佛)인 치성광여래가 약사여래와 같은 역할을 담당하였기 때문이다. 자식이 없는 부인이나 아들을 낳고 싶어하는 부인, 자식의 수명을 비는 신도들에게서 큰 인기를 모았다.","a":"수원 청련암 칠성도","c":"문화유산자료","nc":"","r":"경기도","s":"수원시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660288.jpg"},{"q":"조선시대의 문조선시대의 문신인 ○○○ 선생의 ○○○로, 성종 2년(1471) 좌리공신 3등을 받고 연원군에 봉해졌을 때에 이를 기념하기 위하여 왕명에 의해 제작된 공신도로 보인다. 약간 오른쪽을 바라보고 있는 전신좌상으로, 가로 100㎝, 세로 200㎝의 크기이다. 머리에 쓴 사모가 양 옆으로 길게 수평을 이루고 있는 형태와 관복의 바탕 색이 연붉은 점, 얼굴의 표현과 옷주름의 처리, 발 받침대의 모양에서 조선 전기의 ○○○ 기법이 엿보인다. 우리나라 ○○○의 대부분이 두 손을 옷소매 안에 넣은 공수자세인데 비해 이 상에서는 손이 밖으로 나와 있다.","a":"이숭원초상화","c":"시도유형문화유산","nc":"","r":"경상북도","s":"김천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640364.jpg"},{"q":"이 절터는 공주 웅진동 우뚝 솟은 망월산의 동쪽에 자리잡고 있다. 이곳에서 발견된 ‘○○○’라 적힌 기와와 백제의 전형적인 연꽃무늬 와당과 통일신라와 고려시대의 각종 기와류, 석탑부재, 초석 들로 보아 백제 때 지은 사찰로 추정된다. ○○○터는 완만하게 경사진 밭을 3단계로 구분하여, 석축을 쌓고 지었던 것으로 보인다. 조사된 내용에 의하면 불도를 닦던 곳의 배치가 지형과는 관계없이 남쪽을 향해 탑, 불당과 함께 직선상에 놓았음을 알 수 있다.","a":"공주서혈사지","c":"시도기념물","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652709.jpg"},{"q":"○○○는 백제 성왕 때 창건하였다고 전하나, 통일신라 후기의 승려인 도선국사와 관련된 전설이 전해지고, 이곳에서 발견된 유물들을 볼 때에 통일신라 후기에 창건된 사찰로 보인다. 전설에 의하면 절이 세워지기 전에 근방에 있는 용담천에서 이무기가 나타나 사람들을 괴롭혔는데, 도선국사가 이 절을 세운 뒤 부터는 행패를 부리지 않았다고 한다. 조선 전기의 숭유억불정책으로 절은 사라지고, 현재는 이 탑과 함께 석불입상(보물)과 석등이 남아 있다.","a":"용담사칠층석탑","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"남원시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639375.jpg"},{"q":"향교는 훌륭한 유학자를 제사하고 지방민의 유학교육과 교화를 위하여 나라에서 지은 교육기관이다. 태조 7년(1398)에 세워진 ○○○○는 임진왜란(1592) 때 불에 탄 것을 인조 8년(1630)에 수리하였다. 그 후에도 여러 차례 고쳤다. 현재 남아 있는 건물은 대성전·명륜당·동재·서재·제기고 등이 있다. 경사지에 위치한 ○○○○는 내삼문을 경계로 배움의 공간과 제사공간을 구분하고 있다. 앞쪽에는 외삼문·명륜당·동재·서재가 있고, 뒤쪽에는 대성전과 전사청이 있어 전학후묘의 배치를 이루고 있다.","a":"장흥향교","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639954.jpg"},{"q":"요지는 자기나 기와, 그릇들을 만들어 굽던 가마터를 말한다. ○○○ 사기마을과 마을 뒷산에 4개의 가마터가 있는데, 이중 1개는 통일신라시대의 것이며, 나머지 3개는 분청사기와 백자를 굽던 조선시대의 것이다. 임진왜란 때 일본인들이 이곳의 가마를 파괴하고 도공들을 납치해 갔다고 전해진다. 이곳에서 출토되는 그릇의 종류는 대접, 접시, 사발, 병, 항아리, 장군, 잔 등 다양하며, 주로 생활용 그릇들을 굽던 곳으로 보인다. 도자기를 만드는 바탕흙인 태토는 회색인데 모래 같은 불순물들이 많이 섞여 있으며, 거칠고 어두운 회청색을 띤 유약을 두껍게 칠하였다.","a":"하동 백련리 도요지","c":"시도기념물","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654816.jpg"},{"q":"신안 ○○○○○ 일원에는 ○○○○을 비롯한 제사유적, 관사터, 무심사지 등 4개 유적으로 이루어진 복합유적이 있다. ○○○○은 고대~고려시대 국제 해양도시의 기능을 수행했을 것으로 추정되는 ○○○ 읍동마을을 수호하기 위해 축조한 관방시설로 추정된다. 읍동마을 뒤편의 계곡 초입부에는 고려시대 중국 사신들이 머물던 관사터가 위치하고 있다. 이 관사의 맞은편 골짜기에는 무심사지(无心寺址)가 들어서 있고, 바로 위쪽의 봉우리에 ○○○○이 자리잡고 있다. ○○○○ 서쪽의 ○○○ 정상에는 봉화 불을 피우던 봉수대와 제사유적이 위치하고 있다.","a":"신안흑산도상라산성","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654392.jpg"},{"q":"○○○는 경상북도 의성군 비안면 산제1리 화장산 중턱에 위치한 사찰로 1999년 1월 현 주지인 대관(大觀)스님이 불사를 일으키면서, 암자 뒤쪽에 묻혀있는 불상을 발견하고 이를 파내면서 ○○○○○과 대좌, 광배 등을 발견하게 되었다. 사찰은 약 30년전까지 '화장사(花長寺)'로 불려졌지만 대관스님이 중창하면서 사명을 새롭게 '○○○'로 고쳐 부르고 있다. 현재 석등부재와 3층석탑재가 유존하고 있으며, 건물들에 사용된 각종 석재 등이 모아져 있다.","a":"만장사석조여래좌상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"의성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641057.jpg"},{"q":"○○○는 석가모니(釋迦牟尼)의 일대기를 8개 장면으로 압축하여 묘사한 그림을 말하는데 도솔천에서 내려오는 상[도솔래의상兜率來儀相]․ 비람동산에서 내려오는 상[비람강생상毘藍降生相]․ 4문에 나가 관찰하는 상[사문유관상四門遊觀相]․ 성을 넘어 출가 하는 상[유성출가상踰城出家相]․ 설산에서 수도하는 상[설산수도상雪山修道相]․ 보리수 아래서 마귀에게 항복받은 상[수하항마상樹下降魔相]․ 녹야원에서 처음으로 포교하는 상[녹원전법상鹿苑轉法相]․ 사라쌍수 아래서 열반하는 상[쌍림 열반상雙林 涅槃相] 등 총 8폭으로 구성되어 있다.","a":"안양암 팔상도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2590615.jpg"},{"q":"○○○의 출입통로로 이용되고 있는 ○○○는 성의 남문에 해당되며, 조선시대에는 삼남의 관문이었다. 원래 토성(土城)이었던 것을 석축성(石築城)으로 고쳐 세운 것은 조선 전기의 일이다. ○○○도 그 때 세운 것으로 알려졌는데, 그 뒤에도 여러 차례 고친 것으로 보인다. 지금 있는 건물은 1971년에 전부 해체하여 원래대로 복원한 것이다. 앞면 3칸·옆면 2칸 규모로, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 장식한 익공 양식으로 꾸몄다.","a":"공산성진남루","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660942.jpg"},{"q":"전북 부안군에 있는 월명암을 창건하였다는 부설거사에 관한 이야기를 한문으로 기록한 것이나, 누구에 의해서 기록된 것인지 알 수 없다. 내용을 보면 부설거사가 태어나서 죽을때까지의 행정과 그가 쓴 4부시(賦詩), 그리고 8죽송(竹頌)으로 되어 있는데 4부시와 8죽송의 글씨체가 서로 다르다. 한지 7장을 1면으로하여 총 15면으로 되어 있으며, 1면은 10행이고 매행은 14자이다. 총 2,616자이다.","a":"부설전","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"부안군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639603.jpg"},{"q":"장명등은 무덤 앞에 세워두는 석등으로, 이 석등은 이계맹(1458∼1523) 선생의 묘 앞에 놓여 있다. 이계맹 선생은 조선 성종 20년(1489) 문과에 급제하여 예조·호조·형조 등의 판서를 거쳐 좌찬성에 이르렀다. 석등의 형태는 한돌로 이루어진 받침 위에 등불을 밝혀두는 화사석(火舍石), 지붕돌을 얹고 꼭대기에는 머리장식을 갖추었다. 받침은 기둥의 중간을 잘록하게 하여 세 부분처럼 보이도록 구분하였는데, 아래에는 모서리마다 연꽃무늬를 새겼고, 굵직한 4각을 이룬 가운데에는 아무런 조각을 두지 않았으며, 위에는 모서리와 각 면에 연꽃과 구름무늬를 두었다.","a":"재궁리석등","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639479.jpg"},{"q":"○○○○ 석조○○○○은 조선시대 이래 유행한 약기인의 약사불상의 도상을 정확하게 보여주고 있으며, 통일신라시대부터 조선시대까지 시대의 복합상을 갖춘 불상이라는 점에서 자료적 가치가 인정됨","a":"선운정사 석조약사여래좌상","c":"문화유산자료","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2018071014155300.jpg"},{"q":"지정 대사본인 문수사판은 한국 선종사에 있어서 사상적 이념을 제공한 불교문헌으로 평가되고 있고, 국내에서 ○○○에만 유일하게 소장되어 있는 매우 희귀한 선종문헌의 일종이다.","a":"고양 원각사 달마대사관심론","c":"시도유형문화유산","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637812.jpg"},{"q":"○○○에 있는 신중탱화로서, 인도의 재래적인 토속들을 그림으로 나타낸 불교 그림이다. 신중을 그린 불교 그림이다. 신중은 불교의 토착화 과정에서 수용된 불법 수호의 선신(善神)들로, 이처럼 별도로 그림을 그려 신앙의 대상으로 삼기도 하였다. 신중탱화는 주로 전각의 주불을 모신 불단의 왼쪽(向右)에 걸어 놓는다. ○○○는 신라 진흥왕 9년(548)에 연기조사가 평원사라 이름하여 세웠다고 전한다. 그 뒤 여러번의 보수를 하고 이름도 ○○○로 고쳤다. 한국전쟁과 여순사건으로 인해 화재를 입어 다시 세운 뒤 오늘에 이르고 있다.","a":"산청 대원사 신중도","c":"시도유형문화유산","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642332.jpg"},{"q":"이 목판은 조선 후기의 대유학자 우암 송시열(1607∼1689) 의 문집과 연보 등을 모아 만든 『송자대전』의 목판으로 총 11,023판이다. 송시열은 김장생의 문하생으로 힘있고 논리적인 문장과 서체에 뛰어났고 평생 주자학연구에 몰두하여 율곡 이이의 학통을 잇는 기호학파의 주류이었다. 여러 관직을 거쳐 좌의정까지 오르지만 낙향과 유배, 재기용과 은거를 거듭하며 결국은 남인들에 의해 사약을 받고 목숨을 잃었다.","a":"송자대전판","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"동구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2023030815200000.JPG"},{"q":"고려말 조선초의 문신이며 학자였던 양촌(陽村) ○○과 선생의 아들 권제, 손자 권람의 3대묘이다. 선생은 공민왕 17년(1368) 성균시에 합격한 후 여러 관직을 역임하였으며, 공민왕(재위 1352∼1374)이 죽자 정몽주·정도전과 함께 배원친명(排元親明)을 주장하였고 창왕 2년(1389)에는 명나라에 사신으로 다녀왔다. 태조 7년(1398) 제1차 왕자의 난이 일어난 후에 사형제도를 폐지할 것을 주장하여 왕권확립에 큰 공을 세웠다. 그 후 대제학을 거쳐 재상의 자리에 올랐으며, 문장이 뛰어나『동국사략』등 조정의 각종 편찬 사업에 참여하였다.","a":"음성 권근 삼대 묘소 및 신도비","c":"시도기념물","nc":"","r":"충청북도","s":"음성군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649598.jpg"},{"q":"○○○○○은 세종대왕의 여섯 째 아들인 ○○○○ 이유(錦城大君 李瑜, 1426〜1457)의 ○○이다. ○○○○ 이유는 세종대왕과 소헌왕후 심씨昭憲王后 沈氏 사이에서 여섯째 아들로 태어났다. 천성이 강직했으며 문장가로도 명성이 높았다고 한다. 성삼문成三問 등 사육신死六臣과 함께 단종 복위 운동에 연루되어, 경상북도 영주시 순흥으로 귀양을 갔다. 그곳에서 순흥부사順興府使 이보흠李甫欽과 함께 단종의 복위를 모의하다 한 관노의 밀고로 체포되었고, 1457년 10월 사사賜死되었다.","a":"청주 금성대군 제단","c":"문화유산자료","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660806.jpg"},{"q":"○○○에 딸린 암자인 ○○○ 영산전 앞에 서 있는 탑으로, 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올리고 있다. 위층 기단의 네 면과 탑신의 몸돌에는 기둥 모양을 조각하였다. 지붕돌은 네 귀퉁이가 살짝 치켜올라갔고, 밑면에 계단모양의 받침을 새겨 두었다. 꼭대기의 머리장식은 모두 사라져 버린 상태이다. 삼국시대의 것으로 추정된다.","a":"은해사거조암삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662568.jpg"},{"q":"수덕사에 있는 거문고로 만공스님께서 고종의 둘째 아들인 의친왕 이강에게 받은 것이다. 이조묵(李祖默)이 새긴 공민왕금(恭愍王琴) 이라는 글씨와 함께 만공 스님의 시가 새겨 있다.","a":"수덕사유물(거문고)","c":"문화유산자료","nc":"","r":"충청남도","s":"예산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661217.jpg"},{"q":"<식산 ○○○ 전적>은 조선 후기 학자 식산 ○○○의 시문집으로 1798년(정조22) 그의 후손 및 향중(鄕中)의 지사(志士)들이 각각 출자하고 편집에 착수하여, 15년 후인 1813년(순조 13)에 정종로(鄭宗魯, 1738~1816, 우복 정경세 선생의 6대손)등에 의하여 교정을 거친 뒤 간행되었다. 국가유산으로 지정된 전적은 모두 13종 38책이다. 현재 규장각 소장본은 모두 19책으로 속집 1책이 없어진 상태이며, 속집(9~10)은 뒤에 필사본으로 보충한 것이다. 서문은 없고 속집 끝에 ○○○의 증손 이경유(李敬儒)의 후지(後識)를 붙였다.","a":"식산이만부전적","c":"시도유형문화유산","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640903.jpg"},{"q":"○○○○○는 김해시 동상동 구 김해읍성 내의 포교당 경내에 위치하고 있다. 포교당 경내에는 駕洛古都宮墟碑와 분성대 및 연자루의 주춧돌로 추정되는 석물과 함허교의 교명주로 추정되는 석재 2기, 함허교의 판석으로 추정되는 석판 6기, 석불상 2기가 남아있다. 분성대와 함허정이 있었다고 전해지는 이 터는 가락국 후기의 왕궁터 혹은 수로왕비의 중궁터로도 전해지며 이후 우리나라 최초의 석탑인 파사석탑을 보관한 호계사와 조선시대에 들어서는 연자루와 함허정이 세워진 역사성을 가진 장소로 전해진다.","a":"김해객사후원지","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657499.jpg"},{"q":"구계 서침의 덕을 기리기 위해 위패를 모시고 제사지내는 서원이다. 서침은 고려말∼조선초의 변혁기에 향촌에 은거하며 학문 연구에 노력하였다. ○○○○은 현종 6년(1665) 세웠고, 고종 5년(1868) 대원군의 서원 철폐령으로 철거되었다가 그 후 1924년 유림이 다시 지었다. 신명여고 운동장 오른쪽 언덕 아래에 북동쪽으로 배치되어 있는데, 경앙문을 들어서면 오른쪽에 유허비각이 있고 맞은편에 강당이 있다. ○○○는 강당 바로 뒤에 3m쯤 떨어져 있다. 건물은 앞면 3칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다.","a":"구암서원숭현사","c":"문화유산자료","nc":"","r":"대구광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659448.jpg"},{"q":"임진왜란 당시 나라를 위해 싸우다 전사한 제말장군과 그의 조카인 제홍록의 충의를 기리기 위해 세운 비이다. 제말(?∼1592)은 임진왜란이 일어나자 의병을 모아 웅천 ·김해 ·의령 등지에서 왜적과 싸워 공을 세웠고, 성주싸움에서 전사하였다. 제홍록은 숙부와 더불어 전공을 세웠으며, 이순신 휘하에 있다가 정유재란 때 전사하였다. 비의 형태는 거북받침돌 위에 비몸을 올리고 머릿돌을 얹은 모습이다. 거북받침은 등부분에 아무런 조각이 없으며, 튀어나온 눈을 강조하여 토속적인 느낌이 든다.","a":"진주 쌍충 사적비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641331.jpg"},{"q":"머리는 나발이며 육계는 표현되지 않았다. 얼굴에 비해 코는 크고 입은 작으며 눈은 반개한 모습이다. 양귀는 짧고 어깨는 다소 약간 위로 치켜진 모습이며 삼도가 표현되었다. 법의는 우견편단이며 수인은 항마인을 결하고 있다. 대좌는 8각의 하대석과 중대석만 남아 있으며 불상 근처에 광배가 놓여 있다.","a":"충주 문주리 석조여래좌상","c":"문화유산자료","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660801.jpg"},{"q":"이 가옥은 1938년에 건립한 가옥으로 예산1리 마을회관 맞은편에 자리 잡고 있다. 가옥의 건립자인 도문환은 ○○ 지역의 선각적인 유림으로 계몽운동에 앞장 선 만산(晩山) 도갑모(都甲模)의 아들로서, 그 자신 1920년대 ○○지역의 청년운동과 신간회운동 등 여러 사회운동에 적극적으로 활동하는 등 지역에 지대한 영향을 끼쳤던 인물이다. 가옥의 배치는 서향(西向)한 대문채를 들어서면 바로 사랑채의 좌측면이 나타는데 사랑채 뒤에는 안마당을 사이에 두고 ㄱ자형의 안채를 배치하여 전체적으로는 튼 ㅁ자형의 배치 형태를 취하고 있다.","a":"성주 예산리 만산댁","c":"시도유형문화유산","nc":"","r":"경상북도","s":"성주군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641163.jpg"},{"q":"좁다란 골짜기의 절벽 위 널찍한 터에 자리하고 있는 ○○으로, 흙으로 구워 만든 벽돌로 쌓아 올렸다. 땅 위로 5단의 바닥돌을 놓고 1층의 기단(基壇)을 마련한 뒤 5층의 탑신(塔身)을 올려놓았는데, 오랫동안 무너진 채 방치되었다가 1968년에 다시 세워 놓은 것이어서 원래의 형태인지는 알 수 없다. 이 탑의 특징은 무늬가 있는 벽돌을 사용한 점으로, 불상과 3층 석탑 무늬가 있는 벽돌로 쌓아 올려 탑 전체를 장식하고 있다.","a":"청도 불령사 전탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"청도군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641299.jpg"},{"q":"낮은 언덕 위에 자리한 성당으로, 벽돌과 목재를 이용한 우리나라에서는 보기드문 건축 양식을 보여준다. 정면의 종탑이 쌍탑으로 되어있는 것이 특징인 이 성당은 3개의 출입구와 창들이 모두 무지개 모양을 이루고 있다. 외벽은 붉은 벽돌로, 창둘레와 종탑의 각 모서리는 회색벽돌로 쌓았다. 창 아래와 종탑의 각각 면에는 회색벽돌로 마름모형의 장식을 하였다. 1929년에 새로 지은 건물로, 100여 년 이상의 역사를 간직하고 있으며, 교회가 박해를 받을 때에는 순교의 장소가 되기도 한 한국 천주교회의 발상지적 역할을 담당하였던 곳이다.","a":"당진합덕성당","c":"시도기념물","nc":"","r":"충청남도","s":"당진시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653044.jpg"},{"q":"조선 선조 때의 유명한 장군인 체암(遞菴) ○○○의 생가와 묘소가 있는 곳이다. 선조 16년(1583) 무과에 합격한 후 군함 연구에 관심을 갖고 10여년간 거북선을 연구 제작 실험하였다. 임진왜란이 일어나기 1년 전인 선조 24년(1591) 이순신 장군을 찾아가 거북선 제작을 협의하고 3척을 처음 진수하였다. 임진왜란이 일어나자 옥포해전, 명량해전, 노량해전 등에서 커다란 공을 세웠으며, 임진왜란 후에는 새로운 전함인 창선과 쾌속정인 해추선을 발명하였다.","a":"나대용생가및묘소","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654031.jpg"},{"q":"충청북도 ○○군 ○○○에 있는 전체 높이 7.5m의 불상으로, 큰 바위 한면을 다듬어 몸 전체를 감싸는 듯한 커다란 광배(光背)를 만들고 그 안에 불상을 새겼다. 앞면에 뚫려 있는 구멍으로 보아 원래는 불상을 모시던 나무로 만든 방이 있었을 것으로 보인다. 얼굴은 단아한 스님의 모습을 하고 있으며, 목에는 3줄로 새긴 삼도(三道)가 뚜렷하다. 양 어깨를 감싸고 입은 옷은 U자형으로 흘러내리고 있으며, 왼팔 등에도 촘촘하게 주름이 새겨져 있다. 특징적인 광배와 함께 도식적인 옷주름 표현 등에서 형식화가 진행되는 고려시대 불상의 모습이 잘 나타나 있다.","a":"진천 사곡리 마애여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"진천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638586.jpg"},{"q":"○○○○○은 정면 3칸의 익공계 팔작집으로 사역내의 여러 전각 가운데에서도 비교적 이른 시기에 건립된 조선후기 건물로 건립 연대에 관한 자료가 확인되고 가구는 보조가구재를 채용하여 구조적 안정성을 증대시켰고, 공포는 출목익공의 중요한 사례로써 사내 다른 전각의 것과 함께 건축학적으로 충분한 연구가치가 있으며 보존상태도 양호하다.","a":"순천 선암사 불조전","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640217.jpg"},{"q":"강원특별자치도 철원군 ○○○ 해발 350m의 금학산 동쪽자락 중턱의 거대한 바위면을 다듬어 조각한 ○○○입상이다. 동남향을 하고 있는 불상은 전체 높이 576㎝, 불신 높이 450㎝, 머리 높이 134㎝이다. 몸 부분은 바위면에 직접 새기고 머리 부분은 다른 돌로 만들어 몸통에 꽂아 결합시켰다. 평면적인 불신에 비하여 머리는 입체적인 형태로, 삼도(三道)가 뚜렷한 원통형의 굵고 길다란 목이 함께 붙어 있다. 민머리 위에는 상투 모양의 높직한 머리묶음이 표현되었으며, 얼굴은 긴 네모꼴의 타원형으로 원만한 인상을 하고 있다.","a":"동송읍마애불상","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660381.jpg"},{"q":"선소마을 선착장의 오른쪽 해변에 자리하고 있는 비로, 중국 명나라 장수인 ○○○이 동쪽을 정벌하고 바위에 글을 새겼다 하여 ‘○○○○○’라 이름붙인 것이다. 비의 형태는 커다란 자연석의 윗면을 직사각형으로 평평하게 갈아 글을 새겼다. 직사각형의 테 주변에는 덩굴무늬를 아름답고 정교하게 조각하였다. 비문은 이여송과 진린이 원군으로 조선의 ○○에 와서 왜군을 무찔렀다는 내용으로, 명나라 군인의 우월성을 나타내는 전승기념비적 성격을 띠고 있다.","a":"남해 장량상 동정마애비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641381.jpg"},{"q":"북일면 소재지에서 ○○○로 가는 도로를 따라 해안가에 도달한 다음 해안가에서 북동쪽으로 방조제를 따라 조금만 가면 외도가 나온다. 외도는 그리 높지 않은 섬으로 섬의 정상부가 동쪽에 치우쳐 있어 외해쪽에 연한 동쪽은 급경사를 이루고 있고 내해쪽인 남서쪽은 완경사를 이루고 있는데 고분은 정상부의 경관이 가장 좋은 지점에 나란히 자리잡고 있다. 바다쪽에 연한 섬의 정상부(해발 22.5m)에 북서―남동방향으로 분포되어 있다. 바다쪽에 가까운 동쪽은 섬이 무너지면서 분구의 일부도 유실되었다.","a":"해남내동리밭섬고분군","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"해남군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019052109553900.JPG"},{"q":"규모나 화격면에서 조선시대 ○○화의 격조를 고루 갖춘 작품이다. 세부 표현에 이르기까지 허술하지 않는 깔끔한 품격의 이 작품은 보존상태가 양호하나 현재 보관장소가 협소하여 무리하게 걸려 있어 보관상태가 다소 불량하다. 허적(許積)의 영정은 의자에 앉아 옆면을 바라보고 있는 모습으로 의자에 앉아 호랑이를 밟고 있는 모습이다. 영정의 크기는 아버지인 허한의 영정은 길이 147㎝, 폭 63㎝이고, 허적의 영정은 길이 162㎝, 폭 83.5㎝(표구상태 236×97㎝)이다. 허적의 영정은 아버지인 허한의 영정 좌측에 봉안되어 있으나 다소 퇴락하였다.","a":"허한・허적 초상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"충주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638721.jpg"},{"q":"진주 류씨 안간공파 18대손인 희택과 그 아들 전, 손자 경종의 무덤에서 출토된 일괄 유물이다. 1959년 후손이 안양에서 은산면 가곡리로 이장할 당시 나온 것을 후손이 보관하고 있다가, 1985년 3월에 부여박물관에 위탁 보관하게 되었다. 부장된 유물에는 더 많은 것이 있었을 것이나 남은 것은 명기 3벌 88점, 관복 1벌, 도포 2벌, 골제 빗 1점, 백자제기 13점만 남아 있다.","a":"유경종묘내의유물","c":"문화유산자료","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661093.jpg"},{"q":"배를 타고 들어오는 외적의 침입을 막기 위해 제주도에서는 해안선을 따라가며 성을 쌓았는데 이를 ○○○○이라 한다. 현재 성벽이 남아있는 곳으로는 온평리, 행원리, 한동리, 동복리, 북촌리, 애월리, 고내리 등 14곳이 있다. 김상헌이 지은 『남사록』에는 ○○○○을 일러 ‘탐라의 만리장성’이라 부르고 있다. 별도 ○○○○은 화북동 ○○○○ 1지점에서 동남쪽으로 약 40m 떨어진 곳에 자리잡고 있다. 안벽과 바깥벽을 갖춘 2중성으로, 주변의 크고 작은 돌을 이용하여 벽을 쌓았다. 현재 남아있는 성벽의 길이는 약 640m 정도이다.","a":"별도환해장성","c":"시도기념물","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657906.jpg"},{"q":"이 영정은 ○○○○○의 좌안8분면 바닥가부좌상으로, 왼손엔 주장자를 곧게 들고 있으며 오른손은 염주를 쥐고 앉아 있다. 인물의 뒤편은 상단벽면과 하단돗자리가 그려진 이단구도를 배경으로 하여 도식화된 등받이를 묘사하였다. 화면 향좌측에 ‘○○○대선사○○○○’의 화제가 있다. 화면 크기는 가로 82.1cm, 세로 122.0cm이다.","a":"용허당 지묵 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643037.JPG"},{"q":"여술마을 뒷산 단두리재의 남사면 중턱에 자리하고 있는 백제 후기의 무덤들이다. 발굴조사에 의하면 1기의 앞트기식돌방무덤(횡구식석실분)과 12기의 굴식돌방무덤(횡혈식석실분)이 있는데, 널길(연도)이 달린 굴식(횡혈식) 중에는 긴 벽을 안으로 쌓은 것도 있고, 판석을 이용하여 귀접이하여 짠 형식도 있다. 돌방(석실)의 벽면과 천장, 널길의 틈새는 회같은 물질로 메운 흔적이 있다. 유물은 거의 도굴되어 그 수가 적은데 수습된 유물로는 목짧은 항아리(단경호), 굽다리접시(고배), 심발형토기, 네귀단지, 금귀고리, 은으로 된 꽃모양의 모자장식(은제화형관식) 등이 있다.","a":"논산육곡리고분군","c":"시도기념물","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652846.jpg"},{"q":"이 건물은 정확한 축조연대는 알 수 없으나, 흥학당(興學堂) 번택명록(飜宅名錄)과 단양이씨(丹陽李氏) 춘천부사공파보(春川府使公派譜)의 기록을 토대로 하고 마을 주민의 증언에 의하면 1800년대 말에 지어진 것으로 추정된다. 전면 4칸, 측면 2칸의 팔작 기와집으로 기와 제작 수법과 기술이 뛰어나고, 툇마루 청판은 고식기법(古式技法)으로 조선시대의 치목기법(治木技法)이 나타나 있고 보존상태가 양호하다.","a":"영동 고당리 서당","c":"문화유산자료","nc":"","r":"충청북도","s":"영동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660790.jpg"},{"q":"낙산사 법당인 원통보전의 둘레를 사각으로 에워싸고 있는 담장이다. 조선 세조(재위 1455∼1468)가 낙산사를 고쳐 지을 때, 처음 이 담장을 지었는데 대부분 터만 남아 있어 최근에 연결·보수하였다. 안쪽의 담벽을 기와로 쌓고, 바깥쪽은 막돌로 쌓은 이 담벽은 높이 3.7m·길이 220m이다. 암키와와 흙을 차례로 다져 쌓으면서 위·아래로 줄을 맞추고, 일정한 간격으로 둥근 화강석을 배치하여 단조로운 벽면을 아름답게 장식하였다. 법당을 향하고 있는 담장 안쪽에는 밑부분에 2층의 길게 다듬은 돌기단을 깔고, 그 위에 다시 한층의 긴 받침돌을 놓았다.","a":"낙산사담장","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"양양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637940.jpg"},{"q":"○○○은 고려 충렬왕 3년(1277) 도일선사가 세운 암자로 조선 광해군 2년(1619) 혜식선사가 고쳐 지으면서 ○○○이라 하였다. 효종 4년(1655)에는 혜일선사가 지금의 자리에 욱장사를 지었으나 구한말 왜병의 침입으로 대부분이 불에 타서 없어지고, 1948년 대홍수로 ○○○이 파괴되었다. 1949년에 남아 있는 요사채의 일부를 지금 있는 자리에 옮겨 ○○○이라 부르고 있다. ○○○○○의 안쪽에는 목조여래좌상(충청북도 유형문화유산)을 모시고 있다.","a":"괴산 채운암 대웅전","c":"문화유산자료","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660772.jpg"},{"q":"화성 하동정씨 집성촌에 위치한 가옥으로, 19세기 말에 건립된 것으로 추정되고 있다. 본래 많은 부속건물을 갖춘 큰 규모의 살림집이었으나, 현재는 안채와 사랑채, 문간채만 남아있다. 가옥은 ‘ㄱ’자형 안채와 ‘ㄴ’자형 사랑채가 마주하여 장방형의 안마당을 형성하고 있으며, 안채의 왼쪽으로 행랑마당을 두고 ‘一’자형 행랑채가 위치하고 있다. 사랑채의 정면은 대문이 있는 담장으로 둘러싸서 사랑마당을 형성하였다. 사랑채를 두른 담장은 자연석으로 쌓았지만 안채와 문간채 주변 담장은 한 칸 단위로 기둥을 세우고 상부구조를 만들어 지붕을 올린 것으로 매우 보기 드문 형태이다.","a":"정원채고가","c":"시도민속문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658171.jpg"},{"q":"남성노(1829∼1878) 선생의 덕을 기리기 위해 고향의 유림들과 가문에서 세운 사당으로 선생의 호를 따서 ‘○○○’이라 불렀다. 남성노 선생은 조선 고종 3년(1866) 병인양요 때 군대에서 식량으로 쓸 쌀을 지원했다. 고향에서 가난하고 굶주린 많은 백성들을 도와주었고 노년에는 성리학을 가르쳐 후진을 길러냈다. 건물은 앞면 4칸·옆면 1칸 반 규모이며, 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 지붕 처마를 받치기 위해 장식하여 만든 공포는 새 날개 모양으로 장식한 익공 양식으로 꾸몄다. 가운데 2칸에 대청을 두고 양측 2칸에 온돌방을 두었다.","a":"낙금당","c":"문화유산자료","nc":"","r":"경상북도","s":"청송군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662998.jpg"},{"q":"석정 ○○○ 선생의 글과 그림들이다. 석정 선생은 일찍이 몸소 익혔던 성리학을 토대로 서구의 학문을 섭렵하게 되었는데, 독일의 칸트 철학을 한국 최초로 도입하여 주자학과 비교 분석해 놓은 저서를 남기기도 하였다. 또한 중국의 의약·성력(星曆)·지리·술수학·서법·묵화 등을 두루 섭렵하였고, 귀국한 후에는 그동안 익혔던 학문을 체계화한『연석산방미정문고』등 30여 권을 남겼다. 선생의 저서로는『연석산방미정문고』11책 외에『연석산방미정시초』,『상서대전』,『만사록』,『시전일과』등이 있다.","a":"석정이정직유저유묵","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639616.jpg"},{"q":"‘○○○’은 조선 전기 문신인 이목(李穆, 1471년-1498년)의 위패를 모신 사당이다. 이목은 성종에게 불교를 받들도록 권한 윤필상(尹弼商)을 간사하고 나쁜 사람으로 지목하며 극형에 처할 것을 건의했으나, 오히려 임금을 화나게 만들어 공주 지역으로 쫓겨났다. 이때 이목은 청렴한 선비가 되기 위해 술 대신 차를 즐기며 차를 칭송하는 책[다부(茶賦)]을 지었다고 한다. 이에 매년 음력 7월 26일에 차를 올리는 헌다례(獻茶禮) 의식이 거행되고 있다. ○○○은 현재 ‘정간사(貞簡祠)’ 현판이 붙은 사당과 내삼문, 외삼문, 홍살문이 일렬로 구성되어있다.","a":"한재당","c":"시도기념물","nc":"","r":"경기도","s":"김포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646085.jpg"},{"q":"망천부락의 남쪽의 탑골에 암자터가 있는데 이곳에 3층석탑이 남아있어 ○○○○이라고 불리어지고 있는데 고려후기의 것으로 추측된다. 1982년 흥덕사를 세워 석탑을 경내에 옮겨두고 있으며 현재 2층만이 잔존하고 있다. 일명 사왕도석탑이라고도 함. 허왕후의 고향을 기리기 위해서 ○○○○을 만들었다고 전해지고 있으나, 고려후기 석탑으로 추정됨.","a":"김해 망월석탑","c":"문화유산자료","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664547.jpg"},{"q":"나주 나씨인 나사침(1526∼1596)을 비롯하여 3대에 걸친 충신 두 분과 효자 두 분 그리고 열녀 네 분의 행적을 기리기 위해 마을 입구에 세운 정려문이다. 나사침은 16세 때 어머니가 병으로 위급해지자 자신의 손가락을 잘라 피로 봉양하여 위기를 넘기고 어머니의 병을 낫게 하였다고 한다. 또한 그의 손자인 나득소(1607∼1640)는 어려서부터 효성이 지극하고 아버지인 덕현이 돌아가시자 3년상을 치르고 효를 다해 그의 할아버지와 함께 효자로 정려되었다.","a":"나씨삼강문","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662026.jpg"},{"q":"풀과 나무의 모습을 채색하여 그린 4폭 병풍으로, 각 그림의 크기는 가로 65.5㎝, 세로 222.5㎝ 이다. 원래는 8폭이었을 것으로 추정된다. 각 폭에는 오동나무, 단풍나무, 매화, 모란 등 각기 다른 초목을 한 종류씩 그려 놓았는데, 오동나무를 제외하면, 각 폭마다 짙은 묵으로 그린 기이한 모습의 돌이 함께 표현되어 있다. 어떤 폭은 푸른색의 바위와 붉은 꽃을 그려 색깔의 대비를 보여주기도 한다. 이러한 표현은 조선 후기인 19세기 궁중 가리개 등의 유물에서도 찾아볼 수 있다.","a":"용주사병풍","c":"시도유형문화유산","nc":"","r":"경기도","s":"화성시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637361.jpg"},{"q":"임진왜란 때 왜적과 싸우다 숨진 진주목사 서예원을 비롯한 그의 일가족 6명의 충절을 기리기 위해 세운 것이다. 서예원은 조선 선조 26년(1593) 왜적의 2차 침입 때 적은 군사와 무기를 가지고 진주성을 굳게 지키다 결국 전사하였다. 그의 부인 이씨와 큰아들 계성, 며느리 노씨 그리고 어린 딸도 밤낮으로 군사들을 도우며 싸우다가 성이 함락되자 남강에 뛰어들어 스스로 목숨을 끊었다. 둘째 아들 계철은 강에 몸을 던졌으나, 왜적에게 잡혀 일본으로 끌려갔다가 13년 뒤에 돌아올 수 있었다.","a":"육절려","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"횡성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638016.jpg"},{"q":"○○○는 청난공신 임득의 장군의 영정과 신위를 봉안하기 위해 지어진 사당으로 1632년에 최초로 건립되었으며 건축물이 노후퇴락하여 1872년 재건하여 보존하고 있는 사당으로 주변에 임득의 장군 묘소와 신도비 등이 일곽을 이루고 있다.","a":"정충사","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661581.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○를 세운 시기는 정확하게 알 수 없으나 고려 충렬왕(재위 1274∼1298) 때 동산리 유산에 세운 것으로 추정한다. 이후 조선 현종 10년(1669)에 지금 있는 자리로 옮겼고 철종 1년(1850)부터 이듬해까지 크게 고쳐 지었다. 건물 배치는 앞쪽에 학문을 배우는 공간인 명륜당이 있고 뒤쪽에 제사지내는 공간인 대성전이 있어 전학후묘 형태를 따르고 있다. 대성전은 앞면 3칸·옆면 3칸 규모로 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕이다.","a":"한산향교","c":"시도기념물","nc":"","r":"충청남도","s":"서천군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1652981.jpg"},{"q":"단재 ○○○ 선생의 생가이다. ○○○는 한말 일제시대에 역사가, 언론인, 독립운동가로서 활동했으며 26세가 되던 해에 성균관 박사가 되었으나 관직에 나아갈 뜻을 버리고 황성신문 기자가 되었다. 1905년 황성신문이 폐간되자, 그 이듬해 대한매일신보의 주필로 초빙되어 당당한 시론을 써 민중을 계몽하고 정부를 편달하였다. 한일합방이 되던 1910년 4월 망명길에 올라 블라디보스톡에서 신민회 회원들과 함께 독립운동을 전개하였다. 1919년 3·1운동 직후 임시정부가 수립되자, 그는 이승만 대통령의 위임통치에 반대하였다.","a":"단재신채호선생생가지","c":"시도기념물","nc":"","r":"대전광역시","s":"중구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645811.jpg"},{"q":"경상남도 ○○시 주촌면 양동리와 내삼리의 경계에 위치한 산봉우리를 두른 테뫼식 산성으로 일부는 흙으로 쌓고, 일부는 대강 다듬은 자연석을 사용하였다. 이 산성은 문헌상 ‘가곡산성’, ‘○○○○’이라고 부르고 있다. ○○평야와 낙동강 하구를 효과적으로 조망할 수 있는 있으며, 둘레는 약 800m이고 성벽의 높이와 폭은 2.5m이다. 남쪽과 북쪽의 문터에는 주춧돌이 남아있고, 성안에는 우물터의 흔적과 가야 토기조각들이 확인되었다.","a":"김해 양동산성","c":"시도기념물","nc":"","r":"경상남도","s":"김해시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1655306.jpg"},{"q":"직육면체 모양을 하고 있는 이 작품은 원래 탑의 중심이 되는 탑신부(塔身部)의 몸돌이었을 것으로 보인다. 아래윗면을 제외한 4면에 부처의 모습을 새겼는데, 모두 머리와 몸으로부터 빛이 나오는 형상을 표현하였고, 각기 손모양이 다르다. 윗면에는 도드라진 연꽃무늬를 두었다. 조각수법으로 보아 통일신라시대의 작품으로 보이며, 지금까지 우리나라에서는 그 비슷한 예를 찾아볼 수 없는 특이한 모습이다.","a":"경주동천동사방불탑신석","c":"시도유형문화유산","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640422.jpg"},{"q":"○○○○○은 전체높이가 61.8cm이나, 연화대좌를 제외한 坐像高는 50.7cm의 아담한 불상이다. 허리는 세우고 머리를 앞으로 약간 숙인 자세로, 신체에 비해 머리가 큰 편은 아니다. 수인은 엄지와 중지를 맞댄 중품하생인을 하고 있으나, 양손 모두 무릎 위에 위치하고 있어, 조선 17세기 이후 중품하생인의 특징을 나타내고 있다. 정수리 가운데에는 낮은 보계가 있고, 머리둘레에는 보관턱을 마련하지 않았다.","a":"하동금성사목조보살좌상","c":"문화유산자료","nc":"","r":"경상남도","s":"하동군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665494.jpg"},{"q":"선정비란 어진 다스림을 베푼 관리의 덕을 기념하기 위하여 세우는 것으로, 이 비는 홍천 현감을 지낸 원만춘(元萬春)의 덕을 기리고 있다. 다듬지 않은 바닥돌 위로 철로 만든 비를 세운 모습으로, 비 윗변에 귀 모양 같은 것이 양 쪽에 하나씩 앙증맞게 솟아 있다. 비 앞면 중앙에는 세로로 비의 이름을 새겨두고, 양 옆으로 두 줄씩 비문을 도드라지게 새겨 놓았다. 뒷면에는 이 비를 만든 장인(匠人)의 이름도 기록되어 있어 독특한 모습이다. 원래는 홍천군 홍천읍 희망리 홍천군청 앞 도로가에 서 있었으나, 홍천박물관 내로 이전하여 관리하고 있다.","a":"홍천철비","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"홍천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660426.jpg"},{"q":"무안 ○○○ 고분은 해발 35m 내외의 구릉에 위치하는데, 북동쪽에서 남서쪽으로 내려오는 구릉의 북서 사면에 위치하고 있다. 분구에는 다수의 민묘가 자리하고 있는데 분정 평탄부와 북서, 남서, 남동 사면에 분포하며 남동사면 끝자락은 깊게 패인 부분도 있다. 분구의 남동변을 제외한 나머지 부분의 분구 끝자락이나 주구에 해당되는 부분이 상당히 깎여나간 것으로 생각되며 분구에 민묘가 조성되면서 일부 변형되었지만 전체적인 보존상태는 양호한 편이다. 분구의 평면형태는 방형이며 축방향은 북동-남서이다.","a":"무안고절리고분","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"무안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2020051809575600.jpg"},{"q":"18세기에 건축된 ○○○○○은 전면 창호의 조형과 구성에서 보이는 독특함과 전체적인 통일성 등을 볼 때 조선후기 사찰 건축의 전형적인 특징인 간략화와 다양성을 보여주고 있어 조선후기 사찰건축의 양식적 특징 연구에 중요한 자료적 가치가 있다는 점에서 지정 보존가치가 있다.","a":"속초 신흥사 명부전","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"속초시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638374.jpg"},{"q":"동춘당 송준길(1606~1672) 선생이 강학하던 곳을 기념하여, 제월당 송규렴(霽月堂 宋奎濂, 1630~1709) 등 동춘당 송준길 선생의 제자와 문인들이 1693년(숙종 19)에 세운 누각이다. ○○○이라는 명칭은 동춘당이 읊은 시 가운데 \"골짜기에 물방울 지며 흘러내리는 옥 같은 물방울[層巖飛玉溜]에서 따온 이름으로 계곡의 아름다움을 따서 건물 이름으로 삼은 것이다. 앞면 3칸·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양을 한 팔작지붕이다. 계곡 사이의 바위를 의지하여 서로 다른 높이의 기둥을 세우고 마루를 짠 특이한 하부구조를 가지고 있다.","a":"옥류각","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637187.jpg"},{"q":"인동 장씨가 300여년 전에 입향한 금광마을 중턱에 있는 가옥이다. 지은 시기를 정확하게 알 수 없으나 조선 헌종 때 ‘동지중추부사’를 지낸 장연구(1802∼1892)가 지은 것으로 보인다. 영감댁으로 불리우는 이 집은 전체적으로 ㅁ자형 평면을 이루고 있다. 지붕은 사랑채만 옆면 지붕선이 여덟 팔(八)자 모양을 한 팔작지붕이고, 안채 등은 옆면 지붕선이 사람 인(人)자 모양을 한 맞배지붕으로 꾸몄다. 이 가옥은 조선 후기 민가 건축의 특징을 잘 간직하고 있다.","a":"금광리장씨고택","c":"문화유산자료","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662908.jpg"},{"q":"평산 신씨 영덕파의 재실로 조선 전기 문신인 신휘와 그의 손자인 심종부, 고손자인 신규년 등 3분의 위패를 모시고 제사 지내는 곳이다. 신휘는 조선 성종 때 전상서 주부(主簿)였고, 신종부는 중종 때 한성판관을 지냈으며, 신규년은 임진왜란 때 의병장으로 활약하다 순절한 분이다. 공부하는 건물인 수정서사(水晶書舍)를 一자로 가운데 두고 양 옆으로 방을 두었다. 처음에는 이 3분을 모시고 ‘세덕사(世德詞)’라고 하였으나 고종 때 흥선대원군의 서원철폐령으로 폐쇄되었다가 지금은 묘 앞에서 제사지내는 공간으로만 이용하고 있다.","a":"영덕수정재","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662838.jpg"},{"q":"○○○○ 고가는 ○○○ 한옥마을 내에 있으며, 안채, 사랑채, 대문채로 구성되어 있다. 정면 6칸 측면 1칸에 전후퇴를 둔 안채는 맞배지붕으로 부섭지붕을 하였으며 상량문의 기록으로 볼때 1644년에 건축된 것으로 보인다. 정면 2칸의 대청은 퇴를 합하면 4칸의 규모를 가지며 활처럼 휘어진 대볼보위에 5량의 가구를 두었고 판대공을 설치하였다 배면퇴와 후면퇴에는 머름을 두었으며 큰방과 인접한 후퇴칸에는 뒤주처럼 보이는 수장처를 두었다 창호는 판장문으로 처리했으며 대청의 가운데 기둥을 연결하는 장귀틀은 3개의 부재를 이어 촉으로 고정시켰다.","a":"함양개평리하동정씨고가","c":"문화유산자료","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1665204.jpg"},{"q":"○○○ 경내에 삼층석탑(보물 제467호)과 함께 서 있는 ○○으로, 원래부터 이곳에 있었던 것은 아닌 듯하다. 길쭉한 기둥 위에 받침돌, 불을 밝혀두는 화사석(火舍石), 지붕돌을 차례대로 올린 일반적인 형태로, 각 부재가 8각을 이루고 있다. 윗받침돌은 연꽃을 새겨 장식하였고, 화사석은 4면에 창을 두었다. 지붕돌은 모서리 부분의 파손이 심하며 꼭대기에는 간략한 구조의 머리장식을 올리고 있다. 전체적으로 통일신라 ○○의 양식을 보이고 있으나, 조각수법과 규모로 볼 때 시대가 조금 뒤떨어진 통일신라시대 후기의 것으로 추정된다.","a":"밀양 표충사 석등","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641361.jpg"},{"q":"○○○은 조선 숙종(재위 1674∼1720)때 북한산성을 축조하면서 군사들의 휴식처로 세웠다고도 하며, 연산군(재위 1494∼1506)의 유흥을 위해 지은 정자라고도 전한다. ○○○이란 이름은 광해군 15년(1623) 인조반정 때 이곳에서 광해군의 폐위를 의논하고 칼을 갈아 날을 세웠다고 한데서 세검(洗劍)이라는 이름이 유래되었다고 한다. 이 정자는 평면상 T자형이고, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 영조 24년(1748)에 고쳐 지었으나 1941년에 불타 없어져서 1977년 옛 모습대로 복원하여 오늘에 이르고 있다.","a":"세검정 터","c":"시도기념물","nc":"","r":"서울특별시","s":"종로구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1644756.jpg"},{"q":"신라 경덕왕 때의 학자인 설총의 묘이다. 아버지는 원효이고 어머니는 요석공주이며 출생시기는 태종무열왕대인 654∼660년 사이로 짐작된다. 나면서부터 재주가 많았고, 경사에 널리 능통하였다고 한다. 신라 유학의 종주가 되었으며, 후에 강수·최치원과 함께 신라의 3대 문장가로 꼽혔다. 그가 이두를 창제했다고도 하나, 그가 생존하기 전인 진평왕 때의『서동요』, 선덕여왕 때의『풍요』등이 이두로 기록되어 있는 점으로 보아 그가 창제한 것이 아니라 집대성한 것으로 보인다.","a":"전홍유후설총묘","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654625.jpg"},{"q":"○○○터에 흩어져 있던 탑의 일부분들로, 아래층 기단(基壇)과 위층 기단 일부, 탑신(塔身)의 몸돌 1개, 지붕돌 2개를 수습하여 민가 옆에 모아 놓았다. 위층 기단은 면의 가운데와 모서리에 기둥모양을 새겨 두었고, 기둥조각으로 나뉜 8곳에 8부신중(八部神衆:불교에서 불법을 수호하고 대중을 교화하는 여덟무리의 신)을 각각 조각해 두었다. 탑신의 몸돌에는 기둥 모양을 새겼으며, 지붕돌은 밑면에 4단의 받침을 두었는데, 네 귀퉁이에 방울을 달았던 구멍이 남아 있다.","a":"원주부흥사지석탑재","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660563.jpg"},{"q":"증 순충보조공신 가선대부 이조참판겸동지의금부사 진평군이었던 하위보에게 자헌대부 이조판서겸지의금부사 진평군을 증직함. 아들 하협의 정운원종공신 1등 책훈에 따른 추증.","a":"고신(교지)","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001642720.JPG"},{"q":"○○○의 잠룡동 계곡과 용계동 계곡이 합쳐지는 지점의 북쪽 경사지에 있다. ○○○는 창건과 관련된 구체적인 기록은 알 수 없다. 다만 ○○○에 1103년(고려 숙종8) 청동반자와 1344년(충혜왕 5년)에 만든 향완이 전하고 있어 고려 초에 창건된 것으로 보인다. 또한 1385년(고려 우왕11)에 조성된 태고 보우의 탑비를 통해 보우선사가 1341년 ○○○에 태고암을 짓고 주석하였음을 알 수 있다. 조선시대에는 태조 때 ○○○의 조세를 면제했고, 태종 때 이곳에서 기우제를 지냈다는 기록이 있어 조선 초기까지 어느 정도 사세를 유지하고 있었던 것으로 보인다.","a":"북한산중흥사지","c":"시도기념물","nc":"","r":"경기도","s":"고양시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1646722.jpg"},{"q":"이 유적은 ‘일곱드르 노랑굴’이라고도 한다. 우리 선현들이 일상 생활에서 사용하는 허벅·통개·병·장테 등의 도기를 만들었던 곳이다. 다른 지역에서는 그릇의 표면에 유약을 칠하지만, 이곳에서는 유약을 칠하지 않고 자연적으로 발색시킨다. 또한 다른 지역은 모두 토요(土窯)인 데 반하여 제주도의 도요는 세계에서 유일한 석요(石窯)이다. 이 유적은 제주도 특유의 도기문화를 꽃 피우던 곳일 뿐만 아니라, 우리 선현들의 지혜를 엿 볼 수 있는 곳이기도 하다. 이 굴은 동고 서저로 축조된 노랑굴○○○이다.","a":"신도리도요지","c":"시도기념물","nc":"","r":"제주특별자치도","s":"서귀포시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657982.jpg"},{"q":"이 비는 642년(신라 선덕여왕 11)에 대야성(大耶城)에서 전사한 죽죽(竹竹)의 충절을 기리기 위해 세운 것이다. 신라의 대야성은 642년에 윤충(允忠)이 이끄는 백제군에게 포위되었다. 이때 성주(城主) 김품석(金品釋)에게 아내를 빼앗긴 검일(黔日)이 창고에 불을 질러 성안을 혼란에 빠뜨렸다. 이에 전의를 잃은 김품석은 부하인 죽죽의 만류를 뿌리치고 항복하였다. 그런데 백제군이 항복하러 나온 사람들을 모두 죽여 버리자 김품석은 아내와 자식을 죽이고 자신도 자살하였다. 죽죽은 남은 병사를 거느리고 싸웠으나 백제군을 당할 수가 없었다.","a":"합천 죽죽비","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641671.jpg"},{"q":"복장에서 발견된 발원문에 따르면, 이 불상은 1674년(현종 15)에 백운산(白雲山) 영은사(靈隱寺)에 봉안하기 위해 200명에 달하는 시(施)·발원자(發願者)들이 동참하여 만들었고, 원래는 아미타여래를 본존으로 좌우에 관음과 대세지보살이 협시하는 아미타삼존상으로 조성되었음을 알 수 있다. 현재 좌우 협시인 관음·대세지보살상은 소실되었으며, 본존 아미타여래만이 ○○○ 대웅전의 주불로 예배되고 있다.","a":"함양 백운암 목조아미타여래좌상","c":"시도유형문화유산","nc":"","r":"경상남도","s":"함양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643162.jpg"},{"q":"○○○ 선생은 철종 12년(1861) 21세의 나이로 문과에 급제하였다. 고종 12년(1875)에 연로한 부친을 봉양하기 위하여 벼슬을 그만두고 고향에 내려왔으며, 고종 26년(1889) 동부승지로 제수되었으나 부임하지 아니하였고, 동학군으로 시국이 소란하게 되자 바로 부임하여 백성들을 무마하고 봉급을 고산 현민에게 나누어 주는 등 선정을 베풀었다. 1907년 일본의 만행이 날로 심해지자, 고향에 돌아와 새로운 인재를 양성할 목적으로 신명학교를 세웠으나, 1910년 한일합방 때 폐교되었다.","a":"장태수선생유물","c":"시도유형문화유산","nc":"","r":"전북특별자치도","s":"김제시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639527.jpg"},{"q":"연(輦)은 임금이 거동할 때 타는 가마를 일컫는 것으로, 이 가마는 조선 세조가 마곡사에 올 때 타고 온 것이다. 4명이 들 수 있도록 한 긴 멜대 위에 화려한 조각으로 장식된 사각형의 몸체를 올리고 지붕을 덮은 모습이다. 오랜 세월이 지나면서 보관상태가 좋지 않아 파손된 부분도 있고 채색도 희미한데, 세월의 흐름을 고스란히 담고 있는 듯 하다.","a":"세조대왕연","c":"시도민속문화유산","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658264.jpg"},{"q":"구미시 산동면 인덕리에 마련되어 있는 충직한 소의 무덤이다. 지름이 2m 되는 무덤과 그 앞에 비가 마련되어 있고, 그 뒤로는 가로 6.88m, 세로 0.8m, 폭 0.2 m 크기의 화강암에 의우도(소의 충직을 그린 그림)가 놓여 있다. 여기에는 다음과 같은 이야기가 전한다. 옛날에 문수점(지금의 인덕리)이라는 마을이 있었는데 그곳은 3면이 산이었다. 이 마을에는 김기년이라는 사람이 암소 한 마리를 키우고 있었는데, 어느해 여름 밭을 갈고 있을 때 갑자기 호랑이가 소에게 덤벼들었다.","a":"의우총","c":"시도민속문화유산","nc":"","r":"경상북도","s":"구미시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658826.jpg"},{"q":"이 비석은 예전에 이곳에 자리잡았던 화산서원에 있던 것이다. 화산서원은 조선 선조 11년(1578)에 건립하여, 조선 전기의 대학자 이언적(李彦迪)과 송인수(宋麟壽)의 위패를 모시고 제사지내던 곳이다. 이언적은 전주 부윤으로 부임하여 도덕과 예절로 백성의 교화에 힘썼고, 송인수는 전라 감사로서 청렴한 정치를 펼쳐, 각각 이 지역과 인연이 깊었다. 화산서원은 효종 9년(1658)에 나라에서 이름을 지어주고 후원하는 사액서원으로 선정되기도 하였으나, 고종 5년(1868) 서원철폐령에 따라 헐렸다.","a":"화산서원비","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"전주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661607.jpg"},{"q":"백암산에 위치한 ○○○는 백제 무왕 33년(632) 여환이 처음 지은 절이다. 이후 여러 차례 다시 지어지기도 하고 이름이 바뀌기도 하였는데, 지금의 ○○○라는 이름은 조선 선조 7년(1574) 환양이 절을 다시 지은 이후부터이다. 환양이 절에 있으면서 매일 『법화경』을 읽을 때 흰 양이 경 읽는 소리를 듣고 몰려오는 일이 많아지자 절 이름을 ○○○로 고쳤다 한다. ○○○의 정문인 ○○○○은 1917년 송만암에 의해 절이 크게 다시 지어질 때 5년에 걸쳐 지어졌다. 앞면 5칸·옆면 2칸 규모의 건물로, 지붕 옆면이 사람 인(人)자 모양의 맞배지붕집이다.","a":"장성 백양사 사천왕문","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장성군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639875.jpg"},{"q":"이 ○○은 조선시대 세종조의 문신인 경재 ○○의 시문집을 새기기 위한 책판이다. ○○은 조선 전기의 문신으로, 정몽주의 문인이었다. 1396년 문과에 급제하여 여러 벼슬을 두루 거쳤으며, 대사헌, 형조판서, 좌참찬 등 높은 벼슬을 하였다. 이 책판은 ○○의 5대손 하흔이 흩어진 원고를 모아서 광해군 1년(1609)에 합천 해인사에서 ○○본으로 간행하였다. 당시에는 이 책판만 따로 간행한 것이 아니라『진양연고』속의 일부분으로 편집하여 간행하였으며,『경재집』은 5권 3책으로 이루어져 있다.","a":"하연 경재문집 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641777.jpg"},{"q":"석조○○○○○을 본존불로, 좌측에 관음과 우측에는 지장보살을 협시로 두었다. 불상조성기를 통해 원래 통도사 약사전에 봉안되었던 불상이 이곳 ○○○으로 옮겨왔다는 사실을 확인 할 수 있었다. 이 불상은 파손이나 도금의 박락없이 대체로 양호한 상태이다. 불상 밑바닥 가운데에는 복장공이 마련되어 있고, 입구는 현재 한지를 붙여 두었다. 복장물은 사찰에서 이미 개봉하여따로 보관해 두고 있고, 그 내용물은 불상조성기를 비롯하여 인쇄본 다라니, 약재, 동제후령통과 후령통 내에 오곡, 오색사 등 다양한 봉안물이 포함되어 있다.","a":"양산원효암석조약사여래좌상과복장유물","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642600.jpg"},{"q":"영원사터라고 전하는 곳에 각 부분이 흩어져 있던 것을, 1974년 11월 현재의 자리로 옮겨 세운 것으로, 고려 시대 승려인 ○○○○의 부도(사리탑)로 추정된다. 8각의 평면을 기본형으로 하고 있으며, 탑신(塔身)의 몸돌이 없어진 채, 기단(基壇)과 지붕돌만이 남아 있다. 기단은 안상(眼象), 소용돌이치는 구름무늬, 연꽃무늬를 새겨 화려하게 장식하였다. 지붕돌은 목조건축을 모방하여 기와골과 막새기와까지 표현해 놓았다. 전체적으로 화려하고 복잡한 장식을 하고 있으며, 통일신라 후기의 양식을 계승하고 있다.","a":"밀양 영원사지 보감국사 승탑","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641359.jpg"},{"q":"○○○○○은 명나라 영덕(寧德)우바색(優婆塞)진실(陳實)이 건국 초에 편찬하여 건안의 유오삼랑서국에서 간행·보급한 것으로, 이 판본이 우리나라에 들어오자 바로 고려 말기에서 조선 초기 사이에 번각(飜刻 ：바탕책을 뒤집어 판목 위에 붙이고 그대로 새김)하고 그 각판에서 찍어낸 것으로, 책장에 따라 새긴 글자에 다소의 마멸이 나타나고 있는 점으로 미루어 그 뒤 조선 전기에 찍어낸 것이다. 이 판본은 조선 전기에 찍어낸 전 10권 중 제 7 ·8권 영본 1책이 전래된 것으로 대체로 양호한 편이다.","a":"대장일람집 권7, 8","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"연수구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637130.jpg"},{"q":"양성지(1414∼1482)를 기리기 위해 1922년 세운 사당이다. 양성지는 조선시대 문신으로서 호는 눌재이다. 대사헌·이조판서 등 여러 벼슬을 지냈고 항상 나라를 위해 현실적인 정책을 연구한 인물이다. 민생을 위해 각 지방에 의료기관 설치를 주장하였고 우리나라 고유의 풍습이 중요함을 강조했으며 과거 시험에 대해서도 현실에 맞도록 바꾸길 요구하였다. 또한 ○○○ 사숙을 열어 향토 교육에도 이바지하였다. ○○○에는 선생의 공적을 적은 눌재 양선생 묘비(廟碑)가 있다.","a":"귀암사","c":"문화유산자료","nc":"","r":"충청남도","s":"금산군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661372.jpg"},{"q":"○○○○는 원래 서애(西厓) 유성룡(1542∼1607)의 묘소를 수호하기 위한 재사 건축물이었다. 아들 유초가 찬한 『유천선생유고(柳川先生遺稿)』의 「상로재기(霜露齋記)」에 의하면, 서애가 죽은 후 5년이 되는 광해군 3년(1611)에 포우(浦右)라는 승려의 도움을 받아 재사를 창건하고 ＇상로재(霜露齋)＇라는 현판을 달았다고 한다. 그 후 이 재사는 여러차례 중수를 거듭했을 것으로 추측되지만 중수기를 비롯한 자료 부족으로 자세한 내력은 파악할 수 없다.","a":"풍산류씨수동재사","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658877.jpg"},{"q":"○○○는 신라 법흥왕 때 유일대사가 세웠다고 하나, 〈○○○대웅전상량문〉에 의하면 신라 경순왕 때 창건된 것으로 알려져 있으며, 비로전 대들보에서 발견된 묵서에는 고려 혜종(943∼945)년간에 중수되었음을 기록하고 있다. 이 ○○○○는 남북 기준방향에서 북서∼남동 방향으로 30˚ 가량 틀어져 있다. 현재 비신(碑身)과 이수(이首)는 결실되었고 귀부(龜趺)만 남아 있다. 귀부는 받침석과 한 돌로 조각되었으며 받침석의 평면형태는 방형이다. 4개의 다리는 힘차고 생동감있게 묘사되었고 발톱은 날카롭다.","a":"괴산 각연사 석조귀부","c":"시도유형문화유산","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638761.jpg"},{"q":"족보란 잘 알려진 바와 같이 일족의 그들 시조로부터 족보 편찬 당시까지의 친족계보를 기록한 것이다.『○○○○○』목판은 숙종 28년(1702) 윤선도 등을 주축으로 여러 문중들이 추원당을 건립하면서 이와 함께 문중 결속과 친족간의 유대를 도모하기 위해 만들어진 것이다. 족보에 기록된 내용을 보면 우선 아버지쪽과 동일하게 어머니쪽도 모두 기록하고 있고, 자녀를 남자, 여자 순서로가 아니라 태어난 순서대로 기록하고 있다. 또한 본처의 자식과 첩의 자식을 그대로 기록하면서 외손의 경우 성씨를 기입, 이름만 기록된 아버지 계열과 구분하였다.","a":"해남윤씨족보목판","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"강진군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640100.jpg"},{"q":"뒷쪽의 나지막한 야산을 배경으로 자리한 이 집은 약 250여 년 전에 지은 것으로 보인다. 안채와 사랑채·곳간에 의해 ㅁ자형으로 배치되어 있으며 안뜰이 있다. 안채는 앞면 3칸·옆면 2칸의 규모이며, 一자형 겹집이다. 오른쪽에 부엌을 두고 4개의 방이 있으며, 안뜰 쪽으로 2칸의 방앞에 툇마루를 놓아 연결통로로 활용하고 있다. 지붕 옆면이 여덟 팔(八)자 모양인 화려한 팔작지붕집이다. 부엌에 연결된 곳간과 마굿간이 사랑채 쪽으로도 연결되어 있으며 그 사이에 대문이 있다. 사랑채는 ㄴ자형으로 5칸 규모이며, 왼쪽으로는 안채와의 사이에 대문칸과 행랑방이 자리하고 있다.","a":"동해 심의관 고택","c":"시도유형문화유산","nc":"","r":"강원특별자치도","s":"동해시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638063.jpg"},{"q":"조선 중기의 학자로 퇴계 선생의 제자인 금난수(1530∼1604) 선생의 정자이다. 선생은 명종 19년(1564)에 이미 예안에서 ‘성재’라는 정자를 짓고 학문에 전념하였으며, 이어서 당시 선성(예안현)의 명승지 가운데 한 곳인 가송협에 ○○○을 짓고 ‘일동정자’라 하였다. ○○○은 앞면 3칸·옆면 2칸이며 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕 건물이다. 가운데 칸의 우물마루를 중심으로 좌우에 온돌방을 두었다. 이곳은 경치가 빼어나서 퇴계 선생을 비롯하여 많은 선비들의 왕래가 끊이지 않던 곳으로 퇴계 선생의 시와 금난수 선생의 시 등이 남아있다.","a":"고산정","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640859.jpg"},{"q":"○○○ 장승은 마을 입구 ＇장석거리＇ 또는 ＇삼거리＇ 라고 불리는 곳에 서 있다. 화강석으로 형태는 머리에 약 30cm 높이의 갓모양의 모자를 쓰고 몸에 도포형의 긴 옷을 걸친 모습이다. 어깨에서부터 반듯이 내린 소맷자락 아래로 다섯 개의 손가락이 펼쳐져 있다. 80cm 길이의 얼굴은 290cm의 장승 전체 크기에 비해 다소 긴 편이다. 커다란 타원형의 눈이 툭 튀어나와 있고, 좁은 양미간에서 길게 내려 온 삼각형 코는 두툼하며 투박한 느낌을 준다. 한편 얼굴 측면의 귀는 길고 두툼하게 이어 내려와 투박하면서도 일면 석가모니 귀처럼 부드러운 느낌을 준다.","a":"신안도초고란리석장승","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"신안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662295.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 교육기관이다. ○○○○는 조선 세종 20년(1437) 처음 지었으나 정유재란 때 모두 불타버렸다. 그 뒤 인조 원년(1623)에 다시 세웠고 효종 7년(1656)에 지금 자리로 옮긴 것으로 보인다. 앞쪽에는 교육 공간을 두고 뒤쪽에는 제사 공간을 배치하였다. 학생들이 모여 공부하는 강당인 명륜당은 앞면 7칸·옆면 2칸 규모이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 공자를 비롯하여 중국과 우리나라 성현의 위패를 모신 대성전은 높은 축대 위에 세웠다.","a":"진도향교","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"진도군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662070.jpg"},{"q":"신라 진흥왕 13년(552)에 창건한 ○○○에 있는 마애불로 방 모양으로 암벽을 파고 그 안에 불상을 도드라지게 새겼는데, 붉은 바위색이 퍽 인상적인 작품이다. 사찰에서는 마의태자상이라고 하는데 마의태자를 추모하였던 신라 도공의 후손이 염불하는 태자의 모습을 그리워하며 미륵불을 조각하였다고 한다. 이 마애불은 영험이 있어 기도하면 이루어지지 않는 것이 없다고 전한다. 발을 좌우로 벌리고 연꽃대좌 위에 서 있으며, 가늘고 긴 눈, 작은 입, 가는 코 등이 묘사된 얼굴에는 파격적인 미소에도 불구하고 도식화된 모습이 보인다.","a":"옥천 용암사 마애여래입상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"옥천군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638418.jpg"},{"q":"내장산에 있는 옛 내장사터로서, 『신증동국여지승람』에 의하면 ‘백련사는 내장사라고도 이르며 내장산에 있다.’라고 하였다. 백련사는 언제 세운 것인지 알 수 없으나 백제 의자왕20년(660)에 유해선사가 세웠다고 한다. 조선시대의 명필인 추사 김정희가 ‘백련(白蓮)’을 ‘벽련사(碧蓮寺)’로 개칭하고, 현판을 써서 걸었으나 한국전쟁 때 소실되었다. 1925년 학명선사가 아미타불을 봉안한 극락보전을 고쳐짓고, 스님들이 생활하던 요사채와, 도량건물인 선원을 세웠으나 역시 한국전쟁 때 소실되었다.","a":"내장사지","c":"시도기념물","nc":"","r":"전북특별자치도","s":"정읍시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653572.jpg"},{"q":"이 목조보살좌상은 둥글고 부드러운 얼굴에 무릎으로 내려올수록 커지고 넓어지는 경향을 보이는 작품이다. 특히 무릎이 높고 넓은 편으로 전체적으로 안정감 있는 모습에 둥근 얼굴은 미소가 있어 부드러운 느낌을 준다. 머리 부분은 뒷면이 많이 손상되어 안이 노출되어 기법을 알 수 있는데 그 흔적으로 보아 나무 위에 흙으로 보강하고 표면에는 칠과 같은 가소성 있는 재료를 이용하여 머리카락을 새긴 것으로 추정된다. 보게는 없으나 둥근 흔적이 남아 있어 원래는 따로 만들어 끼웠던 것이 없어졌을 것으로 추정된다.","a":"태안 법정사 목조관음보살좌상","c":"문화유산자료","nc":"","r":"충청남도","s":"태안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/2019042415031903.png"},{"q":"원래 경상북도 봉화군 성화곡 절터에서 발견된 것을 ○○○로 옮겨서 보관하고 있으며, 두 손을 새로 만든 것 이외에는 거의 완전한 형태이다. 민머리 위에 있는 상투 모양의 둥글고 큼직한 머리묶음, 토실토실한 얼굴에 아담한 이목구비 등은 통일신라 후기의 불상양식을 잘 반영하고 있다. 둥근 어깨, 잘록한 허리, 통통한 다리 등에서 부드러움과 균형잡힌 부피감을 엿볼 수 있다. 이러한 신라적인 특징은 옷입는 법에서도 나타나는데, 양 어깨를 감싸고 입은 옷은 간결한 몇 가닥의 계단식 주름으로 처리하고 있다.","a":"천성사석조여래입상","c":"시도유형문화유산","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640521.jpg"},{"q":"○○ 영당은 최영, 이순신, 이대원, 정운 장군과 용왕신, 산신 등을 모시고 있는 제당으로 ○○의 읍지와 향토지, 각종 역사지리서, 토지대장 등을 통해 영당의 역사성과 장소성을 살펴볼 수 있다. 영당에서는 매년 춘추로 제전이 펼쳐졌고, 영당 앞을 지나는 배들은 고사미를 내고 고사를 지낸 후에 출어하는 풍속 등 민속신앙의 현장으로서 민속적 의미가 있고, ○○ 영당은 ○○지역의 역사와 밀접한 관련이 있는 제당으로 복원된 건물 자체의 가치는 높지 않기 때문에 영당의 역사적 의미와 장소성의 의미를 살려 ○○○로 지정하여 보존할 필요성이 있다.","a":"여수 영당지","c":"시도민속문화유산","nc":"","r":"전남광주통합특별시","s":"여수시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658430.jpg"},{"q":"안채와 사랑채 2동으로 이루어진 집인데 본래 상태를 유지하고 있는 것은 안채이다. 안채는 ㄱ자형 평면을 갖추고 있으며 대청을 중심으로 왼쪽에 건넌방 2칸, 오른쪽에 안방과 부엌을 직각으로 배치하였다. 건넌방 앞에서 대청까지 툇마루를 설치하였고 안방의 바깥쪽으로도 툇마루를 두었다. 사랑채는 一자형 평면을 갖추고 있으며 대문을 중심으로 왼쪽에 광을, 오른쪽에는 사랑방 2칸을 두었다. 그 오른쪽에 세운 별채는 외양간과 디딜방앗간으로 구성되었으나 방앗간은 현재 헛간으로 사용하고 있다.","a":"평창지동봉가옥","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"평창군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660471.jpg"},{"q":"이 영정은 능암당 ○○선사의 좌안 8분면 바닥가부좌상으로, 상단벽면과 하단돗자리의 이단구도를 배경으로 하여 등받이의자를 배치하고 바닥에는 방석을 깐 후 양손에 각각 주장자와 염주를 쥐고 측면을 바라보며 앉아 있는 모습이다. 의자에는 연부에 연화당초문양이 그려진 녹색 법피를 드리우고 있다. 화면 향우측에 주지백서의 ‘양종도총섭릉암당○○지진(兩宗都摠攝庱庵堂宇伸之眞)’ 화제가 있을 뿐이다. 화면 크기는 가로 81.8cm, 세로 124.3cm이다.","a":"도암당 우신 진영","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/0000000001643010.JPG"},{"q":"○○○○는 사찰 입구에 설치해 두는 것으로, 절에 행사나 의식이 있을 경우 이곳에 당이라는 깃발을 걸어둔다. 이 깃발을 매달아두는 길쭉한 장대를 당간이라 하며, 이를 양쪽에서 지탱해 주는 두 돌기둥을 ○○○○라 한다. 보통 당은 없고 드물게 당간이 있으나, 대부분은 두 기둥만 남아있다. 이 ○○○○는 비로사로 올라가는 언덕 왼편의 높은 지대에 서 있다. 서로 마주보는 두 기둥의 안쪽면은 평평하며, 맨 위와 가운데에 각각 당간을 고정시키기 위한 네모난 홈을 두었다.","a":"영주삼가동석조당간지주","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640249.jpg"},{"q":"이 ○○은 임진왜란 때 이순신 휘하에 있으면서 여러 해전에서 많은 전공을 세워 전후에 선무원종공신에 책록된 이응표(1555~1611)와 그 후손의 전적 및 ○○이다. 『선무원종공신녹권』은 병자호란 이전의 간본으로 여기에 수록된 공신은 임진왜란의 양상을 연구하는 데 중요한 자료이다. 또한 이응표 부자의 교지 및 유서, 호구단자 등의 고문서는 해당 시대의 사회경제적 이면을 이해하는 데 중요한 자료이다.","a":"포항 합천이씨 전서공파 소장 유물","c":"시도유형문화유산","nc":"","r":"경상북도","s":"포항시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641213.jpg"},{"q":"○○○○○은 동래부의 ○○○과 함께 전국적으로도 남아 있는 사례가 드문 군관용 관아 건물이다. 조선 중기 이래의 간소한 굴도리식 건물로써 건축사적으로 크게 주목될 뿐 아니라 문화유산적 가치도 뛰어나며, 조선 후기 부산 및 ○○ 지역 관아 건축의 양상을 보여주는 몇 안 되는 건축 유구(遺構)로 우리나라 동남해안의 전략 요충지였던 ○○군의 역사성을 고스란히 담고 있는 소중한 건축 문화유산이다.","a":"기장 장관청","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"기장군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2575235.jpg"},{"q":"태산에서 동쪽으로 뻗은 낮은 구릉이 영산강의 지류인 금천과 만나는 지점에 있는 무덤이다. 원래 이곳에는 2기의 무덤이 있었으나 1기는 파괴되고 1기만 남아있다. 남아있는 1기도 천정부가 훼손되고 부장유물이 모두 도굴되었으나 내부구조는 거의 완벽하게 남아있다. 구조는 반원아치형의 활천정(궁륭식천정)을 한 굴식돌방무덤(횡혈식석실분)이다. 널방(현실)의 중앙에 널길(연도)을 두었고 널방에서 입구로 갈수록 좁아지는 형태이다. 널방의 벽은 깬돌을 이용하여 바닥에서 약 80㎝를 수직으로 쌓고, 그 위로 모서리를 다듬어 천정을 현실바닥의 ⅓까지 좁혀 쌓았다.","a":"나주송제리고분","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"나주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/2019051719433100.jpg"},{"q":"조선시대에 많은 유생들을 배출하였던 곳이다. 성종 4년(1473)에 박씨·남씨·진씨의 세 성씨가 세웠는데 호랑이의 피해가 있어서 철폐하였다. 그 뒤 숙종 35년(1709)에 김·이·우·정씨의 사성이 처음 있던 학구당에서 300여m 떨어진 곳에 새롭게 학구당을 세웠다. 지금 있는 ○○○○○ 건물은 1966년에 고쳐 지은 것이다. 규모는 앞면 4칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다. ○○○○○은 새로운 나라의 정치·사회 이념에 따라 당시 정책을 세우는데 필요한 구조물이었던 것이다.","a":"수북학구당","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"담양군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661908.jpg"},{"q":"임진왜란 때 공을 세운 충무공 김시민(1544∼1592)과 충숙공 김제갑(1525∼1592)의 위패를 모시고 있는 사당이다. 김시민은 임진왜란이 일어나자 진주목사가 되어 사천, 고성, 김해 등지에서 적군을 대파하고, 진주성 싸움에서 3800여명의 병력으로 2만 대군과 맞서 싸워 승리를 거두었다. 김제갑은 임진왜란 때 왜군이 원주로 쳐들어오자 관군과 의병을 이끌고 영원산성에 들어가 항쟁하였으나 성이 함락되자 그의 부인 이씨, 아들 김시백과 함께 순절하였다. 선조 때 이분들의 절개와 업적을 기리기 위해 사당을 세웠다.","a":"괴산 충민사","c":"시도기념물","nc":"","r":"충청북도","s":"괴산군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1649233.jpg"},{"q":"○○대학교 안에 있던 ○○○ 야외에 안치되어 있던 불상으로, 광배는 없고 대좌(臺座)와 불신만이 남아있는 통일신라 후기의 전형적인 비로자나불상이다. 머리에는 작은 소라 모양의 머리칼을 붙여 놓았으며, 그 위로 상투 모양의 머리묶음이 큼직하게 표현되었다. 활모양의 눈썹, 큼직한 코, 굳게 다문 입 등은 양감있는 얼굴과 알맞게 조화되어 원만한 인상을 보여주고 있다. 두 귀는 거의 어깨까지 내려왔으며 목에는 부드러운 곡선의 3주름이 표현되었다. 옷은 양 어깨를 감싸고 있으며 옷주름은 좌우대칭의 평행선으로 약간 도식화되었다.","a":"청주 용암사 석조비로자나불좌상","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638431.jpg"},{"q":"김정호의 ○○○○를 기초로 펜으로 필사한 지도로, 1892년 경에 제작되었으며 미국인 선교사들이 사용했던 것으로 추정된다. 현전하는 한글본 한양지도가 희소하고, 구한말 한양의 지명을 구체적으로 알 수 있는 등, 지도학사적․어문학적으로 가치가 있다.","a":"수선전도","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"서대문구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636521.jpg"},{"q":"○○○은 조선 영조 51년(1775) 반계 이숙(1720∼1807)이 지은 정자로, 사람들과 이야기를 나누며 시를 읊던 곳이다. 이숙은 세속을 떠나 시골에서 글을 읽으며 지내던 선비로 유명하였다. 이 정자는 ○○강의 맑은 물이 감도는 강 언덕 반석 위에 서 있다.","a":"밀양 반계정","c":"문화유산자료","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664354.jpg"},{"q":"월아산 기슭에 위치한 ○○○는 통일신라 경문왕 13년(873)에 도선국사가 지은 절로 임진왜란(1592) 때 완전히 불타 없어졌던 것을 조선 광해군 4년(1612) 포우대사가 다시 지어 오늘에 이르고 있다. 석가삼존불상을 모시고 있는 ○○○은 광해군(재위 1608∼1623) 때에 다시 지어졌다. 앞면 3칸·옆면 2칸 규모의 건물로, 지붕 옆면이 여덟 팔(八)자 모양인 팔작지붕집이다. 지붕 처마를 받치면서 장식을 겸하는 공포가 기둥 위와 기둥 사이에도 있는 다포계 건물이다.","a":"진주 청곡사 대웅전","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641456.jpg"},{"q":"조선 인조(재위 1623∼1649) 때 김경여(1596~1653)가 지은 별당건물이다. 그의 호를 따서 ○○○이라 이름지었다. ‘송애(松崖)’는 눈서리를 맞아도 변치않는 소나무의 곧은 절개와 높이 우뚝 선 절벽의 굳센 기상을 간직하겠다는 뜻으로, 김경여의 높은 기개와 충성심을 잘 표현하고 있다. 송시열이 지은 송애정사기(松崖精舍記)가 전하며 상량문은 창건 때의 것은 없고 중수 때의 것만 있다.","a":"송애당","c":"시도유형문화유산","nc":"","r":"대전광역시","s":"대덕구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637188.jpg"},{"q":"마을 앞 논 가운데 자리하고 있으며, 탑이 속해있던 절의 역사는 전하는 것이 없다. 전체적인 모습은 2층 기단(基壇) 위에 3층의 탑신(塔身)을 올린 형태이다. 기단부는 크게 파손되어 전체가 동쪽으로 13∼15도 정도 기울어져 있던 것을, 1979년에 해체 ·보수하였다. 위층 기단 윗면은 연꽃무늬를 돌아가며 새기고, 가운데에 윗돌을 괴기 위한 높직한 괴임을 두었다. 탑신부의 1층 몸돌에는 문짝모양을 새겼다. 급한 경사가 흐르는 지붕돌은 밑면에 4단의 받침을 두었는데, 몸돌에 비해 처마가 좁고 줄어드는 비율도 적어 무거워 보인다.","a":"안동임하동동삼층석탑","c":"시도유형문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640433.jpg"},{"q":"부도는 승려의 무덤을 상징하여 그 유골이나 사리를 모셔둔다. 이 부도는 ○○○ 대웅전 뒤쪽의 부도밭에 자리잡고 있는 10여기의 부도들 중 하나로, 이 절의 주지이면서 승병장으로 유명하였던 벽암대사의 사리가 안치되어 있다. 형태는 둥글게 다듬은 바닥돌 위로 종모양의 탑신(塔身)을 올리고, 사각의 지붕돌을 얹어놓은 모습이다. 바닥돌 윗면에는 16잎의 연꽃무늬를 새겨 둘러 놓았다. 탑신에는 ‘○○○’이라는 승려의 호를 새겨 그 주인공을 정확히 밝히고 있다. 지붕돌은 다소 투박해 보이나 네 귀퉁이에서 살짝 위로 들려 약간의 가벼움을 실었다.","a":"송광사벽암당부도","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"완주군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661797.jpg"},{"q":"○○○○○은 자경마을 입구에 있었던 것으로 경지 정리 시 도로변에 옮겨 세운 것이다. 화강암을 돌기둥처럼 다듬었는데 상부가 남근의 귀두와 같다고 하여 ○○○이라고 부른다. 제작 연대는 확실하지 않다. 높이 200cm이고 사각기둥 꼴의 몸통은 각 변의 폭이 28cm 정도이며 둘레는 113cm이다. 상부의 귀두 부분의 높이는 37cm, 차양 및 괴임 높이는 16cm이며, 갓 너비는 일변 36cm로서 약간 퍼져 있는 형국이다.","a":"사곡리남근석","c":"시도민속문화유산","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658326.jpg"},{"q":"보한재 신숙주의 초상을 모시기 위해서 지은 영당으로, 지금의 영당은 1830년 창건하여 1888년(고종 25)에 중건하였다. 앞면 3칸·옆면 2칸의 목조 기와집이며, 옆면이 사람 인(人)자 모양인 맞배지붕이다. 신숙주는 조선 전기의 문신으로 훈민정음을 만들 때 참가하여 많은 공을 세웠으며, 그 시대의 정치와 학문에도 영향력이 컸다. 영정(초상)은 마루방에 보관하고 있고, 영조(재위 1724∼1776) 때에 구봉영당에서 모시고 있는 신숙주 초상을 옮겨 그린 것이다. 옮겨 그릴 때 정범조가 초상에 대해 쓴 글이 기재되어 있다.","a":"청주 묵정영당","c":"시도유형문화유산","nc":"","r":"충청북도","s":"청주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638564.jpg"},{"q":"한말의 도학자 오준선(1851∼1931)이 강당을 짓고 후학을 양성하던 곳이다. 오준선은 오하규의 아들로 태어나 백부 항규에게 입양되었다. 18세부터는 노사 기정진에게 배우며 학문의 폭을 넓혔으며, 일제의 회유정책에도 굽히지 않고 1917년에 용진산에 들어가 생을 마칠 때 까지 후학을 가르쳤다. ○○○○는 원래 용진사라는 절이 있던 곳인데 절이 허물어 진 뒤 정안 이씨가 그 터를 가지고 있었다. 이때 오준선의 뜻을 전해 듣고 절터의 일부를 내주어 건물을 짓게 되었다.","a":"용진정사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659600.jpg"},{"q":"○○○○○은 두암이 20세에 분가할 때 지은 집으로 몸채 24칸·함집당 6칸·사당 6칸으로 되어있다. 정침은 조선 선조 23년(1590)에 지었고, 함집당과 사당은 그 후대에 지은 것이다. 두암 김우익(1571∼1639)은 광해군 4년(1612)에 문과에 급제하여, 영원군수, 해미현감을 역임한 후 한성부원에 이르렀다.","a":"우금촌두암고택","c":"시도유형문화유산","nc":"","r":"경상북도","s":"영주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1640384.jpg"},{"q":"선방(禪房) 앞에 자리하고 있는 석탑으로, 원래는 2층 기단(基壇) 위에 3층의 탑신(塔身)이 놓여 있었을 것이나 지금은 아래층 기단의 일부와 탑신의 2층 지붕돌 이상을 잃어버린 상태이다. 위층 기단은 각 면마다 모서리와 가운데에 기둥을 본 뜬 조각을 두었으며, 탑신의 1층 몸돌을 괴는 곳에 얕은 받침을 새겨 놓았다. 2층 몸돌까지만 남아있는 탑신은 1층 몸돌만 따로 만들었고 1층 지붕돌과 2층 몸돌은 하나의 돌로 만들었다. 몸돌의 모서리에는 기단에서와 같은 기둥 모양의 조각이 있고, 지붕돌은 밑면에 4단의 받침을 새겼다.","a":"축서사삼층석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"봉화군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662710.jpg"},{"q":"○○○○○경은 줄여서 ‘○○○’이라고 부르기도 하는데, 우리나라 화엄종의 근본경전으로, 부처와 중생은 둘이 아니라 하나임을 기본 사상으로 하고 있다. ○○○의 普賢行願品만을 별도로 편집한 것으로 해탈의 세계에 들어가기 위한 보 현보살의 실천과 염원을 담고 있으며, ○○○ 중에서도 판각이 제일 성행하였던 부분이다. 이 판본은 乙酉字로 세조연간(1455～1468)에 간행한 금속활자본이다. 乙酉字는 원각경 등 불경을 인출하기 위해 세조의 명을 받아 정란종의 글씨를 字本으로 주조한 큰 자, 중간 자, 작은 자의 동활자인데 자체가 고르지 않아 별로 이용되지 않았던 활자였다.","a":"대방광불화엄경보현행원품","c":"시도유형문화유산","nc":"","r":"충청북도","s":"단양군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1638942.jpg"},{"q":"수애 유진걸이 1939년에 지은 집이다. 유진걸의 호를 따라 ○○○이라 하였으며 처음 임동면 수곡동에 있었으나 임하댐 건설로 1987년에 지금 있는 자리로 옮겼다. 3동의 건물로 이루어졌는데 중심 건물은 앞면 7칸·옆면 2칸이며, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양의 팔작지붕이다. 창고는 앞면 10칸의 ㄱ자형 평면을 취하고 있다. ○○○은 춘양목으로 지어 보존상태가 매우 좋으며 조선 후기의 건축 양식을 잘 나타내고 있다.","a":"수애당","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662456.jpg"},{"q":"조선 성종 때의 문신 양소당 김영수(1446∼1502) 선생의 종가집이다. 김영수 선생은 태사 김행의 후손으로 사헌부 장령을 지낸 분이다. 안채와 사랑채로 이루어진 ㅁ자형 집이다. 사랑채는 왼쪽에 방을 두고 오른쪽에 마루를 놓아 제사 때 제청으로 활용할 수 있게 하였다.","a":"안동김씨종택","c":"시도민속문화유산","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/folklore_material/thumb/1658501.jpg"},{"q":"모두 4단으로 이루어진 이 묘역에는 15∼18세기에 걸쳐 상산김씨(商山金氏) 13대 후(後)를 비롯한 모두 6기의 묘가 조성되어 있다. 이중 13대 후와 14대 장(張)의 묘는 방형분이고, 19대 경근(敬謹)과 25대 규한(奎漢)의 부인 평산신씨(平山申氏)의 묘는 원분(圓墳)이다. 가장 상단에 위치한 ○○의 묘는 부인 장씨(長氏)와 합장되어 하나의 봉분으로 이루어져 있는데, 갑석의 각 모서리는 끝이 가볍게 들어 올려져 있어 탑의 옥개석을 연상케 한다.","a":"산청 김후 묘","c":"시도기념물","nc":"","r":"경상남도","s":"산청군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1657187.jpg"},{"q":"신라 제4대 ○○○이 탄생한 곳이다. 신라의 3대 왕성인 박·석·김 가운데 최초의 석씨 왕인 ○○○에 대하여 다음과 같은 전설이 전하고 있다. 왜국에서 동북쪽으로 1천여 리 떨어져 있는 다파나국 왕비가 임신 7년만에 큰 알을 낳았는데, 이는 좋지 못한 일이라 하여 그 알을 보물과 함께 궤속에 넣어 바다에 띄워 보냈다. 그 궤가 신라 땅에 와 닿았을 때 한 늙은 여자가 발견하여 열어보니 어린아이가 있어 데려가 길렀다.","a":"석탈해왕탄강유허","c":"시도기념물","nc":"","r":"경상북도","s":"경주시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1654530.jpg"},{"q":"고려 말ㆍ조선 초 김문발(金文發,1359~1418)이 세운 정자이다. “부용”은 송(宋)의 주돈이(周敦離)가「애련설(愛蓮設)」에서 연꽃을 꽃 중의 군자라고 칭송하였던 것에서 따온 것이다. 김문발은 고려말과 조선초의 왜구 토벌에 공을 세웠고 전라 감사ㆍ황해도관찰사ㆍ형조 참판 등을 지냈다. 관직에서 물러나 ○○○을 중심으로 여씨(呂氏)의 남전향약(藍田鄕約)과 주자(朱子)의 백록동규약(白鹿洞規約)을 따라 시행하며 풍속의 교화에 힘썼는데 이것이 광주 향약좌목(鄕約座牧)의 유래가 되었다.","a":"부용정","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"남구","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1659608.jpg"},{"q":"이 불상은 오른손과 왼손은 각각 촉지인과 설법인을 맺고 오른발을 위로 하여 結跏趺坐한 ○○○○○이다. 肉髻를 포함한 머리 부분이 像 높이의 1/3 이상을 차지할 정도로 매우 크며, 몸통은 머리에 비하여 좁고 작은 편이다. 服制는 法衣를 오른쪽 어깨에도 살짝 걸치는 右肩偏袒으로 입었고 하체에는 裙을 입었다. 복부 위에 보이는 裙衣 상단은 연꽃잎을 여럿 겹친 모양으로 만들었으며, 왼쪽 무릎 위에는 옷의 끝자락이 몸의 바깥으로 삐치고 있는데 이는 매우 독특한 표현으로 주목할 만하다. 양식적인 특징으로 보아 이 불상의 조성연대는 조선 후기로 추정된다.","a":"상주 상락사 대웅전 목조석가여래좌상","c":"문화유산자료","nc":"","r":"경상북도","s":"상주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663632.jpg"},{"q":"○○○는 안호가 조선 숙종 2년(1676)에 우리나라 주자학의 시조인 안향과 중국 송나라 주자를 모시기 위해 세운 사당이다. 안향(1243∼1306)은 고려시대의 명신이며 학자로 밀직부사 부(孚)의 아들이며, 지금의 경북 영주군 풍기인 흥주의 죽계 상평리에서 태어났다. 원종 1년(1260)에 문과에 급제하여 교서랑이 되었으며, 충렬왕 15년(1289)에는 원나라에 가서 주자서(朱子書)를 손수 베끼고 주자의 초상화를 그려오기도 하였다. 사당 안에는 주자와 안향의 초상화가 놓여 있으며, 용의 모습을 한 향로와 술잔이 있다.","a":"도동묘","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"곡성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661950.jpg"},{"q":"이 ○○○은 전체적으로 본지의 박락과 안료의 변색으로 인해 화면이 칙칙하고 어두운 상태이며, 군데군데 곰팡이가 피어 있고 또한 화면 하단의 화기란 일부도 손실된 상태이다. 화면은 상하로 이분되어 상단에는 합장한 제석천이 천자와 천녀·동자를 거느리고 모두 서서 향우측을 향해 나아가는 모습이며, 하단에는 합장한 위태천이 용왕과 신중 등의 3위와 함께 역시 향우측을 향하여 서 있는 모습이다. 전체적으로 녹색과 적색을 주조색으로 하여 일부 금박을 사용하여 선명함을 살리고 있으나, 안료의 변색으로 원래의 색조보다 훨씬 퇴색된 상태이다.","a":"남해운대암제석신중탱","c":"문화유산자료","nc":"","r":"경상남도","s":"남해군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1666277.jpg"},{"q":"○○○ 안에 위치한 ○○○는 법회나 법당의 주요행사를 열 때 사용하던 누각이다. 부처의 설법이 만세를 누린다는 뜻으로 ○○○라 이름을 지었다. 세운 시기는 알 수 없으나 조선 인조 22년(1644)에 영숙화상이 보수했다고 알려져 있다. 앞면 5칸·옆면 3칸으로 기둥의 높이가 길고 기둥 사이가 넓어 대규모의 건물로 느껴진다. 가운데칸 양쪽 기둥 위에 밖으로는 용머리를, 그 안쪽으로는 용꼬리를 새겨 출입구를 강조했다. 내부 역시, 기둥 위와 그 사이에 꽃모양 받침의 장식이 있어 위엄이 느껴진다.","a":"양산 통도사 만세루","c":"시도유형문화유산","nc":"","r":"경상남도","s":"양산시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641814.jpg"},{"q":"백제의 시조 온조가 졸본부여(卒本扶餘)를 떠나 직산(현 충청남도 천안시 직산면 일대)에 와서 처음 도읍을 정하고 개국하였는데, 직산의 옛 이름이 ○○○이다. 『삼국사기』나 『삼국유사』에는 ‘직○○○○’이라 불려지고 있는데, 이곳이 바로 백제의 첫 도읍지인 것이다. ○○○의 ○○○은 상 정상부를 둘러쌓은 테뫼식 산성으로, 주변의 ○○○성, 사산성과 함께 방어용으로 사용되었을 것으로 추정된다. 산성의 둘레는 950m이고, 성 안의 면적은 5700㎡이다.","a":"천안성거산위례성","c":"시도기념물","nc":"","r":"충청남도","s":"천안시","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1653059.jpg"},{"q":"영덕 ○○○ 마을 내에 있는 ○○○은 호은 남흥수(1813∼1899)가 1847년경 건립하였으며, 1938년에 그의 증손 남대철이 중수하였다고 전해진다. 1950년대까지 대문채, 방앗간, 마굿간이 있었으나 현재는 없어졌다. 이 ○○○은 정면 4칸·측면 6칸의 ㅁ자형 건물로 자연석 기단위에 각주를 세웠다. 대문칸을 중심으로 좌측에 1칸의 방과 우측에 아랫방과 사랑대청이 있다. 우익사는 사랑대청과 연결하여 2칸의 사랑방과 현재 출입문으로 사용하고 있는 1칸의 통래칸으로 구성되어 있다. 사랑방 배면에 벽장과 내부와 통하는 문을 두고 툇마루를 설치하였다.","a":"영덕괴시리영감댁","c":"문화유산자료","nc":"","r":"경상북도","s":"영덕군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663398.jpg"},{"q":"임진왜란 때 공이 컸던 충무공 이순신과 정운, 송희립을 모시기 위해 세운 사당이다. 충무공 이순신(1545∼1598)은 조선 선조 12년(1579) 무과에 급제하였다. 임진왜란이 일어나자 옥포·강포·한산도 등지에서 승리를 거두었다. 정유재란 때 명량에서 대승을 거두었으며 노량진에서 순절하였다. 충장 정운(1543∼1592)은 조선 중기의 무신으로 선조 3년(1570)에 과거에 급제하였다. 임진왜란이 일어나자 이순신 장군의 휘하에서 옥포·당포·한산도 등 여러 해전에서 큰 공을 세웠다. 9월 부산포 해전에서 우부장으로 선봉에서 싸우다가 전사하였다.","a":"충무사","c":"문화유산자료","nc":"","r":"전남광주통합특별시","s":"순천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661979.jpg"},{"q":"신도비란 임금이나 고관의 평생업적을 기록하여 그의 무덤 남동쪽에 세워두는 것으로, 이 비는 조선 중기의 문신인 ○○○ 선생을 기리고 있다. ○○○은 이항복과 김장생의 제자로, 조선 선조 때 승문원에서 처음으로 벼슬을 시작하여 강화유수를 지내었고, 병으로 생을 마칠 때까지 도승지, 호조판서 등의 여러 관직을 맡아 보았다. 광해군 9년(1617)에는 일본에 회답사의 종사관으로 다녀오고, 인조 2년(1642) 이괄의 난이 일어나자 전라절도사로서 커다란 공을 세웠다. 인조 5년(1627) 정묘호란 때에는 병조참판으로 청나라의 사신과 교섭하여 화의를 성립시키기도 하였다.","a":"효민공 이경직 묘역","c":"시도유형문화유산","nc":"","r":"서울특별시","s":"관악구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636288.jpg"},{"q":"1876년에 제작된 이 ○○○○는 원래 무량수전(無量壽殿)에 안치되었던 불화로서, 현재는 ○○○에 모셔져 있다. 화면에는 지장보살좌상을 중심으로 十王과 그 권속이 함께 그려져 있다. 중앙의 지장보살삼존 좌우로 왼쪽에는 홀수의 시왕과 판관, 사자, 옥졸 등을, 오른쪽에는 짝수의 시왕과 판관, 사자, 옥졸 등을 배치한 형태이다. 여기에 화면 상단의 지장보살 주위로 6보살이 좌우 대칭으로 첨가되어 있다. 문양의 생략, 음영이 심한 옷주름 표현, 적색, 녹색, 청색, 황색, 흰색 등의 두드러진 채색 등에서 19세기 말경의 양식적 특징을 잘 나타내고 있다.","a":"문경대승사명부전지장탱화","c":"문화유산자료","nc":"","r":"경상북도","s":"문경시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663643.jpg"},{"q":"동헌은 조선시대의 지방 관아건물로 고을의 수령이 일반 행정업무와 재판 등 공적일 일을 하던 곳이다. 흥선대원군은 정권을 잡은 후 관청의 위엄을 세우기 위하여 전국에 걸쳐 관청건물을 정비하였다. 그 일환으로 고종 8년(1871) 정기화 군수가 세웠다. 해방 후 홍산지서로 사용하다가 1984년에 부여군에서 현재의 모습으로 보수하였다. 앞면 7칸·옆면 2칸의 크기로 중앙에 대청마루를 두고 좌우에 각각 크기가 다른 온돌방을 설치했다. 지붕은 옆모습이 여덟 팔(八)자 모양인 팔작지붕으로 관청의 위엄을 나타내고 있다.","a":"홍산동헌","c":"시도유형문화유산","nc":"","r":"충청남도","s":"부여군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1639238.jpg"},{"q":"○○리 마을의 밭을 둘러 싸고 있는 흙으로 쌓은 성과 군탄리 마을의 옛 풍전역터에 놓여 있는 직육면체의 석조물이다. 점토를 이용해 직사각형으로 쌓아올린 이 성은 우리나라에서는 보기 드물게 평탄한 곳에 설치되어 있다. 원래는 제법 큰 규모의 성이었을 것이나, 지금은 3면의 성벽이 없어지고 한쪽면의 성벽만 남아있다. 성안에는 당시의 사람들이 살았던 집터 흔적이 남아 있고, 무늬없는 토기조각이나 석기 등이 발견되고 있다.","a":"철원 갈말읍 토성","c":"시도기념물","nc":"","r":"강원특별자치도","s":"철원군","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1647812.jpg"},{"q":"○○○은 남명 조식(1501~1572)이 1548년에 건립한 정자이다. 조식은 48세 때 ○○군에 ○○○과 계복당을 짓고 학문을 연구하면서 제자들을 가르쳤다. ○○○이란 장자에 나오는 ‘시거이용현, 연묵이뢰성:시동처럼 가만히 있다가 때가 되면 용처럼 나타나고, 깊은 연못과 같이 묵묵히 있다가 때가 되면 우뢰처럼 소리친다.’에서 따 온 것이다. 정자는 앞면 5칸·옆면 2칸 규모로, 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"합천 뇌룡정","c":"문화유산자료","nc":"","r":"경상남도","s":"합천군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664133.jpg"},{"q":"고려 후기의 문신이자 포은 정몽주의 제자인 복애(伏涯) 범새동(范世東)의 묘지이다. 고려 공민왕 18년(1369)에 과거에 급제하여 덕녕부윤, 간의대부 등의 벼슬을 지냈으며, 성리학을 깊이 연구하여『화해사전』,『동방연원록』등의 책을 펴냈다. 조선 왕조의 개창을 반대하며 고향인 나주(현 광주광역시 광산구 복만동)에 은거하였으며, 조선 태종이 여러 차례 벼슬을 권했으나 끝내 사양하였다. 죽은 뒤 후덕군(厚德君)에 봉해지고 문충(文忠)의 시호를 받았다. 묘역 안에는 조선 초기에 만들어진 묘비와 문인석이 있다.","a":"범세동선생묘","c":"시도기념물","nc":"","r":"전남광주통합특별시","s":"광산구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645770.jpg"},{"q":"입석사에 있는 탑으로 무너져 있던 것을 세워 둔 것인데, 2기의 석탑 부재가 섞여 있는 듯 하다. 부재들은 두툼하고 네모난 연꽃받침이 2개, 얇은 연꽃받침이 1개, 각 면에 기둥 모양을 새긴 탑신(塔身)의 몸돌이 3개, 네모난 판돌이 4개이다. 연꽃무늬 조각이나 탑신의 몸돌을 다듬은 솜씨로 보아 고려시대 전기의 작품으로 추정된다. 조선 태종(재위 1400∼1418)이 왕위에 오른 후 어린 시절의 스승 운곡 원천석을 자주 불렀으나 응하지 않고 치악산에 들어가 은둔생활을 하며 나타나지 않으니, 그를 생각하며 이 탑을 세우게 되었다는 이야기가 함께 전해 내려온다.","a":"입석사석탑","c":"문화유산자료","nc":"","r":"강원특별자치도","s":"원주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660346.jpg"},{"q":"○○○는 전라남도 장흥군 가지산에 있는 절로, 860년 신라의 승려 체징에 의해 창건되었다. 이 책은 ○○○○○의 배 안에 넣어서 보관하던 유물 가운데 하나로, 모두 41종 58책이다. 금강경과 법화경을 비롯한 경전류가 주종을 이루고 있는 것이 특징인데, 금강경은 ‘금강반야바라밀경’의 줄임말로 반야심경과 더불어 조계종의 근본 경전으로 많이 읽힌다. 또 ‘묘법연화경’이라 불리는 법화경은 천태종의 근본 경전으로, 화엄경과 함께 한국 불교사상 확립에 크게 영향을 미친 불경이다.","a":"보림사사천왕상복장경전불서","c":"시도유형문화유산","nc":"","r":"전남광주통합특별시","s":"장흥군","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/2020022814451400.jpg"},{"q":"○○○의 옛 터에 남아 있는 것으로, 스님들이 사용하는 물을 담아두던 도구이다. 사찰 부엌에서 물탱크로 사용했던 것으로 보이며, 현재 ○○○의 옛 터인 마을 안길의 땅속에 매몰된 상태로 보존하고 있다. 그 크기가 거대한 것으로 알려져 절에서 쓰던 둘레 9.4m의 ○○○ 철확(철솥)과 함께 당시 사찰의 규모를 짐작할 수 있는 유물이다. 또한 원래의 자리를 지키고 있어 ○○○터의 역사를 살피는데에도 좋은 자료가 된다.","a":"개태사지석조","c":"문화유산자료","nc":"","r":"충청남도","s":"논산시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661323.jpg"},{"q":"○○○를 건립하게 된 이유, 위치 등 ○○○에 대한 여러 글들을 모은 것으로 김상집이 지은 것이다. 이 책판의 간행연대는 알 수 없으나, ○○○당의 위치와 건립하게 된 배경 및 취지 등 포충사의 내력이 수록되어 있으며, 모두 7권으로 되어 있다. 당시 대문호였던 교산 허균(1569∼1618)에게 이 간행의 서문을 썼고 발문은 승려 뇌묵당이 광해군 4년(1612)에 썼다. 이 책판은 ○○○의 내력 및 사명대사의 활동과 전공을 알 수 있는 직접적인 자료로 임진왜란에 대한 역사기록을 보완해주는 자료로 평가된다.","a":"밀양 표충사 제영록 목판","c":"시도유형문화유산","nc":"","r":"경상남도","s":"밀양시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1642123.jpg"},{"q":"부산대학교박물관 소장 ○○○○○은 화면에 배경 없이 책을 중심으로 문방구와 도자기, 고동기(古銅器), 소과(小菓) 등의 기물(器物)을 배치한 나열식 ○○○그림을 본으로 하여 비단에 전통 ○○로 제작한 8폭의 ○○이다. ○○○○은 각 폭마다 서가 없이 책과 여러 종류의 기물(器物)이 상하에 배열된 밑그림에 수를 놓았다. 8폭 ○○으로 장황(裝潢·粧潢)[비단이나 두꺼운 종이를 발라서 책이나 화첩(畫帖), 족자 따위를 꾸미어 만든 것]되어 있다. 제8폭을 제외하면 각 폭 상단에 서적들이 여러 겹으로 쌓여 있고 그 아래에 여러 종류의 기물들이 나열되어 있다.","a":"자수 책거리 병풍","c":"시도유형문화유산","nc":"","r":"부산광역시","s":"금정구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1636741.jpg"},{"q":"처사 박인택을 추모하기 위하여 그 후손들이 지은 사당이다. 언제 지었는지 정확한 연도는 알 수 없고, 처음에는 마을에 소규모의 초가를 지어 제사를 지냈다. 그 뒤 현 위치로 옮겨 짓고 2차례에 걸쳐 보수를 하였다고 한다. 전하는 바에 따르면, 후손이 병에 걸려 갖가지 약으로도 고치지 못하였는데 꿈에 박인택이 나타나 사당을 짓고 공을 드리면 나을 것이라 하여 그렇게 하자 병이 바로 나았다고 한다. 처사 박인택은 조선 중기에 추자도로 유배와 불교적 생활을 하면서, 주민들의 병을 치료해 주고 불교 교리도 가르치면서 살았다고 한다.","a":"추자처사각","c":"시도유형문화유산","nc":"","r":"제주특별자치도","s":"제주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1643282.jpg"},{"q":"○○○ 안에서 군사가 주둔하던 중군영(中軍營)의 문이었으나 광복 이후 8·15해방을 기리는 뜻으로 ○○○라 불렀다. ○○○는 원래 ○○○의 북문인 공북루 옆에 있던 것을 현 위치로 옮기고 웅심각이라 불렀는데, 1946년에 백범 김구와 성재 이시영이 이곳에 와서 나라를 다시 찾았다는 뜻을 기리고자 고쳐 부르게 되었다고 한다. 앞면 3칸·옆면 2칸 규모의 2층 누각으로 모든 면이 개방되어 있으며, 왼쪽에는 오르내릴 수 있도록 층계를 만들어 두었다. 지붕은 옆에서 볼 때 여덟 팔(八)자 모양인 팔작지붕으로 꾸몄다.","a":"공산성광복루","c":"문화유산자료","nc":"","r":"충청남도","s":"공주시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1660948.jpg"},{"q":"창영초등학교는 인천 최초의 공립학교로 1907년에 세워졌으며, 당시 이름은 인천공립보통학교였다. 1933년 인천제일공립보통학교, 1938년 인천창영공립심상소학교, 1941년 창영공립국민학교, 광복 후 창영국민학교로 이름이 바뀌어 오늘에 이르고 있으며, 3·1운동 당시 인천지역 만세운동의 진원지이기도 한 전통 깊은 곳이기도 하다. 옛 학교 건물은 1924년에 세운 것으로, 一자형의 구성이다. 벽체 윗부분은 화강석으로 아치(Arch)형을 이루고 있고, 현관은 근세풍 양식을 띤 무지개 모양으로 꾸몄다.","a":"인천창영초등학교 구 교사","c":"시도유형문화유산","nc":"","r":"인천광역시","s":"제물포구","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1637023.jpg"},{"q":"○○은 미역바위라는 뜻이다. 이곳 판지마을 바다 속에 있는 자연바위이며, ‘양반바위’, ‘박윤웅(朴允雄)바위’ 등으로 불려지기도 한다. 1937년에 간행된 『흥려승람(興麗勝覽)』에 의하면 박윤웅은 나말여초 당시 왕건이 고려를 세우고 지방의 호족세력을 정비할 때 협조하였다. 그로 인해 울산은 흥려부로 승격되고, 박윤웅은 그 공훈을 인정받아 정5품 흥려백에 봉해졌다고 한다. ‘흥려’라는 말은 고려(高麗)를 흥성(興盛)하게 하였다는 뜻이다.","a":"곽암","c":"시도기념물","nc":"","r":"울산광역시","s":"북구","i":"http://www.khs.go.kr/unisearch/images/monument/thumb/1645914.jpg"},{"q":"조선 중기의 무신인 ○○○ 장군의 묘이다. 장군의 자는 자방(子房), 평택사람으로 부사 임식의 둘째 아들이며 임득인의 동생이다. 선조 29년(1596) 이몽학이 충청도 홍산에서 반란을 일으켜 인접한 임천·정산·청양·대흥 등을 함락하고 홍주성을 침범하자 홍주목사 홍가신을 도와 난을 평정하였다. 이 공로로 1604년 청난공신 3등에 기록되고 평성군으로 봉해졌다. 그뒤 충청수우후를 거쳐 광해군 1년(1609) 경상우도 병마절도사가 되었다. 묘소는 홍성군 서부면 판교리 청룡산에 있다.","a":"홍성임득의장군묘","c":"문화유산자료","nc":"","r":"충청남도","s":"홍성군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661495.jpg"},{"q":"정우당 조치우 선생의 제사를 모시는 사당과 왕이 선생에게 내린 옥으로 만든 비이다. 조치우(1459∼1529)는 조선 성종 때의 문신으로, 성종 25년(1494) 별사문과에 급제하여 예문관 검열을 거쳐 성균관전적이 되어 성종실록편찬에 참여하였다. 중종반정 이후 장령을 지내고 대구 부사를 지내면서 어진 다스림을 펼쳐 칭송을 받았다. 사옹원정에 임명되었으나 어머니의 봉양을 위해 이를 거절하였고, 어머니의 상 도중 그도 생을 마치었다. 그가 죽은 후 조정에서는 옥비 2기를 하사하여 그의 청렴결백과 효행의 덕을 표창하였다.","a":"유후재및옥비","c":"문화유산자료","nc":"","r":"경상북도","s":"영천시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662563.jpg"},{"q":"○○○은 언제 지었는지 정확한 기록이 없으나, ○○○ 양돈(1461∼1512)의 호로 미루어 그가 생존시에 지은 것으로 추정한다. 양돈은 성종 9년(1498) 사마시에 합격하였으나 무오사화로 봉현리에 낙향하였다. 그의 문장과 덕행은 뛰어나 당시 모범이 되었고, 남효온의 추천으로 조정에서 벼슬을 내렸으나 이를 거부하고 조용히 세상을 살았다. 원래 정자는 삼계면 후천리 광제 마을에 있었으나, 고종 9년(1872)에 지금 있는 자리로 옮겨 지었다. ○○○은 앞면 3칸·옆면 2칸 규모이며, 정자 한 가운데에 온돌방이 하나 있는 점이 특징이다.","a":"광제정","c":"문화유산자료","nc":"","r":"전북특별자치도","s":"임실군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1661763.jpg"},{"q":"○○○ 마을에 자리하고 있는 탑으로, 계단식으로 이루어진 독특한 모습이다. 평면이 정사각형을 이루고 있는데, 각 층마다 비교적 크고 반듯한 판돌 네 장으로 면을 이루게 한 뒤, 그 안을 막돌로 채워넣는 방식으로 되어 있다. 위층으로 올라갈수록 점점 줄어들어 5층으로 되어 있으나, 원래의 형태인지는 확인할 수 없다. 고려시대나 조선시대 전기에 세운 것으로 추측되며, 보기드문 양식을 보여주고 있어 석탑의 여러 형태를 연구하는데 좋은 자료가 되고 있다.","a":"안동석탑리방단형적석탑","c":"문화유산자료","nc":"","r":"경상북도","s":"안동시","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1663180.jpg"},{"q":"향교는 공자와 여러 성현께 제사를 지내고 지방민의 교육과 교화를 위해 나라에서 세운 지방의 교육기관이다. 조선 성종 15년(1484) 월변동에 처음 지었고, 숙종(재위 1674∼1720)대에 고성리 성서동으로 옮겼다가 고종 9년(1872)에 지금 있는 자리로 옮긴 것이다. 그 뒤 한국전쟁으로 모두 불타 없어졌는데 1979년 명륜당을 복원하여 오늘에 이르고 있다. ○○○은 공자를 비롯하여 중국과 우리나라 성현의 위패를 모신 곳이다. 앞면 5칸·옆면 3칸의 규모이며, 지붕은 옆면에서 볼 때 사람 인(人)자 모양인 맞배지붕으로 소박한 모습이다.","a":"울진향교 대성전","c":"문화유산자료","nc":"","r":"경상북도","s":"울진군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1662713.jpg"},{"q":"비석을 보호하기 위해 세운 건물이다. 옛날 하동으로 가는 길목인 ○○성 북쪽 성벽 밑에 있으며, 이 길목도 비각거리, 또는 빗집거리라고 부른다. 비각의 규모는 앞면 2칸·옆면 1칸이고, 옆면이 여덟 팔(八)자 모양과 비슷한 팔작지붕의 1층 목조 건축물이다. 안쪽 2개의 비는 광무 5년(1901)과 1907년에 각각 세워진 것으로, 고종황제 당시에 ○○성 안에 살고 있던 사람들이 질병이나 어려움을 당했을 때 개인 재산을 털어 그들을 도와준 연안 차씨와 아들 김정식 모자의 은혜를 기리기 위해 마을 사람들이 세운 시혜불망비이다.","a":"진주 김해김씨비각","c":"시도유형문화유산","nc":"","r":"경상남도","s":"진주시","i":"http://www.khs.go.kr/unisearch/images/tangible_cult_prop/thumb/1641747.jpg"},{"q":"○○○은 조선 현종 5년(1664)에 성리학자인 송지일 선생이 선비들과 더불어 학문을 연구하기 위해 자신의 호를 따서 지은 정자로, 낙동강변의 절벽 위에 자리잡고 있다. 임진왜란(1592) 때 파손되어서 여러 번 고쳐 지었다. 건물은 앞면·옆면 2칸 규모이며 지붕은 옆면에서 볼 때 여덟 팔(八)자 모양인 팔작지붕이다. 앞쪽은 마루로 꾸몄고, 뒤쪽에는 방을 두었다.","a":"함안 광심정","c":"문화유산자료","nc":"","r":"경상남도","s":"함안군","i":"http://www.khs.go.kr/unisearch/images/cultural_material/thumb/1664355.jpg"}]);